// swap from each pitcher's season-overall HR/9 to their real HR/9 allowed
// specifically against that batter hand (pitcherStatcast[pid].hr9ByHand, synced
// by sync-pitcher-zone-hr.mjs from real outs-by-hand/HR-by-hand reconstruction --
// the only real per-hand AGGREGATE stat this repo has for pitchers; AVG/wOBA/WHIP/
// ISO/SLG/FIP have no hand-split source, so those columns stay season-overall
// regardless of this filter).
let prHandFilter = 'all';
const lineupCache = {};
let repoLineupsData = null;
let repoLineupsLoaded = false;
const lineupMeta  = {}; // pitcherId -> {pitcherName, gamePk, side, oppTeamId, pitcherHr9, pitcherIp, teamAbbr, oppAbbr}
// Production stability patch: normalize pitcher ids and prevent stale lineup requests
// from overwriting an actively opened Batting Lineup & Matchup panel.
const lineupLoading = new Set();
const lineupRequestTokens = {};
// Same "last call wins, a stale in-flight response gets discarded" token guard as
// lineupRequestTokens above -- renderPitcherDriversSection can legitimately be
// triggered twice in close succession for the same pitcher (once chained off the
// Arsenal section's own Promise.all, once by pollForLineupThenRefreshMatchup once
// the real lineup lands), and the two calls don't resolve in a guaranteed order.
const driversRenderTokens = {};
const normalizePitcherId = (id) => String(id);

// Which pitcher's lineup is currently showing in the pop-out modal, if any —
// the whole Pitcher Report table (including this panel's own DOM node) gets
// rebuilt on every live-score refresh, so this is what lets a re-render pick
// the open modal back up instead of leaving it stuck on stale content.
let openLineupModalPid = null;

async function loadRepoLineups() {
  if (repoLineupsLoaded) return repoLineupsData;
  repoLineupsLoaded = true;
  try {
    repoLineupsData = await drFetchDailyJSON(`data/lineups.json`);
    return repoLineupsData;
  } catch (e) {
    repoLineupsData = null;
    return null;
  }
}

function _normalizeLineupTeam(team = {}, game = {}) {
  if (!team?.lineup?.length) return null;
  return {
    lineup: team.lineup.map(b => ({
      name: b.name || b.fullName || '–',
      id: b.id || b.playerId || null,
      pos: b.pos || b.position || '–',
      stats: b.stats || {},
      last10HR: b.last10HR ?? null,
      todayHR: b.todayHR || 0,
      confirmed: team.confirmed === true,
      source: team.source || game.source || 'repo-lineups'
    })),
    teamAbbr: team.abbr || team.teamAbbr || '',
    source: team.source || game.source || 'repo-lineups',
    confirmed: team.confirmed === true,
    confirmedAt: team.confirmedAt || null,
    updatedAt: repoLineupsData?.generatedAt || game.updatedAt || null
  };
}

function getRepoLineupForGame(gamePk, teamSide) {
  const manualGame = manualLineupsData?.games?.[String(gamePk)];
  const manualTeam = manualGame?.teams?.[teamSide];
  const manual = _normalizeLineupTeam(manualTeam, manualGame || {});
  if (manual?.lineup?.length) return { ...manual, source: manual.source || 'manual-upload', confirmed: manual.confirmed === true };

  const game = repoLineupsData?.games?.[String(gamePk)];
  const team = game?.teams?.[teamSide];
  return _normalizeLineupTeam(team, game || {});
}

// Real "is this batter actually in today's lineup" badge for board rows (HR
// Threats, Hits/RBI/TB/SB/H+R+RBI) -- reads the same repo-synced lineups.json
// getRepoLineupForGame already serves the pitcher-matchup panel from, no new
// fetch. Batter's own side is derivable from teamAbbr vs the game's homeAbbr
// already present on every board row. Returns '' (badge hidden) when there's
// no real lineup data yet, rather than guessing.
function lineupBadgeHTML(gamePk, teamAbbr, homeAbbr) {
  if (gamePk == null || !teamAbbr) return '';
  const side = teamAbbr === homeAbbr ? 'home' : 'away';
  const entry = getRepoLineupForGame(gamePk, side);
  if (!entry || !entry.lineup || !entry.lineup.length) return '';
  return entry.confirmed
    ? '<span class="dr-row-lineup-badge confirmed">✅ Lineup Confirmed</span>'
    : '<span class="dr-row-lineup-badge expected">🔮 Expected Lineup</span>';
}

let manualLineupsData = null;
try {
  manualLineupsData = JSON.parse(localStorage.getItem('drConfirmedLineups') || 'null');
} catch { manualLineupsData = null; }

async function loadPitcherReport() {
  const el = document.getElementById('pr-content');
  if (el) el.innerHTML = drSkeletonRowsHTML(4, 'Loading pitcher report…');
  try {
    const today = new Date().toLocaleDateString('en-CA', {timeZone:'America/Chicago'});
    await loadStatcastHotHitters();
    await loadParkFactors().catch(() => {});
    // Whole-file static fetch (cheap, cached), preloaded here so the main table row
    // (not just the pop-out modal, which already awaited this separately) can show a
    // real pitcher Trend Indicator badge before a user ever opens a single dashboard.
    await loadPitcherRolling().catch(() => {});
    const games = await getTodaySchedule('team,probablePitcher');
    if (!games.length) { el.innerHTML = '<div class="mu-empty">No games scheduled today.</div>'; return; }

    const pitchers = [];
    games.forEach(g => {
      const dt = new Date(g.gameDate);
      const t = dt.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Chicago'});
      const state = g.status.abstractGameState;
      const isLive = state==='Live' || g.status.detailedState==='In Progress';
      const isFinal = state==='Final';
      const timeLabel = isLive ? '● LIVE' : isFinal ? 'FINAL' : t;
      const timeColor = isLive ? 'var(--live)' : isFinal ? 'var(--muted)' : 'var(--text)';
      const gameTimestamp = dt.getTime(); // numeric ms for sorting
      [['away','home'],['home','away']].forEach(([side,opp]) => {
        const p = g.teams[side].probablePitcher;
        if (p) pitchers.push({
          id: p.id, name: p.fullName,
          teamAbbr: g.teams[side].team.abbreviation,
          oppAbbr: g.teams[opp].team.abbreviation,
          oppTeamId: g.teams[opp].team.id,
          timeLabel, timeColor, gameTimestamp,
          gamePk: g.gamePk,
          side,
          mlbLink: `https://www.mlb.com/gameday/${g.gamePk}`
        });
      });
    });

    if (!pitchers.length) { el.innerHTML = '<div class="mu-empty">No probable pitchers announced yet.</div>'; return; }

    const statsArr = await Promise.all(pitchers.map(async p => {
      try {
        const d = await fetchJSON(`https://diamondreport.app/api/v1/people/${p.id}?hydrate=stats(group=pitching,type=season,season=2026)`);
        // pitchHand is a top-level field on the person object this same call already
        // returns (no hydrate needed for it) -- captured here so the Matchup scouting
        // table below can show each opposing batter's real split against THIS
        // pitcher's actual throwing hand, zero extra requests.
        return { stat: d.people?.[0]?.stats?.[0]?.splits?.[0]?.stat || {}, hand: handCode(d.people?.[0], 'pitchHand') };
      } catch { return { stat: {}, hand: null }; }
    }));

    function f(v, dec=2) {
      if (v==null||v==='') return null;
      const n=parseFloat(v); return isNaN(n)?null:+n.toFixed(dec);
    }
    function fI(v) { const n=parseInt(v); return isNaN(n)?null:n; }

    prRows = pitchers.map((p, i) => {
      const s = statsArr[i].stat;
      const pitcherHand = statsArr[i].hand;
      const iso = (s.slg!=null&&s.avg!=null) ? f(parseFloat(s.slg)-parseFloat(s.avg),3) : null;
      const totalK = parseInt(s.strikeOuts) || 0;
      const gs = parseInt(s.gamesStarted) || parseInt(s.gamesPitched) || 1;
      const kpg = gs > 0 ? (totalK / gs).toFixed(1) : null;
      const k9 = parseFloat(s.strikeoutsPer9Inn) || 8;
      // Baseline K prop: K/9 × projected IP (avg 5.5) / 9, rounded to nearest .5
      const projIP = 5.5;
      const projK = Math.round((k9 * projIP / 9) * 2) / 2;
      // MLB Stats API's pitching stat object has no `fip` field — FIP is a sabermetric
      // stat the API doesn't compute, so reading s.fip directly always returned
      // undefined and this column silently rendered "–" for every pitcher. Computed
      // here from the standard formula instead (using the commonly-cited ~3.10
      // constant since a real per-season league constant isn't available from this
      // endpoint).
      const rawIpForFip = parseFloat(s.inningsPitched) || 0;
      const fipCalc = rawIpForFip > 0
        ? ((13*(parseInt(s.homeRuns)||0) + 3*((parseInt(s.baseOnBalls)||0)+(parseInt(s.hitBatsmen)||0)) - 2*totalK) / rawIpForFip) + 3.10
        : null;
      return {
        pitcher: p,
        gameTime: p.gameTimestamp,
        ip: f(s.inningsPitched,1), bf: fI(s.battersFaced),
        fip: f(fipCalc), avg: f(s.avg,3), woba: f(s.obp,3),
        whip: f(s.whip), iso, slg: f(s.slg,3),
        hr9: f(s.homeRunsPer9), tb: fI(s.totalBases),
        kpg, kprop: projK,
        wl: (s.wins!=null)?`${s.wins}-${s.losses}`:'–',
        era: f(s.era),
        rawHr9: parseFloat(s.homeRunsPer9) || 0,
        rawIp: parseFloat(s.inningsPitched) || 0,
        rawK9: k9,
        gamesStarted: gs,
        pitcherHand,
      };
    });

    // Default sort by HR/9 descending -- surfaces the biggest real home-run
    // risks in today's starting pitchers first, matching every other HR-focused
    // board's own default (HR Threats sorts by HR probability, not game time).
    prSortCol = 'hr9';
    prSortDir = -1;

    renderPRTable();
    loadKsToday();
  } catch(e) {
    // Passes {force:true} because window.loadPitcherReport gets wrapped later
    // in this file (prod-v9-performance-orchestrator's coalesce('loadPitcherReport',
    // 'matchups')) with a guard that silently no-ops any call while paneId
    // 'matchups' isn't the active .section -- a stale check from an older UI
    // layout (Pitcher Report now lives inside #props as a .gamepick-pane, not
    // its own top-level #matchups section, so that check can never pass).
    // {force:true} is the same bypass loadGameProps's own retry already
    // relies on for the identical reason.
    drShowError(document.getElementById('pr-content'), "Couldn't load the pitcher report.", () => loadPitcherReport({ force: true }));
  }
}

// K O/U lookup: pitcherId -> ouLine (populated by renderPRTable)
const pitcherOULines = {};


function isPRMobileTabletView() {
  return window.matchMedia && window.matchMedia('(max-width: 1024px)').matches;
}

// Real HR/9 allowed specifically against batter hand `hand` ('R'/'L'), or the
// season-overall HR/9 already on the row when hand is 'all'. Null (never a
// fabricated number) when that pitcher's real hand-split sample hasn't cleared
// sync-pitcher-zone-hr.mjs's own minimum-IP floor yet.
function prHr9ForRow(r, hand) {
  if (hand !== 'R' && hand !== 'L') return r.hr9;
  const pid = normalizePitcherId(r.pitcher?.id);
  return pitcherStatcast[String(pid)]?.hr9ByHand?.[hand]?.hr9 ?? null;
}

function getSortedPRRowsForCurrentSort() {
  return [...prRows].sort((a,b) => {
    if (!prSortCol) return 0;
    const av = prSortCol === 'hr9' ? prHr9ForRow(a, prHandFilter) : a[prSortCol];
    const bv = prSortCol === 'hr9' ? prHr9ForRow(b, prHandFilter) : b[prSortCol];
    if (av==null&&bv==null) return 0;
    if (av==null) return 1; if (bv==null) return -1;
    return (av-bv)*prSortDir;
  });
}

// ── Pitcher Analytics Dashboard (roadmap 7.1) ───────────────────────────
// Organizes the pitcher pop-out into five named sections instead of one long
// stack, per the roadmap's explicit ask -- Arsenal (pitcherArsenalPanelHTML,
// unchanged entry point), Performance (real L10/L15/L20 form + today's
// expected K/IP), Matchup (the existing real opposing-lineup panel, plus a
// real lineup-strength read once it loads), Environment (real park factor +
// live weather for today's specific game), Support (his own team's real
// bullpen fatigue tier). Every section identifies its own period/source in
// its subtext per the acceptance criteria, and degrades to an honest empty
// state -- never a fabricated number -- when a pitcher's situation (opener,
// bullpen game, not yet enough starts logged) doesn't have real data behind
// a given section.
const PITCHER_DASHBOARD_SECTION_META = {
  drivers:     { icon: '🤖', title: 'MATCHUP DRIVERS & ANALYSIS' },
  arsenal:     { icon: '🧪', title: 'ARSENAL' },
  performance: { icon: '📈', title: 'PERFORMANCE' },
  matchup:     { icon: '⚔️', title: 'MATCHUP' },
  environment: { icon: '🌤️', title: 'ENVIRONMENT' },
  support:     { icon: '🛟', title: 'SUPPORT' },
};
function pitcherDashboardSectionWrap(key, contentEl, subtext) {
  const meta = PITCHER_DASHBOARD_SECTION_META[key];
  const wrap = document.createElement('div');
  wrap.className = 'dr-pdash-section';
  wrap.setAttribute('data-pdash-section', key);
  const head = document.createElement('div');
  head.className = 'dr-pdash-section-head';
  head.innerHTML = `<span class="dr-pdash-section-icon">${meta.icon}</span><span class="dr-pdash-section-title">${meta.title}</span>` +
    (subtext ? `<span class="dr-pdash-section-sub" id="pdash-sub-${key}-${contentEl.id || ''}">${drEscAttr(subtext)}</span>` : '');
  wrap.appendChild(head);
  wrap.appendChild(contentEl);
  return wrap;
}

// Opposing lineup's average real season K rate, read from whatever's already
// in lineupCache at call time (the lineup fetch this same modal-open kicks
// off) rather than a second network round trip. If the lineup hasn't
// resolved yet, falls back to the league-average 22% -- same fallback the K
// Props board's own boxscore-based version already uses when data isn't
// available -- and gets one real refresh below once the lineup lands.
function opponentKPctForPid(pid, meta) {
  const cacheKey = `${meta.gamePk}-${meta.side}`;
  const lineup = lineupCache[cacheKey]?.lineup || [];
  const kpcts = lineup.map(b => {
    const s = b.stats || {};
    const so = parseInt(s.strikeOuts), pa = parseInt(s.plateAppearances);
    return (so > 0 && pa > 0) ? so / pa : null;
  }).filter(v => v != null);
  if (!kpcts.length) return 0.22;
  return kpcts.reduce((a, b) => a + b, 0) / kpcts.length;
}

// L10/L15/L20 rate-stat trend, reusing the exact recentPitchingForm() the K
// Props/Diamond Report Pick models already call at N=5 -- just called at
// three more window sizes here, cached per (pid, N) for 5 minutes so
// re-opening the same pitcher's modal doesn't re-fetch. A pitcher with fewer
// starts than a given window (rookie, midseason call-up) shows "–" for that
// column rather than a fabricated number. Season baseline is read straight
// out of prRows (already fetched for the table this modal was opened from),
// no extra request.
async function renderPitcherPerformanceSection(pid, meta, wrap) {
  const row = prRows.find(r => normalizePitcherId(r.pitcher.id) === pid) || null;
  const windows = [10, 15, 20];
  const forms = await Promise.all(windows.map(w => recentPitchingForm(pid, w).catch(() => null)));
  if (!wrap.isConnected) return; // modal closed/reopened for a different pitcher while these were in flight
  const seasonEra = row?.era, seasonWhip = row?.whip, seasonK9 = row?.rawK9;

  if (!forms.some(Boolean) && seasonEra == null) {
    wrap.innerHTML = `<div class="mu-empty" style="color:var(--muted)">No recent-start data available yet for ${drEscAttr(meta.pitcherName || 'this pitcher')}.</div>`;
    return;
  }

  function trendCell(val, seasonVal, dec, lowerIsBetter) {
    if (val == null) return `<td class="num"><span style="color:var(--muted)">–</span></td>`;
    let style = '';
    if (seasonVal != null) {
      const delta = val - seasonVal;
      const meaningfulThreshold = dec === 1 ? 0.3 : 0.15; // K/9 noise floor is coarser than ERA/WHIP's
      if (Math.abs(delta) >= meaningfulThreshold) {
        const better = lowerIsBetter ? delta < 0 : delta > 0;
        style = ` style="color:${better ? 'var(--green)' : '#f4a261'};font-weight:700"`;
      }
    }
    return `<td class="num"${style}>${val.toFixed(dec)}</td>`;
  }

  const rateRows = [
    { label: 'ERA',  dec: 2, lowerIsBetter: true,  season: seasonEra,  vals: forms.map(f => f?.era) },
    { label: 'WHIP', dec: 2, lowerIsBetter: true,  season: seasonWhip, vals: forms.map(f => f?.whip) },
    { label: 'K/9',  dec: 1, lowerIsBetter: false, season: seasonK9,   vals: forms.map(f => f?.k9) },
  ];
  const tableRows = rateRows.map(r => `<tr><td><strong>${r.label}</strong></td><td class="num">${r.season != null ? r.season.toFixed(r.dec) : '–'}</td>${windows.map((w, i) => trendCell(r.vals[i], r.season, r.dec, r.lowerIsBetter)).join('')}</tr>`).join('');
  const startsFound = forms.map((f, i) => f ? `L${windows[i]} (${f.starts})` : null).filter(Boolean).join(', ');

  const oppKpct = opponentKPctForPid(pid, meta);
  const expected = row ? pitcherExpectedKAndIP(seasonK9 ?? 8, row.rawIp ?? 0, row.gamesStarted ?? 1, oppKpct) : null;

  wrap.innerHTML = `
    <div class="dr1041-table-wrap"><table class="dr1041-pitch-table">
      <thead><tr><th>Rate</th><th>2026 Season</th><th>Last 10</th><th>Last 15</th><th>Last 20</th></tr></thead>
      <tbody>${tableRows}</tbody>
    </table></div>
    <div class="zone-note" style="margin-top:8px">${startsFound ? `Real starts logged per window: ${startsFound}. ` : ''}Green = trending better than his season baseline over that window; orange = trending worse; muted/– = not enough recent starts logged yet for that window.</div>
    ${expected ? `<div class="dr-pdash-expected"><div class="dr-pdash-expected-stat"><strong>${expected.projIP.toFixed(1)}</strong><span>Expected IP</span></div><div class="dr-pdash-expected-stat"><strong>${expected.projK.toFixed(1)}</strong><span>Expected K</span></div><span class="zone-note">Today's projection vs ${meta.oppAbbr || 'the opponent'} — same model as the K Props board.</span></div>` : ''}
  `;
}

async function renderPitcherEnvironmentSection(meta, wrap) {
  await loadParkFactors().catch(() => {});
  const homeAbbr = meta.side === 'home' ? meta.teamAbbr : meta.oppAbbr;
  const awayAbbr = meta.side === 'home' ? meta.oppAbbr : meta.teamAbbr;
  const parkIdx = homeAbbr ? parkFactors[homeAbbr] : null;
  const weather = homeAbbr ? await fetchGameWeather(homeAbbr, awayAbbr, meta.gameTimestamp).catch(() => null) : null;

  const parkRow = parkIdx != null
    ? `<div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Park HR Factor</span><span class="dr-pdash-env-value" style="color:${parkIdx >= 110 ? '#f4a261' : parkIdx <= 92 ? 'var(--green)' : 'var(--text)'}">${parkIdx >= 100 ? '+' : ''}${(parkIdx - 100)}% ${parkIdx >= 110 ? '(Hitter-Friendly)' : parkIdx <= 92 ? '(Pitcher-Friendly)' : '(Neutral)'}</span></div>`
    : `<div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Park HR Factor</span><span class="dr-pdash-env-value" style="color:var(--muted)">Not available for ${drEscAttr(homeAbbr || 'this park')}</span></div>`;
  const weatherRow = weather
    ? `<div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Conditions</span><span class="dr-pdash-env-value">${weather.temp}°F · wind ${weather.wind} mph${weather.precip > 0 ? ' · rain' : ''}</span></div>`
    : `<div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Conditions</span><span class="dr-pdash-env-value" style="color:var(--muted)">${homeAbbr ? 'Dome / indoor park' : 'Not available yet'}</span></div>`;

  wrap.innerHTML = `<div class="dr-pdash-env">${parkRow}${weatherRow}</div><div class="zone-note" style="margin-top:8px">Today's game at ${drEscAttr(homeAbbr || '–')} — real park HR factor + live conditions (Open-Meteo), refreshed every 15 minutes.</div>`;
}

async function renderPitcherSupportSection(meta, wrap) {
  await loadBullpenFatigue().catch(() => {});
  const info = meta.teamAbbr ? bullpenFatigue[meta.teamAbbr] : null;
  if (!info) {
    wrap.innerHTML = `<div class="mu-empty" style="color:var(--muted)">Bullpen support data not available yet for ${drEscAttr(meta.teamAbbr || 'this team')}.</div>`;
  } else {
    const tierColor = info.tier === 'Fresh' ? 'var(--green)' : info.tier === 'Gassed' ? '#f87171' : info.tier === 'Taxed' ? '#fbbf24' : 'var(--text)';
    wrap.innerHTML = `
      <div class="dr-pdash-env">
        <div class="dr-pdash-env-row"><span class="dr-pdash-env-label">${drEscAttr(meta.teamAbbr)} Bullpen</span><span class="dr-pdash-env-value" style="color:${tierColor};font-weight:800">${info.tier}</span></div>
        <div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Reliever Pitches (last 2 days)</span><span class="dr-pdash-env-value">${info.totalRelieverPitches ?? '–'}</span></div>
        <div class="dr-pdash-env-row"><span class="dr-pdash-env-label">Arms Used Back-to-Back</span><span class="dr-pdash-env-value">${info.backToBackArms ?? '–'}</span></div>
      </div>
      <div class="zone-note" style="margin-top:8px">Real recent bullpen workload, not a season average — how much relief support is actually available behind him if he comes out early.</div>`;
  }

  // Real individual reliever reference (season ERA/WHIP/K9/HR9) -- the aggregate
  // workload above answers "how gassed is the pen," this answers "who's actually in
  // it and how good are they." Independent of bullpenFatigue's own availability, so
  // this still tries even when the block above showed the "not available yet" empty
  // state. No way to know pre-game which specific arm enters, so a reference list,
  // not a projection -- same convention as the Bench section on the lineup panel.
  if (meta.gamePk && meta.side) {
    try {
      const box = await fetchJSON(`https://diamondreport.app/api/v1/game/${meta.gamePk}/boxscore`);
      const teamBox = box.teams?.[meta.side];
      const bullpenIds = (teamBox?.bullpen || []).filter(Boolean);
      const people = await fetchRosterReference(bullpenIds, 'pitching', new Date().getFullYear());
      appendRosterReferenceSection(wrap, 'Bullpen Arms', '🧢', people, 'pitching');
    } catch (e) {}
  }
}

// ── Matchup Drivers & AI Explanation ──────────────────────────────────────
// Rule-based synthesis (no LLM call anywhere in this app) -- the same "real threshold
// on a real computed number triggers a short templated sentence" convention already
// used by getColdBatterDiagnosis's reasons and hrScoutingVulnsHTML's vulns. Every input
// here is already computed elsewhere in this exact modal (rolling profile, bullpen
// fatigue, park factor, the real lineup with its platoon/K% data); this function adds
// no new fetch of its own, it just ranks and explains what's already on the page.
// Returns null fields gracefully (never fabricated) when a given input isn't available
// yet, and a driver simply doesn't appear rather than showing a fake "no data" line.
function buildMatchupDrivers({ pitcherName, oppAbbr, row, rollingProfile, bullpenInfo, parkIdx, lineup, avgOpponentKPct }) {
  const drivers = [];

  // 1. Stuff trend (velocity + whiff, usage-weighted L3-vs-season) -- reuses the exact
  // same signal the Trend Indicator badge is built from, just spelled out in prose.
  const trend = computePitcherTrendIndicator(rollingProfile);
  if (trend) {
    const veloTxt = trend.veloDelta !== 0 ? `${trend.veloDelta > 0 ? '+' : ''}${trend.veloDelta} mph velo` : null;
    const whiffTxt = trend.whiffDelta !== 0 ? `${trend.whiffDelta > 0 ? '+' : ''}${trend.whiffDelta}% whiff` : null;
    const detail = [veloTxt, whiffTxt].filter(Boolean).join(', ');
    const good = trend.label === 'Hot Streak' || trend.label === 'Trending Up';
    drivers.push({
      icon: good ? '📈' : '🧊',
      tone: good ? 'green' : 'red',
      magnitude: Math.abs((trend.veloDelta || 0) * 2) + Math.abs(trend.whiffDelta || 0),
      text: `<b>${good ? 'Trending up' : 'Trending down'}</b> over his last 3 starts${detail ? ` (${detail}, usage-weighted vs season)` : ''}.`,
    });
  }

  // 2. Bullpen support behind him.
  if (bullpenInfo?.tier) {
    const tough = bullpenInfo.tier === 'Gassed';
    const good = bullpenInfo.tier === 'Fresh';
    if (tough || good) {
      drivers.push({
        icon: tough ? '🥵' : '🛟',
        tone: tough ? 'red' : 'green',
        magnitude: 3,
        text: tough
          ? `<b>Bullpen is Gassed</b> — ${bullpenInfo.totalRelieverPitches ?? 'a lot of'} pitches over the last 2 days, less margin if he struggles early.`
          : `<b>Bullpen is Fresh</b> — deep relief support if he needs to come out early.`,
      });
    }
  }

  // 3. Park HR factor.
  if (parkIdx != null && (parkIdx >= 110 || parkIdx <= 92)) {
    const hitterFriendly = parkIdx >= 110;
    drivers.push({
      icon: hitterFriendly ? '🏟️' : '🧱',
      tone: hitterFriendly ? 'red' : 'green',
      magnitude: Math.abs(parkIdx - 100) / 5,
      text: hitterFriendly
        ? `Pitching in a <b>hitter-friendly park</b> tonight (${parkIdx >= 100 ? '+' : ''}${parkIdx - 100}% HR factor).`
        : `Pitching in a <b>pitcher-friendly park</b> tonight (${parkIdx - 100}% HR factor).`,
    });
  }

  // 4. Opposing lineup's real platoon-split strength against his throwing hand
  // (batter.platoon.ops, from fetchAndRenderLineup's real vl/vr split fetch).
  if (Array.isArray(lineup) && lineup.length) {
    const opsVals = lineup.map(b => b.platoon?.ops).filter(v => typeof v === 'number');
    if (opsVals.length >= 4) {
      const avgOps = opsVals.reduce((a, b) => a + b, 0) / opsVals.length;
      if (avgOps >= 0.780 || avgOps <= 0.680) {
        const tough = avgOps >= 0.780;
        drivers.push({
          icon: tough ? '⚔️' : '✅',
          tone: tough ? 'red' : 'green',
          magnitude: Math.abs(avgOps - 0.730) * 20,
          text: `Today's lineup carries a real <b>${avgOps.toFixed(3).replace(/^0/, '')} OPS</b> against his throwing hand (${opsVals.length} of ${lineup.length} batters with a real split).`,
        });
      }
    }
  }

  // 5. Opposing lineup's real strikeout tendency -- high K% is favorable for the
  // pitcher, low K% means a tougher, contact-oriented lineup.
  if (avgOpponentKPct != null) {
    if (avgOpponentKPct >= 0.26 || avgOpponentKPct <= 0.16) {
      const favorable = avgOpponentKPct >= 0.26;
      drivers.push({
        icon: favorable ? '💨' : '🎯',
        tone: favorable ? 'green' : 'red',
        magnitude: Math.abs(avgOpponentKPct - 0.21) * 40,
        text: favorable
          ? `Opposing lineup strikes out at a real <b>${(avgOpponentKPct * 100).toFixed(0)}%</b> clip — above average.`
          : `Opposing lineup is <b>contact-oriented</b> — real strikeout rate of just ${(avgOpponentKPct * 100).toFixed(0)}%.`,
      });
    }
  }

  // 6. Real season rate-stat form (only when clearly above/below average -- this is a
  // season-long read, weakest signal of the set, so it's ranked last by design).
  if (row?.era != null) {
    if (row.era <= 3.20 || row.era >= 5.00) {
      const good = row.era <= 3.20;
      drivers.push({
        icon: good ? '🎖️' : '⚠️',
        tone: good ? 'green' : 'red',
        magnitude: Math.abs(row.era - 4.10),
        text: `Real season ERA of <b>${row.era.toFixed(2)}</b>${good ? ', among the better marks in the league' : ', a rough season so far'}.`,
      });
    }
  }

  drivers.sort((a, b) => b.magnitude - a.magnitude);
  const top = drivers.slice(0, 5);

  // AI Explanation -- deterministic templated prose, not a generated summary. Built
  // purely by stitching the top 2-3 real driver sentences together with connective
  // tissue, same "compute real numbers first, template the sentence" rule as every
  // other explanation panel in this app (see getColdBatterDiagnosis's own comment).
  let summary = null;
  if (top.length) {
    const strip = t => t.replace(/<\/?b>/g, '');
    const sentences = top.slice(0, 3).map(d => strip(d.text));
    const name = (pitcherName || 'This pitcher').split(' ').pop();
    summary = `${name} ${sentences[0].charAt(0).toLowerCase()}${sentences[0].slice(1)}`;
    if (sentences[1]) summary += ` ${sentences[1]}`;
    if (sentences[2]) summary += ` ${sentences[2]}`;
  } else {
    const name = (pitcherName || 'This pitcher').split(' ').pop();
    summary = `No matchup drivers are clearly above/below average for ${name} vs ${oppAbbr || 'this lineup'} right now — a genuinely neutral read, not a missing-data gap.`;
  }

  return { drivers: top, summary };
}

function pitcherMatchupDriversHTML(ctx) {
  const { drivers, summary } = buildMatchupDrivers(ctx);
  const rows = drivers.map(d => `<div class="pr-driver-row"><span class="pr-driver-icon">${d.icon}</span><span class="pr-driver-text">${d.text}</span></div>`).join('');
  return `<div class="pr-drivers-panel">
    <div class="pr-drivers-summary">🤖 <b>AI Explanation:</b> ${summary}</div>
    ${rows || '<div class="zone-note">No real drivers stand out from average yet.</div>'}
  </div>
  <div class="zone-note" style="margin-top:8px">Rule-based synthesis from real numbers already on this page (rolling Statcast trend, bullpen workload, park factor, real platoon splits, opponent K rate, season ERA) -- ranked by how far each one is from average. Not AI-generated text; no external model is called.</div>`;
}

async function renderPitcherDriversSection(pid, meta, wrap) {
  if (!wrap.isConnected) return;
  // See driversRenderTokens' own comment -- this call might be one of two racing to
  // render the same pitcher; only the most-recently-started one is allowed to write.
  const token = `${Date.now()}-${Math.random()}`;
  driversRenderTokens[pid] = token;
  const row = prRows.find(r => normalizePitcherId(r.pitcher.id) === pid) || null;
  // Explicitly awaited (not just read off the module store) same as every sibling
  // section here -- callers don't guarantee loadPitcherRolling has resolved yet by
  // the time this runs (openPitcherLineupModal fires this and the Arsenal section's
  // own Promise.all in parallel, not sequentially).
  await loadPitcherRolling().catch(() => {});
  const rollingProfile = pitcherRolling[String(pid)] || null;
  await loadBullpenFatigue().catch(() => {});
  const bullpenInfo = meta.teamAbbr ? bullpenFatigue[meta.teamAbbr] : null;
  await loadParkFactors().catch(() => {});
  const homeAbbr = meta.side === 'home' ? meta.teamAbbr : meta.oppAbbr;
  const parkIdx = homeAbbr ? parkFactors[homeAbbr] : null;
  const cacheKey = `${meta.gamePk}-${meta.side}`;
  const lineup = lineupCache[cacheKey]?.lineup || null;
  const avgOpponentKPct = (lineup && lineup.length) ? opponentKPctForPid(pid, meta) : null;
  if (!wrap.isConnected || driversRenderTokens[pid] !== token) return;
  wrap.innerHTML = pitcherMatchupDriversHTML({
    pitcherName: meta.pitcherName, oppAbbr: meta.oppAbbr, row, rollingProfile, bullpenInfo, parkIdx, lineup, avgOpponentKPct,
  });
}

// Once the opposing lineup (fetched in parallel by openPitcherLineupModal
// below) actually lands, this fills in the one thing that can't be known
// before then: a real opposing-lineup-strength read, and refreshes Expected
// K/IP from the league-average fallback to the real opponent K rate. Bounded
// to a few tries over a few seconds rather than polling forever if a game's
// lineup genuinely never posts.
function pollForLineupThenRefreshMatchup(pid, meta, matchupSubEl, performanceWrap, matchupTableWrap, driversWrap) {
  const cacheKey = `${meta.gamePk}-${meta.side}`;
  let tries = 0;
  (function tick() {
    tries++;
    const lineup = lineupCache[cacheKey]?.lineup;
    if (lineup && lineup.length) {
      const opsVals = lineup.map(b => parseFloat(b.stats?.ops)).filter(v => Number.isFinite(v) && v > 0);
      if (opsVals.length && matchupSubEl) {
        const avgOps = opsVals.reduce((a, b) => a + b, 0) / opsVals.length;
        const tier = avgOps >= .760 ? 'Tough' : avgOps <= .690 ? 'Favorable' : 'Average';
        const color = tier === 'Tough' ? '#f4a261' : tier === 'Favorable' ? 'var(--green)' : 'var(--text)';
        matchupSubEl.innerHTML = `Today's ${drEscAttr(meta.oppAbbr || 'opposing')} lineup — real avg OPS ${avgOps.toFixed(3).replace(/^0/, '')} (<span style="color:${color};font-weight:700">${tier}</span>)`;
      }
      if (performanceWrap && document.body.contains(performanceWrap)) renderPitcherPerformanceSection(pid, meta, performanceWrap);
      if (matchupTableWrap && document.body.contains(matchupTableWrap)) renderPitcherMatchupTable(pid, meta, matchupTableWrap);
      // Matchup Drivers depends on the same real lineup (platoon splits, opponent K%)
      // this poll just confirmed landed, plus bullpen/park data the section fetches
      // itself -- re-run it now so its first real render reflects the actual lineup
      // instead of the "no lineup yet" placeholder it's stuck with when this function
      // first runs before the lineup exists.
      if (driversWrap && document.body.contains(driversWrap)) renderPitcherDriversSection(pid, meta, driversWrap);
      return;
    }
    if (tries < 6) setTimeout(tick, 500);
  })();
}

// heatBG treats a HIGH value as bad (red) -- correct for pitcher rate stats like
// FIP/WHIP, but backwards for a stat where high is good (Whiff%). Negating both the
// value and the two thresholds flips which side reads as green without touching
// heatBG's own blending math.
function heatBGInverted(val, goodAbove, badBelow) {
  return heatBG(val == null ? null : -val, -goodAbove, -badBelow);
}

// Per-pid UI state for the Matchup section's sortable/filterable batter table
// (pitch-type filter chip, RHB/LHB/All hand toggle, sort column/direction, row
// density) -- lets interacting with the controls re-render just the table without
// losing the user's chosen view when the section refreshes for other reasons
// (e.g. the lineup landing late).
const pitcherMatchupTableState = {};
function _muTableState(pid) {
  if (!pitcherMatchupTableState[pid]) pitcherMatchupTableState[pid] = { pitch: 'all', sortKey: 'hr', sortDir: 'desc', density: 'comfortable' };
  return pitcherMatchupTableState[pid];
}

// Real platoon split (AVG/SLG/OPS) against today's specific pitcher's real throwing
// hand -- fetchAndRenderLineup's per-batter statSplits fetch (batter.platoon), not the
// pitch-mix store the other columns read from. Labels are built dynamically off the
// real pitcher hand ("vs RHP"/"vs LHP") rather than a generic "vs Hand" so it's explicit
// these three columns are the batter's real production against pitchers who throw the
// same hand as this one, not against this pitcher's own arsenal like every other column.
function muHandLabel(pitcherHand) {
  return pitcherHand === 'L' ? 'LHP' : pitcherHand === 'R' ? 'RHP' : 'Hand';
}
function muTableColumns(pitcherHand) {
  const hl = muHandLabel(pitcherHand);
  return [
    { key: 'pitches', label: 'Pitches Seen', dec: 0 },
    { key: 'avg',     label: 'AVG',   dec: 3, pct0: true },
    { key: 'iso',     label: 'ISO',   dec: 3, pct0: true },
    { key: 'slg',     label: 'SLG',   dec: 3, pct0: true },
    { key: 'woba',    label: 'wOBA',  dec: 3, pct0: true },
    // Avg EV was here but removed -- live-verified the batter AND pitcher
    // pitch-arsenal leaderboard CSVs (both queried directly against Baseball
    // Savant) simply don't publish an exit-velocity or barrel% column at all,
    // for either side. rowToPitchStat's avgEV/barrelPct candidate names were
    // guesses made before this environment could reach Savant to check; now
    // confirmed none of them exist in the real response, so this cell has
    // shown "–" for every batter under every pitch-type filter since this
    // table launched -- looked exactly like a broken filter, not a genuinely
    // missing data source. Left as a real gap rather than backfilled with an
    // estimate; a future pass could derive it from Statcast Search's raw
    // launch_speed field (same source sync-batter-pitch-type-hr.mjs already
    // queries) if this signal is worth the added per-batter request cost.
    { key: 'whiffPct', label: 'Whiff%', dec: 1, suffix: '%' },
    { key: 'hr',      label: 'HR', dec: 0 },
    { key: 'platoonAvg', label: `AVG vs ${hl}`, dec: 3, pct0: true },
    { key: 'platoonSlg', label: `SLG vs ${hl}`, dec: 3, pct0: true },
    { key: 'platoonOps', label: `OPS vs ${hl}`, dec: 3, pct0: true },
    // Real season HR count against pitchers who throw the same hand as today's
    // starter specifically (b.platoon.hr, same vl/vr statSplits fetch as the three
    // rate columns above) -- distinct from the plain season `hr` column, which is
    // every HR regardless of pitcher hand.
    { key: 'platoonHR',  label: `HR vs ${hl}`,  dec: 0 },
    // Real season K% as a hitter (strikeOuts/PA) -- batter.kPct, same "already computed
    // for the K-prop cell's lineup average, now also surfaced per batter" data as there.
    { key: 'kPct', label: 'K%', dec: 1, suffix: '%' },
  ];
}

// Real per-batter production against either every pitch this pitcher throws
// (pitchKey === 'all', pitches-weighted across the batter's own real per-pitch-type
// rows) or one specific pitch type -- sourced entirely from
// data/batter-pitch-type-season.json (batterPitchTypeSeason), the same real store
// the Batter vs Pitcher modal's Pitch Mix Advantage table already reads. Returns
// null fields (never a fabricated number) when a batter simply isn't in that
// dataset yet or has no rows for the selected pitch type.
function batterStatsForPitchFilter(batterId, pitchKey) {
  const rows = batterPitchTypeSeason[String(batterId)];
  if (!rows) return { pitches: null, avg: null, iso: null, slg: null, woba: null, avgEV: null, whiffPct: null, homeRuns: null };
  if (pitchKey !== 'all') {
    const r = rows[pitchKey];
    if (!r) return { pitches: null, avg: null, iso: null, slg: null, woba: null, avgEV: null, whiffPct: null, homeRuns: null };
    return {
      pitches: r.pitches || null,
      avg: r.avg, iso: (r.slg != null && r.avg != null) ? +(r.slg - r.avg).toFixed(3) : null,
      slg: r.slg, woba: r.woba, avgEV: r.avgEV, whiffPct: r.whiffPct,
      homeRuns: r.homeRuns,
    };
  }
  // 'all' -- aggregate every pitch-type row for this batter, weighted by real
  // pitches seen (a batter who's faced 400 fastballs and 20 sliders shouldn't have
  // those two rates count equally). AVG is pitches-weighted the same way SLG/wOBA/
  // Whiff%/Avg EV already are below -- this used to try recomputing AVG from summed
  // atBats/hits instead, but rowToPitchStat (sync-pitcher-statcast.mjs) never writes
  // per-pitch-type atBats/hits counts, only the pre-computed avg rate itself, so that
  // sum was always 0 and AVG (and ISO, which needs AVG) silently showed "–" for every
  // batter's default "All Pitches" view, every day, regardless of real data coverage.
  const entries = Object.values(rows);
  if (!entries.length) return { pitches: null, avg: null, iso: null, slg: null, woba: null, avgEV: null, whiffPct: null, homeRuns: null };
  let pitches = 0;
  let avgSum = 0, avgW = 0, slgSum = 0, slgW = 0, wobaSum = 0, wobaW = 0, evSum = 0, evW = 0, whiffSum = 0, whiffW = 0;
  let hrSum = 0, hrSeen = false;
  entries.forEach(r => {
    const w = r.pitches || 0;
    pitches += w;
    if (r.avg != null) { avgSum += r.avg * w; avgW += w; }
    if (r.slg != null) { slgSum += r.slg * w; slgW += w; }
    if (r.woba != null) { wobaSum += r.woba * w; wobaW += w; }
    if (r.avgEV != null) { evSum += r.avgEV * w; evW += w; }
    if (r.whiffPct != null) { whiffSum += r.whiffPct * w; whiffW += w; }
    if (r.homeRuns != null) { hrSum += r.homeRuns; hrSeen = true; }
  });
  const avg = avgW > 0 ? +(avgSum / avgW).toFixed(3) : null;
  const slg = slgW > 0 ? +(slgSum / slgW).toFixed(3) : null;
  return {
    pitches: pitches || null,
    avg, iso: (slg != null && avg != null) ? +(slg - avg).toFixed(3) : null,
    slg, woba: wobaW > 0 ? +(wobaSum / wobaW).toFixed(3) : null,
    avgEV: evW > 0 ? +(evSum / evW).toFixed(1) : null,
    whiffPct: whiffW > 0 ? +(whiffSum / whiffW).toFixed(1) : null,
    homeRuns: hrSeen ? hrSum : null,
  };
}

// Real per-batter production against a SPECIFIC pitcher's own real arsenal mix
// (data/pitcher-statcast.json's byPitch usage%), unlike batterStatsForPitchFilter's
// 'all' blend above which weights by how often the BATTER has faced each pitch
// type across the whole league this season. This weights by how often THIS
// pitcher actually throws each pitch, a more honest answer to "does this
// batter's real production profile match up well against this pitcher's
// specific mix" -- the same real per-pitch-type rows, just reweighted.
// Returns the same shape isFavorableMatchupRow already expects; null fields
// when the batter has no real row for a pitch type this pitcher throws.
function batterVsPitcherArsenalStats(batterId, pitcherId) {
  const rows = batterPitchTypeSeason[String(batterId)];
  const arsenal = pitcherStatcast[String(pitcherId)]?.byPitch || [];
  if (!rows || !arsenal.length) return { pitches: null, avg: null, iso: null, slg: null, woba: null, avgEV: null, whiffPct: null };
  let pitches = 0, avgSum = 0, avgW = 0, slgSum = 0, slgW = 0, wobaSum = 0, wobaW = 0, evSum = 0, evW = 0, whiffSum = 0, whiffW = 0;
  arsenal.forEach(p => {
    const r = rows[normalizePitchTypeKey(p.name)];
    const w = p.usagePct || 0;
    if (!r || !w) return;
    pitches += r.pitches || 0;
    if (r.avg != null) { avgSum += r.avg * w; avgW += w; }
    if (r.slg != null) { slgSum += r.slg * w; slgW += w; }
    if (r.woba != null) { wobaSum += r.woba * w; wobaW += w; }
    if (r.avgEV != null) { evSum += r.avgEV * w; evW += w; }
    if (r.whiffPct != null) { whiffSum += r.whiffPct * w; whiffW += w; }
  });
  const avg = avgW > 0 ? +(avgSum / avgW).toFixed(3) : null;
  const slg = slgW > 0 ? +(slgSum / slgW).toFixed(3) : null;
  return {
    pitches: pitches || null,
    avg, iso: (slg != null && avg != null) ? +(slg - avg).toFixed(3) : null,
    slg, woba: wobaW > 0 ? +(wobaSum / wobaW).toFixed(3) : null,
    avgEV: evW > 0 ? +(evSum / evW).toFixed(1) : null,
    whiffPct: whiffW > 0 ? +(whiffSum / whiffW).toFixed(1) : null,
  };
}

// League-average xSLG (falling back to real SLG when a row has no xSLG) per pitch
// type, computed from the SAME batterPitchTypeSeason store already loaded for
// every other per-pitch-type read in this file -- not a separate fetch, not a
// hardcoded guess. Only numeric-id keys are summed (batterPitchTypeSeason also
// carries a lowercased-name duplicate of every entry for name-based lookups
// elsewhere -- summing both would double-count every batter). Memoized since the
// underlying store only changes when loadBatterPitchTypeSeason's own 2-minute
// refresh interval swaps it out.
let _leagueAvgXslgByPitchTypeCache = null;
let _leagueAvgXslgByPitchTypeSrc = null;
function leagueAvgXslgByPitchType() {
  if (_leagueAvgXslgByPitchTypeCache && _leagueAvgXslgByPitchTypeSrc === batterPitchTypeSeason) return _leagueAvgXslgByPitchTypeCache;
  const sums = {}, weights = {};
  Object.keys(batterPitchTypeSeason).forEach(key => {
    if (!/^\d+$/.test(key)) return;
    const rows = batterPitchTypeSeason[key] || {};
    Object.values(rows).forEach(r => {
      const v = r.xslg != null ? r.xslg : r.slg;
      const w = r.pitches || 0;
      if (v == null || !w) return;
      const pk = normalizePitchTypeKey(r.name);
      if (!pk) return;
      sums[pk] = (sums[pk] || 0) + v * w;
      weights[pk] = (weights[pk] || 0) + w;
    });
  });
  const out = {};
  Object.keys(sums).forEach(pk => { out[pk] = +(sums[pk] / weights[pk]).toFixed(3); });
  _leagueAvgXslgByPitchTypeCache = out;
  _leagueAvgXslgByPitchTypeSrc = batterPitchTypeSeason;
  return out;
}

function _muHeatBG(colKey, val) {
  switch (colKey) {
    case 'avg':  return heatBG(val, 0.230, 0.290);
    case 'iso':  return heatBG(val, 0.120, 0.220);
    case 'slg':  return heatBG(val, 0.370, 0.500);
    case 'woba': return heatBG(val, 0.290, 0.370);
    case 'whiffPct': return heatBGInverted(val, 30, 15);
    // Same real league-average bands as the season avg/slg columns above -- these
    // are the batter's real AVG/SLG specifically against pitchers who throw the same
    // hand as this one.
    case 'platoonAvg': return heatBG(val, 0.230, 0.290);
    case 'platoonSlg': return heatBG(val, 0.370, 0.500);
    // League-average OPS runs ~.720-.750; a real vs-hand OPS well above that is real
    // extra danger to this pitcher specifically (not just this batter's overall line).
    case 'platoonOps': return heatBG(val, 0.680, 0.850);
    // Inverted like Whiff% above -- a HIGH strikeout rate is good/safe for the pitcher
    // (green), a low one means a contact hitter who's a tougher real out (red).
    case 'kPct': return heatBGInverted(val, 25, 15);
    default: return 'transparent';
  }
}

// A row earns the "Favorable Matchup" flag when the batter's real production
// against the pitcher's CURRENTLY FILTERED pitch mix clears at least 3 of these
// danger thresholds at once -- the same red-end cutoffs _muHeatBG above already
// colors individual cells with. One hot cell is noise; three real thresholds
// clearing together is a genuine signal this batter is a live danger against
// this specific slice of the pitcher's arsenal, not a single-stat fluke.
// Gated on a real sample floor (pitches seen) so a two-pitch outlier can never
// trigger it -- re-evaluates per pitch-type chip since "favorable" is relative
// to whichever pitch mix is currently selected, same as every other column.
const MU_FAVORABLE_MIN_PITCHES = 20;
const MU_FAVORABLE_MIN_SIGNALS = 3;
function isFavorableMatchupRow(stat) {
  if (stat.pitches == null || stat.pitches < MU_FAVORABLE_MIN_PITCHES) return false;
  let signals = 0;
  if (stat.avg != null && stat.avg >= 0.290) signals++;
  if (stat.iso != null && stat.iso >= 0.220) signals++;
  if (stat.slg != null && stat.slg >= 0.500) signals++;
  if (stat.woba != null && stat.woba >= 0.370) signals++;
  // avgEV signal removed -- see muTableColumns' own comment; stat.avgEV is
  // always null (Savant's pitch-arsenal leaderboard doesn't publish it), so
  // this branch could never fire. MU_FAVORABLE_MIN_SIGNALS stays 3 unchanged
  // -- this was already effectively "3 of 7 real signals," not 8.
  if (stat.whiffPct != null && stat.whiffPct <= 15) signals++;
  if (stat.platoonOps != null && stat.platoonOps >= 0.850) signals++;
  if (stat.kPct != null && stat.kPct <= 15) signals++;
  return signals >= MU_FAVORABLE_MIN_SIGNALS;
}

// The pitcher's own real pitch arsenal (usage%/season HR already synced by
// sync-pitcher-statcast.mjs / sync-pitcher-zone-hr.mjs) becomes the filter chips --
// clicking one recomputes every batter's row against that specific pitch type
// instead of an "All Pitches" blend.
function pitcherMatchupChipsHTML(pid, state) {
  const byPitch = pitcherStatcast[pid]?.byPitch || [];
  const chips = [`<button type="button" class="dr-mu-chip${state.pitch === 'all' ? ' active' : ''}" data-mu-chip="all" data-mu-pid="${pid}">All Pitches</button>`];
  byPitch.forEach(p => {
    const key = normalizePitchTypeKey(p.name);
    const usage = p.usagePct != null ? `${p.usagePct.toFixed(0)}%` : '–';
    const hr = p.homeRuns != null ? `${p.homeRuns} HR` : '';
    chips.push(`<button type="button" class="dr-mu-chip${state.pitch === key ? ' active' : ''}" data-mu-chip="${key}" data-mu-pid="${pid}" style="border-left:3px solid ${pitchTypeColor(p.name)}">${drEscAttr(p.name)} <span class="dr-mu-chip-meta">${usage}${hr ? ' · ' + hr : ''}</span></button>`);
  });
  return `<div class="dr-mu-chips">${chips.join('')}</div>`;
}

function pitcherMatchupControlsHTML(pid, state, pitcherHand) {
  const sortOpts = muTableColumns(pitcherHand).map(c => `<option value="${c.key}"${state.sortKey === c.key ? ' selected' : ''}>${c.label}</option>`).join('');
  return `
    <div class="dr-mu-controls">
      <label class="dr-mu-sort">Sort by
        <select data-mu-sort-key="${pid}">${sortOpts}</select>
      </label>
      <button type="button" class="dr-mu-sort-dir" data-mu-sort-dir="${pid}" title="Toggle ascending/descending">${state.sortDir === 'desc' ? '↓ High to Low' : '↑ Low to High'}</button>
      <div class="dr-mu-density-toggle" data-mu-pid="${pid}">
        <button type="button" class="dr-mu-density-btn${state.density === 'comfortable' ? ' active' : ''}" data-mu-density="comfortable" title="Comfortable rows">☰</button>
        <button type="button" class="dr-mu-density-btn${state.density === 'compact' ? ' active' : ''}" data-mu-density="compact" title="Compact rows">≡</button>
      </div>
    </div>`;
}

// The full sortable/filterable scouting table -- real per-batter production
// against today's real opposing lineup (already fetched for the lineup cards
// below) and the pitcher's real pitch mix. Never a second data source from the
// lineup cards underneath; just a different real cut of the same
// batterPitchTypeSeason + lineupCache data.
// A compact real lineup-status line -- the old per-batter card list surfaced
// this via a CONFIRMED/pending badge; this table takes over the same honesty
// signal so an "expected" fallback lineup (from a past game, not yet
// confirmed for today) is never shown looking as certain as a real posted one.
function pitcherMatchupLineupStatusHTML(cacheEntry) {
  if (!cacheEntry) return '';
  if (cacheEntry.lineupStatus === 'confirmed' || cacheEntry.confirmed === true) {
    return `<div class="dr-mu-lineup-status confirmed">✅ Confirmed lineup${cacheEntry.source ? ' · ' + drEscAttr(cacheEntry.source) : ''}</div>`;
  }
  if (cacheEntry.lineupStatus === 'expected') {
    return `<div class="dr-mu-lineup-status expected">🟡 Expected lineup — not yet confirmed for today${cacheEntry.expectedFromDate ? ' (from ' + new Date(cacheEntry.expectedFromDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ')' : ''}</div>`;
  }
  return '';
}

// Real, actionable message for the two genuinely-broken platoon-split states
// (see fetchPlatoonSplits' own header comment) -- shown only when EVERY
// batter in the lineup is blocked for the same reason, since that's the
// signature of an actual problem (the pitcher's hand not resolved yet, or a
// shared fetch failure) rather than individual batters just not having a
// real vs-hand sample yet (which stays as quiet, unremarkable dashes -- not
// every blank cell is a bug). A mix of 'ok' and 'no-data'/'error' rows means
// most of the table loaded fine, so no banner fires for that case either.
function platoonSplitBannerHTML(pid, lineup) {
  const statuses = lineup.map(b => b.platoon?.status || 'unknown-hand');
  if (!statuses.length || !statuses.every(s => s === 'unknown-hand' || s === 'error')) return '';
  const reason = statuses[0] === 'unknown-hand'
    ? "this pitcher's throwing hand hasn't been confirmed yet"
    : 'a network hiccup while loading';
  return `<div class="dr-mu-platoon-warn">⚠️ "vs Hand" columns unavailable — ${reason}. <button type="button" data-mu-retry-platoon="${pid}">Retry</button></div>`;
}

function pitcherMatchupTableHTML(pid, meta) {
  const state = _muTableState(pid);
  const cacheKey = `${meta.gamePk}-${meta.side}`;
  const cacheEntry = lineupCache[cacheKey];
  const lineup = cacheEntry?.lineup || [];
  if (!lineup.length) {
    return `<div class="mu-empty" style="color:var(--muted)">Waiting for the ${drEscAttr(meta.oppAbbr || 'opposing')} lineup to load…</div>`;
  }

  const columns = muTableColumns(meta.pitcherHand);
  const rows = lineup.map(b => {
    const stat = batterStatsForPitchFilter(b.id, state.pitch);
    // Real production against pitchers who throw the SAME hand as this one
    // (b.platoon, fetched once per batter against meta.pitcherHand specifically) --
    // this is the pitcher-handedness cut the AVG/SLG/OPS "vs Hand" columns show,
    // distinct from the pitch-mix columns above/below which are about this
    // pitcher's own arsenal regardless of hand.
    stat.platoonAvg = b.platoon?.avg ?? null;
    stat.platoonSlg = b.platoon?.slg ?? null;
    stat.platoonOps = b.platoon?.ops ?? null;
    stat.platoonHR = b.platoon?.hr ?? null;
    stat.kPct = b.kPct ?? null;
    const seasonHR = parseInt(b.stats?.homeRuns);
    const seasonHRVal = Number.isFinite(seasonHR) ? seasonHR : null;
    // 'all' shows the real season HR total (authoritative); a specific pitch
    // chip shows real HRs off that pitch type specifically (stat.homeRuns,
    // null when the batter has no HRs logged against it) -- previously this
    // column showed the season total no matter which chip was active, so
    // clicking a pitch type never actually changed the HR count shown, and
    // "Sort by HR" silently sorted by undefined for every row since stat.hr
    // was never set at all.
    stat.hr = state.pitch === 'all' ? seasonHRVal : stat.homeRuns;
    return { batter: b, stat, seasonHR: seasonHRVal };
  });
  const topHRCount = Math.max(0, ...rows.map(r => r.seasonHR || 0));

  rows.sort((a, b) => {
    const av = a.stat[state.sortKey], bv = b.stat[state.sortKey];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    return state.sortDir === 'desc' ? bv - av : av - bv;
  });

  const headCells = columns.map(c => `<th class="num">${c.label}</th>`).join('');
  const pName = (meta.pitcherName || '').replace(/'/g, "\\'");
  // data-label carries each column's short header onto its own <td> -- same
  // mechanism renderPRTable's heatCell/plainCell already use so the existing
  // @media(max-width:700px) card layout can turn every stat into a labeled
  // chip via a CSS ::before instead of forcing sideways scroll on a phone.
  // The whole row opens that batter's full Matchup deep-dive (zone heatmaps,
  // pitch mix, HR spray chart) -- same openMatchup() the old per-batter
  // lineup cards' "Matchup" button called, now the only way in from here
  // since those cards are no longer shown alongside this table.
  const bodyRows = rows.map(({ batter, stat, seasonHR }) => {
    const cells = columns.map(c => {
      if (c.key === 'hr' || c.key === 'platoonHR') {
        const v = stat[c.key];
        return `<td class="num" data-label="${c.label}">${v != null ? v : '–'}</td>`;
      }
      const val = stat[c.key];
      const bg = _muHeatBG(c.key, val);
      const txt = val == null ? '<span style="color:var(--muted)">–</span>' : (c.pct0 ? val.toFixed(c.dec).replace(/^0/, '') : val.toFixed(c.dec)) + (c.suffix || '');
      return `<td class="num" data-label="${c.label}" style="background:${bg}">${txt}</td>`;
    }).join('');
    const star = seasonHR != null && seasonHR > 0 && seasonHR === topHRCount ? '<span title="Most HRs in today\'s lineup" style="color:#fbbf24;margin-left:4px">★</span>' : '';
    const handTag = batter.hand ? `<span class="dr-mu-hand-tag">${batter.hand}</span>` : '';
    const favorable = isFavorableMatchupRow(stat);
    const favorableBadge = favorable ? `<span class="dr-mu-favorable-badge" title="Clears 3+ real production thresholds against ${state.pitch === 'all' ? "this pitcher's full mix" : 'this pitch type'} on a real sample">🔥 Favorable</span>` : '';
    const bName = (batter.name || '').replace(/'/g, "\\'");
    return `<tr class="dr-mu-row${favorable ? ' dr-mu-row-favorable' : ''}" title="View ${drEscAttr(batter.name)} vs ${drEscAttr(meta.pitcherName || 'pitcher')}" onclick="openMatchup(${batter.id},'${bName}',${pid},'${pName}')"><td class="dr-mu-batter-cell">${drEscAttr(batter.name)}${handTag}${star}${favorableBadge}</td>${cells}</tr>`;
  }).join('');

  return `
    ${pitcherMatchupLineupStatusHTML(cacheEntry)}
    ${platoonSplitBannerHTML(pid, lineup)}
    ${pitcherMatchupChipsHTML(pid, state)}
    ${pitcherMatchupControlsHTML(pid, state, meta.pitcherHand)}
    <div class="dr1041-table-wrap dr-mu-table-wrap"><table class="dr1041-pitch-table dr-mu-table dr-mu-density-${state.density}">
      <thead><tr><th>Batter</th>${headCells}</tr></thead>
      <tbody>${bodyRows}</tbody>
    </table></div>
    <div class="zone-note" style="margin-top:2px">Click a batter to open their full Matchup analysis.</div>
    <div class="zone-note" style="margin-top:8px">Real 2026 season production vs the selected pitch type (data/batter-pitch-type-season.json), not a head-to-head history against this specific pitcher -- too small a sample to exist for most matchups. "AVG/SLG/OPS vs ${muHandLabel(meta.pitcherHand)}" and "K%" are real, unfiltered season stats (each batter's real platoon split against pitchers who throw the same hand as this one, and strikeout rate as a hitter) -- they don't change with the pitch-type filter above. Color = danger to this pitcher (red = production well above average, green = below); ★ = most home runs in today's confirmed lineup; 🔥 Favorable = a real sample (20+ pitches seen) that clears at least 3 of these danger thresholds at once against the selected pitch mix.</div>`;
}

function renderPitcherMatchupTable(pid, meta, wrap) {
  if (!wrap.isConnected) return;
  wrap.innerHTML = pitcherMatchupTableHTML(pid, meta);
}

// Manual retry for platoonSplitBannerHTML's button -- re-fetches only the
// "vs Hand" columns (not the whole lineup/boxscore) and re-renders the table
// in place. When the pitcher's own hand still isn't known on meta (the most
// common real cause every row goes blank -- see fetchPlatoonSplits' header
// comment), tries to resolve it fresh first via a single /people/{id} call
// and, if that succeeds, updates lineupMeta[pid] so it's fixed for any future
// re-render too, not just this one retry.
window.retryPlatoonSplits = async function(pid) {
  const meta = lineupMeta[pid];
  const wrap = document.getElementById(`pr-matchup-table-${pid}`);
  if (!meta || !wrap) return;
  const cacheKey = `${meta.gamePk}-${meta.side}`;
  const cacheEntry = lineupCache[cacheKey];
  if (!cacheEntry?.lineup?.length) return;
  const btn = wrap.querySelector('[data-mu-retry-platoon]');
  if (btn) { btn.disabled = true; btn.textContent = 'Retrying…'; }
  let pitcherHand = meta.pitcherHand;
  if (pitcherHand !== 'L' && pitcherHand !== 'R') {
    try {
      const d = await fetchJSON(`https://diamondreport.app/api/v1/people/${pid}`);
      const resolved = handCode(d?.people?.[0], 'pitchHand');
      if (resolved === 'L' || resolved === 'R') {
        pitcherHand = resolved;
        meta.pitcherHand = resolved;
      }
    } catch {}
  }
  const batterIds = cacheEntry.lineup.map(b => b.id).filter(Boolean);
  const platoonById = await fetchPlatoonSplits(batterIds, pitcherHand);
  cacheEntry.lineup.forEach(b => { b.platoon = platoonById[b.id] || { status: 'unknown-hand' }; });
  renderPitcherMatchupTable(pid, meta, wrap);
};

// Delegated so re-rendering the table (which replaces its DOM) never loses the
// click wiring -- same pattern as the existing [data-pstats-toggle] handler.
document.addEventListener('click', (e) => {
  const chip = e.target.closest('[data-mu-chip]');
  if (chip) {
    const pid = chip.getAttribute('data-mu-pid');
    const meta = lineupMeta[pid];
    const wrap = document.getElementById(`pr-matchup-table-${pid}`);
    if (meta && wrap) {
      _muTableState(pid).pitch = chip.getAttribute('data-mu-chip');
      renderPitcherMatchupTable(pid, meta, wrap);
    }
    return;
  }
  const sortDirBtn = e.target.closest('[data-mu-sort-dir]');
  if (sortDirBtn) {
    const pid = sortDirBtn.getAttribute('data-mu-sort-dir');
    const meta = lineupMeta[pid];
    const wrap = document.getElementById(`pr-matchup-table-${pid}`);
    if (meta && wrap) {
      const state = _muTableState(pid);
      state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';
      renderPitcherMatchupTable(pid, meta, wrap);
    }
    return;
  }
  const densityBtn = e.target.closest('[data-mu-density]');
  if (densityBtn) {
    const pid = densityBtn.closest('[data-mu-pid]')?.getAttribute('data-mu-pid');
    const meta = pid && lineupMeta[pid];
    const wrap = pid && document.getElementById(`pr-matchup-table-${pid}`);
    if (meta && wrap) {
      _muTableState(pid).density = densityBtn.getAttribute('data-mu-density');
      renderPitcherMatchupTable(pid, meta, wrap);
    }
    return;
  }
  const retryBtn = e.target.closest('[data-mu-retry-platoon]');
  if (retryBtn) {
    e.stopPropagation();
    window.retryPlatoonSplits(retryBtn.getAttribute('data-mu-retry-platoon'));
  }
});
document.addEventListener('change', (e) => {
  const sel = e.target.closest('[data-mu-sort-key]');
  if (sel) {
    const pid = sel.getAttribute('data-mu-sort-key');
    const meta = lineupMeta[pid];
    const wrap = document.getElementById(`pr-matchup-table-${pid}`);
    if (meta && wrap) {
      _muTableState(pid).sortKey = sel.value;
      renderPitcherMatchupTable(pid, meta, wrap);
    }
  }
});

// Opens (or re-populates, after a table refresh rebuilds its DOM) the
// Pitcher Analytics Dashboard pop-out for a given pitcher row — clicking the
// row calls this directly; renderPRTable calls it again after every refresh
// so an open modal survives the live-score re-render instead of going
// stale.
function openPitcherLineupModal(pidRaw) {
  const pid = normalizePitcherId(pidRaw);
  const meta = lineupMeta[pid];
  if (!meta) return;
  const overlay = document.getElementById('pr-lineup-modal-overlay');
  const body = document.getElementById('pr-lineup-modal-body');
  const title = document.getElementById('pr-lineup-modal-title');
  const sub = document.getElementById('pr-lineup-modal-sub');
  const panel = document.getElementById(`panel-${pid}`);
  if (!overlay || !body || !panel) return;

  openLineupModalPid = pid;
  // Real pitchHand from the MLB Stats API person object (see loadPitcherReport's own
  // comment on where meta.pitcherHand comes from) -- same RHP/LHP label convention as
  // the Matchup scouting table's muHandLabel(), just surfaced in the dashboard header
  // too so it's visible before scrolling to any specific split.
  const handLabel = (meta.pitcherHand === 'L' || meta.pitcherHand === 'R') ? muHandLabel(meta.pitcherHand) : null;
  const handBadgeHTML = handLabel ? ` <span style="display:inline-flex;align-items:center;background:rgba(47,107,255,.14);border:1px solid rgba(47,107,255,.4);color:var(--accent2);border-radius:999px;padding:2px 9px;font-size:11px;font-weight:800;letter-spacing:.5px;vertical-align:middle" title="Throws ${handLabel === 'LHP' ? 'left' : 'right'}-handed">${handLabel}</span>` : '';
  if (title) title.innerHTML = `${drEscAttr(meta.pitcherName || 'Pitcher Analytics Dashboard')}${handBadgeHTML}`;
  if (sub) sub.textContent = `Pitcher Analytics Dashboard${meta.teamAbbr && meta.oppAbbr ? ` · ${meta.teamAbbr} vs ${meta.oppAbbr}` : ''}`;
  body.innerHTML = '';

  const driversWrap = document.createElement('div');
  driversWrap.id = `pr-drivers-${pid}`;
  driversWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Analyzing today's matchup…</div>`;
  body.appendChild(pitcherDashboardSectionWrap('drivers', driversWrap, 'Real-number synthesis, ranked by how far each factor is from average'));

  const arsenalWrap = document.createElement('div');
  arsenalWrap.id = `pr-arsenal-${pid}`;
  arsenalWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Loading ${meta.pitcherName || 'pitcher'}'s pitch data…</div>`;
  body.appendChild(pitcherDashboardSectionWrap('arsenal', arsenalWrap, `${(meta.pitcherName || '').split(' ').pop()}'s repertoire — real Statcast pitch-level data, 2026 season`));

  const performanceWrap = document.createElement('div');
  performanceWrap.id = `pr-performance-${pid}`;
  performanceWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Loading recent form…</div>`;
  body.appendChild(pitcherDashboardSectionWrap('performance', performanceWrap, 'Real last 10/15/20 starts vs season baseline (MLB Stats API game logs)'));

  const matchupWrap = document.createElement('div');
  matchupWrap.id = `pr-matchup-${pid}`;
  const matchupTableWrap = document.createElement('div');
  matchupTableWrap.id = `pr-matchup-table-${pid}`;
  matchupTableWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Loading matchup scouting table…</div>`;
  matchupWrap.appendChild(matchupTableWrap);
  // The old per-batter lineup card list is now redundant with the scouting
  // table above (AVG/HR/OPS/L10/HR PROB there vs. the richer pitch-filtered
  // stats here, and each table row now opens the same Matchup deep-dive the
  // old card's button did) -- kept in the DOM rather than removed so
  // fetchAndRenderLineup/renderLineup (which write into this exact node, and
  // are what actually populates lineupCache for the table above) don't need
  // any restructuring, just visually hidden.
  panel.style.display = 'none';
  matchupWrap.appendChild(panel);
  const matchupSectionEl = pitcherDashboardSectionWrap('matchup', matchupWrap, `Today's ${meta.oppAbbr || 'opposing'} lineup`);
  body.appendChild(matchupSectionEl);

  const environmentWrap = document.createElement('div');
  environmentWrap.id = `pr-environment-${pid}`;
  environmentWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Loading park &amp; weather…</div>`;
  body.appendChild(pitcherDashboardSectionWrap('environment', environmentWrap, "Today's ballpark + live conditions"));

  const supportWrap = document.createElement('div');
  supportWrap.id = `pr-support-${pid}`;
  supportWrap.innerHTML = `<div style="padding:10px 0;color:var(--muted);font-size:12px"><span class="spin"></span> Loading bullpen support…</div>`;
  body.appendChild(pitcherDashboardSectionWrap('support', supportWrap, `${meta.teamAbbr || 'His'} bullpen — real season relief numbers`));

  overlay.style.display = 'flex';
  document.body.style.overflow = 'hidden';

  Promise.all([loadPitcherStatcast(), loadPitcherRolling()]).then(() => {
    arsenalWrap.innerHTML = pitcherArsenalPanelHTML(pid, meta.pitcherName);
    drFillMeters(arsenalWrap);
    // Chained after this exact Promise.all (rather than calling loadPitcherRolling
    // independently) so it can never render its first pass with a still-loading
    // rolling profile -- same real dependency the Arsenal section above already has
    // on this data, not a second guess at load ordering.
    renderPitcherDriversSection(pid, meta, driversWrap);
  });
  renderPitcherPerformanceSection(pid, meta, performanceWrap);
  renderPitcherEnvironmentSection(meta, environmentWrap);
  renderPitcherSupportSection(meta, supportWrap);

  const cacheKey = `${meta.gamePk}-${meta.side}`;
  if (lineupCache[cacheKey]) {
    renderLineup(`panel-${pid}`, lineupCache[cacheKey], meta.pitcherHr9, meta.pitcherIp, meta.oppAbbr, pid, meta.pitcherName);
  } else if (!lineupLoading.has(pid)) {
    fetchAndRenderLineup(pid, meta.pitcherName, meta.gamePk, meta.side, meta.oppTeamId, meta.pitcherHr9, meta.pitcherIp, false, true, meta.pitcherHand).catch(()=>{});
  }
  // The scouting table needs the pitcher's own arsenal (for the filter chips) and
  // the batter pitch-type-season store (for every stat cell) on top of the lineup
  // itself -- render once whichever of those two things is still missing lands,
  // same "never show a stale filtered view" discipline as the rest of this modal.
  Promise.all([loadPitcherStatcast(), loadBatterPitchTypeSeason()]).then(() => {
    renderPitcherMatchupTable(pid, meta, matchupTableWrap);
  });
  renderPitcherMatchupTable(pid, meta, matchupTableWrap);
  const matchupSubEl = matchupSectionEl.querySelector('.dr-pdash-section-sub');
  pollForLineupThenRefreshMatchup(pid, meta, matchupSubEl, performanceWrap, matchupTableWrap, driversWrap);
}
window.openPitcherLineupModal = openPitcherLineupModal;

function closePitcherLineupModal() {
  const overlay = document.getElementById('pr-lineup-modal-overlay');
  if (overlay) overlay.style.display = 'none';
  document.body.style.overflow = '';
  openLineupModalPid = null;
}
window.closePitcherLineupModal = closePitcherLineupModal;

function rehydrateOpenLineupModal() {
  if (!openLineupModalPid) return;
  if (!lineupMeta[openLineupModalPid]) { closePitcherLineupModal(); return; }
  openPitcherLineupModal(openLineupModalPid);
}

// Card-based layout at every screen size (previously desktop got a dense 15-column
// table and only mobile/tablet got cards — this replaced both with the one polished
// card treatment, in a grid that's 1-up on narrow screens and 2-up on wide ones).
const PR_SORT_FIELDS = [
  {key:'gameTime', label:'Time'},
  {key:'kprop',    label:'Live K'},
  {key:'ip',       label:'IP'},
  {key:'bf',       label:'BF'},
  {key:'fip',      label:'FIP'},
  {key:'avg',      label:'AVG'},
  {key:'woba',     label:'wOBA'},
  {key:'whip',     label:'WHIP'},
  {key:'iso',      label:'ISO'},
  {key:'slg',      label:'SLG'},
  {key:'hr9',      label:'HR/9'},
  {key:'tb',       label:'TB'},
  {key:'kpg',      label:'K/GM'},
];

// Heat-map background for a stat cell: green at/below goodBelow, red at/above
// badAbove, continuously blended in between — reuses the exact same thresholds
// the old pill() badges used, just expressed as a gradient instead of 3 buckets.
// Softened extremes (was green=[26,58,42]/red=[58,26,26]) -- 7 of this
// table's columns are heat-mapped simultaneously, so full-strength color on
// every one of them read as a heavy wash across the whole row rather than a
// quick scan. Same neutral midpoint, same real gradient math, just a lower
// max saturation at both ends.
function heatBG(val, goodBelow, badAbove) {
  if (val == null) return 'transparent';
  const mid = (goodBelow + badAbove) / 2;
  const half = (badAbove - goodBelow) / 2 || 1;
  let t = 1 + (val - mid) / half; // 0 = green, 1 = neutral, 2 = red
  t = Math.max(0, Math.min(2, t));
  const green = [20,46,36], neu = [11,20,36], red = [46,22,22];
  const [a, b] = t <= 1 ? [green, neu] : [neu, red];
  const localT = t <= 1 ? t : t - 1;
  const rgb = a.map((c, i) => Math.round(c + (b[i] - c) * localT));
  return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
}

function renderPRTable() {
  const el = document.getElementById('pr-content');
  if (!el) return;
  const __searchFocus = drCaptureSearchFocus('pr-search-input');
  const sorted = getSortedPRRowsForCurrentSort().filter(r => drMatchesSearch('pr', r.pitcher?.name));
  const hs = id => `https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_46,q_auto:best/v1/people/${id}/headshot/67/current`;
  // data-label carries each cell's short column header along for the mobile
  // card layout (see the @media (max-width: 700px) rules in styles.css),
  // where a CSS ::before turns every stat into a labeled chip instead of a
  // table column — .pr-mobile-tag distinguishes a plain cell from a heat
  // cell so that layout can give plain cells a neutral chip background
  // without overwriting the heat cells' own inline color.
  const heatCell = (val, dispFn, goodBelow, badAbove, tip, label) => {
    const bg = heatBG(val, goodBelow, badAbove);
    const txt = val == null ? '<span style="color:var(--muted)">–</span>' : dispFn(val);
    return `<td style="background:${bg}"${tip?` data-tip="${tip}"`:''}${label?` data-label="${label}"`:''}>${txt}</td>`;
  };
  const plainCell = (value, tip, label) => `<td class="pr-plain-cell"${tip?` data-tip="${tip}"`:''}${label?` data-label="${label}"`:''}>${value}</td>`;

  const rowsAndPanels = sorted.map(r => {
    const p = r.pitcher;
    const pid = normalizePitcherId(p.id);

    // K prop line — real sportsbook line if available, else model projection rounded to nearest half
    const kpropLine = getKPropLine(p, r);
    if (kpropLine != null) pitcherOULines[p.id] = kpropLine;

    // Populated for every row (not just ones the user has opened) so a click
    // on the row can open the pop-out modal with just a pitcher id.
    lineupMeta[pid] = {
      pitcherName: p.name, gamePk: p.gamePk, side: p.side, oppTeamId: p.oppTeamId,
      pitcherHr9: r.rawHr9, pitcherIp: r.rawIp, teamAbbr: p.teamAbbr, oppAbbr: p.oppAbbr,
      pitcherHand: r.pitcherHand, gameTimestamp: p.gameTimestamp,
    };

    const row = `<tr class="pr-row-tr" id="pr-row-${pid}" style="cursor:pointer" onclick="window.openPitcherLineupModal('${pid}')">
        <td class="pr-lineup-batter-cell">
          <img class="pr-headshot" src="${hs(p.id)}" alt="${p.name}" loading="lazy" decoding="async">
          <div style="min-width:0">
            <div class="pr-mobile-name">${p.name} ${pitcherTrendIndicatorChipHTML(pitcherRolling[String(p.id)])}</div>
            <div class="pr-mobile-sub">${p.teamAbbr} · ${r.wl} · vs ${p.oppAbbr}</div>
            <div class="pr-mobile-time" style="color:${p.timeColor};font-weight:${p.timeLabel.includes('LIVE')?700:400}">${p.timeLabel}</div>
            <div class="pr-lineup-hint" style="display:inline-flex;align-items:center;gap:4px;margin-top:5px;padding:3px 8px;border-radius:999px;background:rgba(47,107,255,.12);border:1px solid rgba(47,107,255,.35);color:var(--accent2);font-size:9px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;white-space:nowrap">
              <svg width="10" height="10" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="14" height="14" rx="2"/><path d="M6.5 7.5h7M6.5 10h7M6.5 12.5h4"/></svg>
              View ${p.oppAbbr || 'Opponent'} Lineup
            </div>
          </div>
        </td>
        ${plainCell(r.ip!=null?r.ip.toFixed(1):'–', 'Innings Pitched', 'IP')}
        ${plainCell(r.bf!=null?r.bf:'–', 'Batters Faced', 'BF')}
        ${heatCell(r.fip,  v=>v.toFixed(2), 3.25, 4.50, 'Fielding Independent Pitching', 'FIP')}
        ${heatCell(r.avg,  v=>v.toFixed(3).replace(/^0/,''), .220, .270, 'Batting Average Against', 'AVG')}
        ${heatCell(r.woba, v=>v.toFixed(3).replace(/^0/,''), .290, .340, 'Weighted On-Base Average', 'wOBA')}
        ${heatCell(r.whip, v=>v.toFixed(2), 1.10, 1.40, 'Walks + Hits per Inning Pitched', 'WHIP')}
        ${heatCell(r.iso,  v=>v.toFixed(3).replace(/^0/,''), .150, .200, 'Isolated Power — extra-base power allowed', 'ISO')}
        ${heatCell(r.slg,  v=>v.toFixed(3).replace(/^0/,''), .350, .430, 'Slugging Percentage Against', 'SLG')}
        ${heatCell(prHr9ForRow(r, prHandFilter),  v=>v.toFixed(2), 0.80, 1.50, prHandFilter==='all' ? 'Home Runs per 9 Innings' : `Home Runs per 9 Innings vs ${prHandFilter==='R'?'RHB':'LHB'}`, prHandFilter==='all' ? 'HR/9' : `HR/9 vs ${prHandFilter==='R'?'RHB':'LHB'}`)}
        ${plainCell(r.tb!=null?r.tb:'–', 'Total Bases Allowed', 'TB')}
        ${plainCell(`<span style="color:${r.kpg>=7?'var(--green)':r.kpg>=5?'var(--text)':'var(--muted)'}">${r.kpg??'–'}</span>`, 'Average Strikeouts per Game Started', 'K/GM')}
      </tr>`;

    // Hidden, off-row lineup panel — kept alive independent of the table row
    // markup so HR Threats' pre-lineup fallback (loadHRPotential) can keep
    // warming lineupCache via fetchAndRenderLineup even when no modal is
    // open. The pop-out modal borrows this exact node (by id) when opened.
    const panel = `<div class="pr-expand-panel" id="panel-${pid}" style="display:none"><span class="spin"></span> Loading lineup…</div>`;

    return { row, panel };
  });
  const rows = rowsAndPanels.map(x => x.row).join('');
  const hiddenPanels = rowsAndPanels.map(x => x.panel).join('');

  const prSortBtns = PR_SORT_FIELDS.map(({key,label}) => {
    const active = prSortCol === key;
    const arrow = active ? (prSortDir === 1 ? ' ↑' : ' ↓') : '';
    const displayLabel = (key === 'hr9' && prHandFilter !== 'all') ? `HR/9 vs ${prHandFilter==='R'?'RHB':'LHB'}` : label;
    return `<button onclick="sortPR('${key}')" style="font-size:9px;font-weight:700;font-family:Manrope,sans-serif;padding:4px 10px;border-radius:12px;border:1px solid ${active?'var(--accent2)':'var(--border)'};background:${active?'rgba(47,107,255,.12)':'var(--surface2)'};color:${active?'var(--accent2)':'var(--muted)'};cursor:pointer;white-space:nowrap;flex-shrink:0;transition:all .15s">${displayLabel}${arrow}</button>`;
  }).join('');

  // HR/9 vs batter hand toggle -- the only column with a real per-hand aggregate
  // stat (prHr9ForRow's own comment explains why the rest of the table stays
  // season-overall regardless of this). Same .dr1042-split-toggle pill styling
  // as the hand toggles elsewhere in the app so this reads as the same control.
  const prHandToggle = `<div class="dr1042-split-toggle" role="tablist" aria-label="HR/9 batter hand toggle" style="flex-shrink:0">
      <button type="button" class="dr1042-split-btn${prHandFilter==='all'?' active':''}" onclick="setPRHandFilter('all')">HR/9: All</button>
      <button type="button" class="dr1042-split-btn${prHandFilter==='R'?' active':''}" onclick="setPRHandFilter('R')">vs RHB</button>
      <button type="button" class="dr1042-split-btn${prHandFilter==='L'?' active':''}" onclick="setPRHandFilter('L')">vs LHB</button>
    </div>`;
  const hr9HeaderLabel = prHandFilter === 'all' ? 'HR/9' : `HR/9 vs ${prHandFilter === 'R' ? 'RHB' : 'LHB'}`;

  const noMatches = !sorted.length && (window.__drBoardSearch.pr || '').trim();
  el.innerHTML = `
    <div class="kprops-sticky-sort" style="display:flex;align-items:center;gap:6px;padding:8px 14px;background:var(--bg);border-bottom:1px solid var(--border);overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;flex-wrap:nowrap">
      <span style="font-size:9px;font-weight:700;letter-spacing:1px;color:var(--muted);white-space:nowrap;flex-shrink:0">SORT:</span>
      ${prSortBtns}
      <button onclick="resetPRSort()" style="font-size:9px;font-weight:700;font-family:Manrope,sans-serif;padding:3px 8px;border-radius:12px;border:1px solid var(--border);background:var(--surface2);color:var(--muted);cursor:pointer;white-space:nowrap;flex-shrink:0">RESET</button>
      ${prHandToggle}
      ${drSearchInputHTML('pr', 'pr-search-input', 'Search pitchers…', "drSetBoardSearch('pr',this.value,renderPRTable)")}
    </div>
    ${noMatches ? `<div class="mu-empty" style="padding:24px">No pitchers match "${window.__drBoardSearch.pr}". Try a different name.</div>` : `
    <div class="dr1041-table-wrap pr-starters-table-wrap"><table class="pr-stats-table pr-starters-table">
      <thead><tr>
        <th style="text-align:left">Pitcher</th>
        <th>IP</th><th>BF</th><th>FIP</th><th>AVG</th><th>wOBA</th><th>WHIP</th><th>ISO</th><th>SLG</th><th>${hr9HeaderLabel}</th><th>TB</th><th>K/GM</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table></div>
    <div id="pr-lineup-panels" style="display:none">${hiddenPanels}</div>`}
    <div class="pr-legend">
      <span class="pr-legend-chip"><span class="pr-legend-dot good"></span>Elite</span>
      <span class="pr-legend-chip"><span class="pr-legend-dot neu"></span>Average</span>
      <span class="pr-legend-chip"><span class="pr-legend-dot bad"></span>Concerning</span>
      <span class="pr-legend-sep">·</span>
      <span class="pr-legend-note">HR% = estimated per-AB probability based on batter HR rate × pitcher HR/9</span>
      <span class="pr-legend-sep">·</span>
      <span class="pr-legend-note">2026 season</span>
    </div>`;

  rehydrateOpenLineupModal();
  drRestoreSearchFocus(__searchFocus);
}



// v8.9 Lineup Stats Fix
// Official boxscore lineups often include only same-game batting lines, which can be
// 0-for-0 early in the game. This helper separately enriches each batter with season
// hitting stats and tries the adjacent season when the app is running against an older
// MLB data snapshot. It does not change the prediction model; it only prevents the
// lineup matchup UI from displaying empty boxscore stats as .000 / 0 / .000.
function _statHasRealBattingData(stat) {
  if (!stat) return false;
  const ab = parseInt(stat.atBats);
  const pa = parseInt(stat.plateAppearances);
  const ops = parseFloat(stat.ops);
  const avg = parseFloat(stat.avg);
  const hr = parseInt(stat.homeRuns);
  return (ab > 0) || (pa > 0) || (ops > 0) || (avg > 0) || (hr > 0);
}
function _seasonCandidates(preferredSeason) {
  const y = parseInt(preferredSeason || new Date().toLocaleDateString('en-CA',{timeZone:'America/Chicago'}).slice(0,4), 10);
  const vals = [y, y - 1, y + 1, 2025, 2024].filter(v => v && v >= 2020 && v <= y + 1);
  return [...new Set(vals.map(String))];
}
async function fetchBatterSeasonBundle(playerId, preferredSeason, fallbackStats = {}) {
  let bestStat = _statHasRealBattingData(fallbackStats) ? fallbackStats : {};
  let bestLogs = [];
  for (const season of _seasonCandidates(preferredSeason)) {
    try {
      const [seasonData, logData] = await Promise.all([
        fetchJSON(`https://diamondreport.app/api/v1/people/${playerId}?hydrate=stats(group=hitting,type=season,season=${season})`).catch(()=>null),
        fetchJSON(`https://diamondreport.app/api/v1/people/${playerId}/stats?stats=lastXGames&group=hitting&season=${season}&limit=12&gameType=R`).catch(()=>({stats:[]}))
      ]);
      let stat = seasonData?.people?.[0]?.stats?.[0]?.splits?.[0]?.stat || {};
      if (!_statHasRealBattingData(stat)) {
        const alt = await fetchJSON(`https://diamondreport.app/api/v1/people/${playerId}/stats?stats=season&group=hitting&season=${season}&gameType=R`).catch(()=>null);
        stat = alt?.stats?.[0]?.splits?.[0]?.stat || stat;
      }
      // lastXGames isn't documented as guaranteed most-recent-first -- sorted
      // explicitly so every caller's logs.slice(0,N) (last10HR, recentGames,
      // aggregateLastNGames, etc.) actually means "the N most recent games."
      // Same fix already applied at the HR Threats board's own separate
      // lastXGames fetch (loadHRPotential) after this exact assumption produced
      // impossible-looking output (e.g. two "3-HR games" in a batter's last 5).
      const logs = (logData?.stats?.[0]?.splits || []).slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
      if (_statHasRealBattingData(stat)) return { seasonStats: stat, logs, season };
      if (!bestLogs.length && logs.length) bestLogs = logs;
    } catch {}
  }
  return { seasonStats: bestStat, logs: bestLogs, season: String(preferredSeason || '') };
}
// Best-effort "expected lineup" fallback for when MLB hasn't posted today's official
// batting order yet -- pulls the team's most recent completed game's actual batting
// order as a reasonable placeholder (not a roster/depth-chart guess, which would be
// far less reliable), clearly labeled as unconfirmed for today by the caller.
async function fetchExpectedLineup(teamId) {
  if (!teamId) return null;
  try {
    const season = new Date().getFullYear();
    const sched = await fetchJSON(`https://diamondreport.app/api/v1/schedule?sportId=1&season=${season}&teamId=${teamId}&hydrate=team&language=en`);
    const games = [];
    (sched.dates || []).forEach(d => (d.games || []).forEach(g => games.push(g)));
    const now = Date.now();
    const priorFinals = games
      .filter(g => g.status?.abstractGameState === 'Final' && new Date(g.gameDate).getTime() < now)
      .sort((a, b) => new Date(b.gameDate) - new Date(a.gameDate));
    if (!priorFinals.length) return null;
    const lastGame = priorFinals[0];
    const side = String(lastGame.teams?.away?.team?.id) === String(teamId) ? 'away' : 'home';
    const box = await fetchJSON(`https://diamondreport.app/api/v1/game/${lastGame.gamePk}/boxscore`);
    const teamBox = box.teams?.[side];
    let batters = (teamBox?.batters || []).map(id => teamBox.players[`ID${id}`]).filter(Boolean);
    batters = batters.filter(b => {
      const bo = Number(b.battingOrder || b.stats?.batting?.battingOrder || NaN);
      return Number.isFinite(bo) && bo % 100 === 0;
    }).sort((a, b) => (parseInt(a.battingOrder || a.stats?.batting?.battingOrder || 9999) - parseInt(b.battingOrder || b.stats?.batting?.battingOrder || 9999)));
    if (!batters.length) return null;
    return { batters, gameDate: lastGame.gameDate };
  } catch (e) {
    return null;
  }
}

// Real bench (hitting) / bullpen (pitching) roster reference -- season stats only,
// never a specific-matchup projection like the confirmed starters/starter get.
// There's no way to know pre-game which bench player or reliever actually enters a
// game, so this is deliberately just "who's available and how good are they,"
// shared by the batting lineup panel's Bench section (fetchAndRenderLineup) and the
// Pitcher Report Support section's Bullpen Arms section (renderPitcherSupportSection).
async function fetchRosterReference(ids, statGroup, season) {
  if (!ids || !ids.length) return [];
  try {
    const d = await fetchJSON(`https://diamondreport.app/api/v1/people?personIds=${ids.join(',')}&hydrate=stats(group=${statGroup},type=season,season=${season})`);
    return d?.people || [];
  } catch { return []; }
}
function rosterReferenceRowsHTML(people, statGroup) {
  return people.map(p => {
    const s = p.stats?.[0]?.splits?.[0]?.stat || {};
    const pos = p.primaryPosition?.abbreviation || '–';
    const fv = (v, dec) => (v == null || v === '' || v === '-.--') ? '–' : (dec ? String(v).replace(/^0(\.)/, '$1') : v);
    const statsHTML = statGroup === 'pitching'
      ? [['ERA', fv(s.era)], ['WHIP', fv(s.whip)], ['K/9', fv(s.strikeoutsPer9Inn)], ['HR/9', fv(s.homeRunsPer9)]]
      : [['AVG', fv(s.avg, true)], ['HR', fv(s.homeRuns)], ['OPS', fv(s.ops, true)]];
    return `<div class="lbc-bench-row">
      <span class="lbc-bench-name">${p.fullName || '–'}</span>
      <span class="lbc-bench-pos">${pos}</span>
      <span class="lbc-bench-stats">${statsHTML.map(([label, v]) => `<span class="lbc-stat-chip"><b>${label}</b>${v}</span>`).join('')}</span>
    </div>`;
  }).join('');
}
function appendRosterReferenceSection(container, title, icon, people, statGroup) {
  if (!container || !people || !people.length) return;
  const rowsHTML = rosterReferenceRowsHTML(people, statGroup);
  if (!rowsHTML) return;
  const section = document.createElement('div');
  section.className = 'lbc-bench-section';
  section.innerHTML = `<button type="button" class="lbc-bench-toggle" onclick="this.classList.toggle('open');this.nextElementSibling.classList.toggle('open')">${icon} ${title} (${people.length})<span class="lbc-bench-caret">›</span></button>
    <div class="lbc-bench-list">${rowsHTML}</div>`;
  container.appendChild(section);
}

// Real per-batter platoon split (AVG/OBP/SLG/OPS/HR) against a specific pitcher
// hand -- same statSplits/vl,vr endpoint and batterSplitForHand extraction
// fetchAndRenderLineup's own inline version of this used to do inline, now
// pulled out so window.retryPlatoonSplits below can take the exact same path
// on a manual retry instead of duplicating it.
//
// Every entry gets a `status` field ('ok'/'no-data'/'error'/'unknown-hand')
// alongside whatever real values it found. Before this, a real fetch failure
// and a real "this rookie has no vs-hand at-bats yet" were both just `null`,
// indistinguishable from each other or from the (very common) case of the
// pitcher's own throwing hand not being known yet -- all three silently
// rendered as the exact same blank dashes across every column for every
// batter, with no way for a user to tell "this table is broken" from "there's
// genuinely nothing to show" or to do anything about it beyond reloading the
// whole page and hoping. pitcherMatchupTableHTML's platoonSplitBannerHTML
// reads this status to show a real, actionable message only for the two
// genuinely-broken cases.
async function fetchPlatoonSplits(batterIds, pitcherHand) {
  if (!(pitcherHand === 'L' || pitcherHand === 'R') || !batterIds.length) {
    return Object.fromEntries(batterIds.map(id => [id, { status: 'unknown-hand' }]));
  }
  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
  const pairs = await Promise.all(batterIds.map(async id => {
    try {
      const d = await fetchJSON(`https://diamondreport.app/api/v1/people/${id}/stats?stats=statSplits&group=hitting&sitCodes=vl,vr&season=${today.slice(0, 4)}`);
      const split = batterSplitForHand(d?.stats?.[0]?.splits || [], pitcherHand);
      if (!split) return [id, { status: 'no-data' }];
      const avg = split.avg != null ? parseFloat(split.avg) : null;
      const obp = split.obp != null ? parseFloat(split.obp) : null;
      const slg = split.slg != null ? parseFloat(split.slg) : null;
      const ops = split.ops != null ? parseFloat(split.ops) : (obp != null && slg != null ? +(obp + slg).toFixed(3) : null);
      const ab = split.atBats != null ? parseInt(split.atBats) : null;
      const hr = split.homeRuns != null ? parseInt(split.homeRuns) : null;
      return [id, { status: 'ok', avg, obp, slg, ops, ab, hr }];
    } catch { return [id, { status: 'error' }]; }
  }));
  return Object.fromEntries(pairs);
}

async function fetchAndRenderLineup(pitcherId, pitcherName, gamePk, side, oppTeamId, pitcherHr9, pitcherIp, skipEnrichment = false, bypassPRGuards = false, pitcherHand = null) {
  const pid = normalizePitcherId(pitcherId);
  const panel = document.getElementById(`panel-${pid}`);
  if (!panel) return;
  if (!bypassPRGuards && isPRMobileTabletView()) return;

  const token = `${Date.now()}-${Math.random()}`;
  lineupRequestTokens[pid] = token;
  lineupLoading.add(pid);

  const isFirstLoad = !panel.querySelector('[data-batter-id]');
  if (isFirstLoad) {
    panel.style.minHeight = '86px';
    panel.innerHTML = drSkeletonRowsHTML(3, 'Loading lineup…');
  }

  try {
    const oppSide = side === 'away' ? 'home' : 'away';
    await loadRepoLineups();
    const repoLineup = getRepoLineupForGame(gamePk, oppSide);

    // If a confirmed lineup has been uploaded/committed, always trust it first.
    if (repoLineup?.confirmed === true && repoLineup?.lineup?.length) {
      const cacheKey = `${gamePk}-${side}`;
      lineupCache[cacheKey] = { ...repoLineup, oppSide, lineupStatus: 'confirmed' };
      if (lineupRequestTokens[pid] !== token) return;
      renderLineup(`panel-${pid}`, lineupCache[cacheKey], pitcherHr9, pitcherIp, null, pid, pitcherName);
      return;
    }

    const box = await fetchJSON(`https://diamondreport.app/api/v1/game/${gamePk}/boxscore`);
    const boxState = box?.gameData?.status?.abstractGameState || box?.gameData?.status?.codedGameState || '';
    const boxDetail = box?.gameData?.status?.detailedState || '';
    const gameHasStartedForLineup = boxState === 'Live' || boxState === 'Final' || boxDetail === 'In Progress';
    const teamBox = box.teams?.[oppSide];
    let batters = (teamBox?.batters || []).map(id => teamBox.players[`ID${id}`]).filter(Boolean);
    const hasOfficialBattingOrder = batters.some(b => b && (b.battingOrder || b.stats?.batting?.battingOrder));
    if (hasOfficialBattingOrder) {
      batters = batters.sort((a,b) => (parseInt(a.battingOrder || a.stats?.batting?.battingOrder || 9999) - parseInt(b.battingOrder || b.stats?.batting?.battingOrder || 9999)));
    }

    let lineupConfirmed = true;
    let lineupSource = 'MLB official batting order';
    let lineupStatus = 'confirmed';
    let expectedFromDate = null;

    if (!hasOfficialBattingOrder || !batters.length) {
      // Today's official order isn't posted yet -- fall back to this team's most
      // recent completed game's actual batting order as a reasonable placeholder,
      // clearly labeled as unconfirmed for today rather than presented as real.
      const expected = await fetchExpectedLineup(oppTeamId).catch(() => null);
      if (expected && expected.batters.length) {
        batters = expected.batters;
        lineupConfirmed = false;
        lineupStatus = 'expected';
        expectedFromDate = expected.gameDate;
        lineupSource = 'Expected lineup — from ' + new Date(expected.gameDate).toLocaleDateString('en-US', {month:'short', day:'numeric'}) + ", not yet confirmed for today";
      } else {
        const cacheKey = `${gamePk}-${side}`;
        lineupCache[cacheKey] = { lineup: [], oppSide, teamAbbr: teamBox?.team?.abbreviation || '', confirmed: false, lineupStatus: 'pending', source: 'MLB official lineup pending', updatedAt: new Date().toISOString() };
        if (lineupRequestTokens[pid] !== token) return;
        renderLineupPending(`panel-${pid}`, lineupCache[cacheKey].teamAbbr);
        return;
      }
    }

    const today = new Date().toLocaleDateString('en-CA', {timeZone:'America/Chicago'});

    // Real batter handedness (R/L/S) for the RHB/LHB split in the Matchup section --
    // MLB Stats API's bulk /people?personIds= endpoint returns full person records
    // (batSide included) for the whole lineup in one request, the same real
    // person-record shape as the single-batter /people/{id} calls used elsewhere in
    // this file, just batched so a 9-batter lineup doesn't cost 9 extra round trips.
    // Fired now so it resolves in parallel with the enrichment work below.
    const batterIdsForHand = batters.slice(0,9).map(b => b.person?.id).filter(Boolean);
    const batSidePromise = batterIdsForHand.length
      ? fetchJSON(`https://diamondreport.app/api/v1/people?personIds=${batterIdsForHand.join(',')}`).catch(() => null)
      : Promise.resolve(null);

    // Real per-batter platoon split (AVG/OBP/SLG/OPS/HR) against THIS specific pitcher's
    // real throwing hand -- same statSplits/vl/vr endpoint and batterSplitForHand
    // extraction openMatchup already uses for one batter at a time, just paid for the
    // whole lineup here since opening a pitcher's full report is an explicit on-demand
    // click, not part of the always-on HR Threats board. One request per batter (not
    // gated on a minimum AB -- degrades to whatever real sample exists, same convention
    // as openMatchup's own split fetch, never fabricated). fetchPlatoonSplits itself
    // handles the "pitcher's own throwing hand isn't known yet" case (returns every
    // batter tagged 'unknown-hand' rather than skipping silently) -- see its own header
    // comment, and window.retryPlatoonSplits below for the manual-retry path this feeds.
    const platoonSplitPromise = fetchPlatoonSplits(batterIdsForHand, pitcherHand);

    // Fast path: use stats already in the boxscore, skip per-batter API calls.
    // K Props lineup expand uses this — saves ~18 API calls and renders instantly.
    let enriched;
    if (skipEnrichment) {
      enriched = batters.slice(0,9).map(b => {
        const id = b.person?.id;
        const boxStats = teamBox?.players?.[`ID${id}`]?.stats?.batting || {};
        const seasonStats = b.seasonStats?.batting || boxStats;
        const todayHR = gameHasStartedForLineup ? (parseInt(boxStats.homeRuns) || 0) : 0;
        return { seasonStats, last10HR: null, todayHR };
      });
    } else {
      const preferredSeason = (box.gameDate || box.dates?.[0]?.date || today).slice(0,4);
      enriched = await Promise.all(batters.slice(0,9).map(async b => {
        const id = b.person?.id;
        if (!id) return { seasonStats: b.seasonStats?.batting || {}, last10HR: null, todayHR: 0 };
        const boxStats = teamBox?.players?.[`ID${id}`]?.stats?.batting || {};
        try {
          const bundle = await fetchBatterSeasonBundle(id, preferredSeason, b.seasonStats?.batting || boxStats || {});
          const seasonStats = bundle.seasonStats || b.seasonStats?.batting || {};
          const gameLogs    = bundle.logs || [];
          const last10HR    = gameLogs.length ? gameLogs.slice(0,10).reduce((sum, g) => sum + (parseInt(g.stat?.homeRuns)||0), 0) : null;
          const todayLog    = gameLogs.find(g => g.date === today);
          const todayHR     = gameHasStartedForLineup ? (parseInt(todayLog?.stat?.homeRuns) || 0) : 0;
          const boxTodayHR  = gameHasStartedForLineup ? (parseInt(boxStats.homeRuns) || 0) : 0;
          return { seasonStats, last10HR, todayHR: Math.max(todayHR, boxTodayHR) };
        } catch {
          return { seasonStats: (_statHasRealBattingData(b.seasonStats?.batting) ? b.seasonStats?.batting : {}), last10HR: null, todayHR: gameHasStartedForLineup ? (parseInt(boxStats.homeRuns)||0) : 0 };
        }
      }));
    }

    const [peopleData, platoonById] = await Promise.all([batSidePromise, platoonSplitPromise]);
    const batSideById = {};
    (peopleData?.people || []).forEach(p => { if (p?.id) batSideById[p.id] = handCode(p, 'batSide'); });

    const lineup = batters.slice(0,9).map((b, i) => {
      const s = enriched[i].seasonStats || {};
      const pa = parseInt(s.plateAppearances) || 0;
      const so = parseInt(s.strikeOuts) || 0;
      return {
        name: b.person?.fullName || '–',
        id: b.person?.id,
        pos: b.position?.abbreviation || '–',
        // Real MLB-reported batting side ('R'/'L'/'S') from the bulk /people fetch
        // above, or null if that call failed or this batter simply isn't in the
        // response -- never guessed, and handCode's own '–' sentinel is normalized
        // to null here so downstream RHB/LHB grouping can cleanly skip unknowns.
        hand: (batSideById[b.person?.id] && batSideById[b.person?.id] !== '–') ? batSideById[b.person?.id] : null,
        stats: s,
        last10HR: enriched[i].last10HR,
        todayHR: enriched[i].todayHR,
        confirmed: lineupConfirmed,
        source: lineupSource,
        // Real season K% as a hitter (strikeOuts/plateAppearances) -- was already being
        // computed inline just for the K-prop cell's lineup-wide average (see below);
        // kept per-batter here too so the scouting table can show each hitter's own
        // real strikeout tendency instead of only the lineup-wide blend.
        kPct: pa > 0 ? +(so / pa * 100).toFixed(1) : null,
        // Real platoon split (AVG/OBP/SLG/OPS/HR) vs today's specific pitcher's throwing
        // hand -- see fetchPlatoonSplits' own header comment for the status field
        // ('ok'/'no-data'/'error'/'unknown-hand'); values are never fabricated.
        platoon: platoonById[b.person?.id] || { status: 'unknown-hand' },
      };
    });

    const cacheKey = `${gamePk}-${side}`;
    const prevLineup = lineupCache[cacheKey]?.lineup || [];
    lineupCache[cacheKey] = {
      lineup,
      oppSide,
      teamAbbr: box.teams?.[oppSide]?.team?.abbreviation || '',
      confirmed: lineupConfirmed,
      lineupStatus,
      source: lineupSource,
      expectedFromDate,
      updatedAt: new Date().toISOString()
    };

    if (lineupRequestTokens[pid] !== token) return;

    if (isFirstLoad) {
      // Full render on first load
      if (lineupRequestTokens[pid] !== token) return;
      renderLineup(`panel-${pid}`, lineupCache[cacheKey], pitcherHr9, pitcherIp, null, pid, pitcherName);

      // Bench reference (real season AVG/HR/OPS, not a projection -- see
      // fetchRosterReference's header comment) -- fire-and-forget, appended once
      // ready rather than blocking the starters render above on it. teamBox.bench is
      // already sitting in the SAME boxscore this function just fetched, so this is
      // one extra bulk /people call, not a second boxscore fetch.
      const benchIds = (teamBox?.bench || []).filter(Boolean);
      if (benchIds.length) {
        fetchRosterReference(benchIds, 'hitting', today.slice(0, 4)).then(people => {
          if (lineupRequestTokens[pid] !== token) return;
          appendRosterReferenceSection(document.getElementById(`panel-${pid}`), 'Bench', '🪑', people, 'hitting');
        });
      }

      // Patch K Prop cell with lineup-adjusted projection
      const kpropCell = document.getElementById(`kprop-cell-${pid}`);
      if (kpropCell && lineup.length) {
        const avgKpct = lineup.reduce((sum, b) => {
          const s = b.stats;
          return sum + ((s.strikeOuts && s.plateAppearances) ? s.strikeOuts/s.plateAppearances : 0.22);
        }, 0) / lineup.length;
        const row = prRows.find(r => normalizePitcherId(r.pitcher.id) === pid);
        if (row) {
          const k9 = row.rawK9 || 8;
          const kpctAdj = (avgKpct - 0.22) * 10;
          const adjKprop = Math.round((k9 * 5.5 / 9 + kpctAdj) * 2) / 2;
          const kpropCls = k9 >= 9 ? 'good' : k9 >= 7 ? 'mid' : 'low';
          const line = pitcherOULines[pid] != null ? pitcherOULines[pid] : Math.round(adjKprop * 2) / 2;
          const dir = adjKprop < line ? 'Under' : 'Over';
          kpropCell.innerHTML = `<span class="pr-stat-chip pr-kprop-chip ${kpropCls}" title="Adj. for opp K% ${(avgKpct*100).toFixed(0)}%">K Prop: ${dir} ${line}</span>`;
        }
      }
    } else {
      // A live HR (or season-stat count) can move several columns in a single
      // table row (AB/H/HR/RBI/BB/AVG/OBP/SLG/OPS/ISO/Rating all derive from
      // the same season stat object), so patch the whole table rather than
      // trying to diff individual cells — cheap for a 9-row table.
      const anyChanged = lineup.some((b, i) => {
        const prev = prevLineup[i];
        return !prev || prev.todayHR !== b.todayHR || prev.last10HR !== b.last10HR;
      });
      if (anyChanged) {
        renderLineup(`panel-${pid}`, lineupCache[cacheKey], pitcherHr9, pitcherIp, null, pid, pitcherName);
      }

      // Update timestamp
      const tsEl = panel.querySelector('.lineup-timestamp');
      if (tsEl) tsEl.textContent = `Last updated ${new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}`;
    }
  } catch(e) {
    if (lineupRequestTokens[pid] === token && isFirstLoad && panel) {
      drShowError(panel, "Couldn't load today's lineup.", () => fetchAndRenderLineup(pitcherId, pitcherName, gamePk, side, oppTeamId, pitcherHr9, pitcherIp, skipEnrichment, bypassPRGuards, pitcherHand));
    }
  } finally {
    if (lineupRequestTokens[pid] === token) {
      lineupLoading.delete(pid);
      panel.style.minHeight = '';
    }
  }
}

function buildBatterStatsLine(b) {
  const s = b.stats;
  function fmtS(v) {
    if (!_statHasRealBattingData(s)) return '–';
    if (!v||v==='---') return '–';
    const n=parseFloat(v); return isNaN(n)?'–':n.toFixed(3).replace(/^0/,'');
  }
  const last10HR = b.last10HR;
  const hrVal = _statHasRealBattingData(s) ? (s.homeRuns ?? '–') : '–';
  const hrHot = _statHasRealBattingData(s) && parseInt(s.homeRuns) >= 10;
  const l10Display = last10HR === null ? '–' : `${last10HR} HR`;
  const l10Hot = last10HR >= 3, l10Warm = !l10Hot && last10HR >= 1;
  const hrProb = Number(b.hrProb);
  const hrProbChip = Number.isFinite(hrProb)
    ? `<span class="lbc-stat-chip${hrProb>=15?' hot':hrProb>=8?' warm':''}"><b>HR PROB</b>${hrProb.toFixed(1)}%</span>`
    : '';
  return `<span class="lbc-stat-chip"><b>AVG</b>${fmtS(s.avg)}</span>
    <span class="lbc-stat-chip${hrHot?' hot':''}"><b>HR</b>${hrVal}</span>
    <span class="lbc-stat-chip"><b>OPS</b>${fmtS(s.ops)}</span>
    <span class="lbc-stat-chip${l10Hot?' hot':l10Warm?' warm':''}"><b>L10</b>${l10Display}</span>
    ${hrProbChip}`;
}


function renderLineupPending(panelId, teamAbbr = '') {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const checkedAt = new Date().toLocaleTimeString('en-US', { hour:'numeric', minute:'2-digit' });
  panel.innerHTML = `
    <div class="lineup-pending-card lineup-pending-premium">
      <div class="lineup-pending-head">
        <span>${teamAbbr ? `${teamAbbr} BATTING LINEUP` : 'BATTING LINEUP'}</span>
        <span class="lineup-pending-chip">🔄 AUTO CHECK ENABLED</span>
      </div>
      <div class="lineup-pending-body">
        <div class="lineup-pending-icon">🟡</div>
        <div>
          <div class="lineup-pending-title">Awaiting Official MLB Lineup</div>
          <div class="lineup-pending-copy">The official batting order has not been released yet. This section will populate automatically as soon as the team confirms today's starters.</div>
          <div class="lineup-pending-meta">
            <span>Status: Waiting for official lineup</span>
            <span>Last checked ${checkedAt}</span>
          </div>
        </div>
      </div>
    </div>`;
}

// Pitcher's own real pitch-arsenal breakdown (usage/AVG/wOBA/SLG/HR/Whiff% per
// pitch type, plus a per-pitch attack-zone location heatmap) — same real
// synced data (data/pitcher-statcast.json, see scripts/sync-pitcher-statcast.mjs
// and sync-pitcher-zone-hr.mjs) and same markup/classes as the Batter vs
// Pitcher matchup modal's pitch-mix section, extracted standalone so it can
// also show up in the Batting Lineup & Matchups pop-out (Pitcher Report and
// K Props both use this), where there's no specific batter to build a
// matchup against — just the pitcher's own numbers. The Attack Zone tab
// clicks are already handled by a document-level delegated listener keyed
// off [data-attack-zone-toggle]/.dr1042-split-btn[data-pitch], so this needs
// no extra wiring wherever it's injected.
const ZONE_LABELS = ['In/High','High','Out/High','Inside','Middle','Away','In/Low','Low','Out/Low'];
// Simple horizontal bar chart shared by the Pitcher Analytics Dashboard's
// Usage/Velocity/Whiff charts -- one row per pitch type, bar color keyed to
// PITCH_TYPE_COLORS so a pitch reads as the same color across every chart in
// this panel ("color follows the entity"). Every bar carries a direct value
// label (not just a color-coded legend), since the 8-slot palette validated
// in the 6-8 CVD floor band, which is only legal with that secondary
// encoding. `domainMax` is a fixed scale, not each chart's own data max, so
// bars stay honestly comparable rather than reading off a rescaled axis.
function pitchBarChartHTML(title, subtitle, rows, domainMax, fmt) {
  if (!rows.length) return '';
  const bars = rows.map(r => {
    const pct = Math.max(0, Math.min(100, (r.value / domainMax) * 100));
    const color = pitchTypeColor(r.name);
    return `<div class="dr-pchart-row" title="${drEscAttr(r.name)}: ${drEscAttr(fmt(r.value))}">
      <span class="dr-pchart-label"><span class="dr-pchart-swatch" style="background:${color}"></span>${drEscAttr(r.name)}</span>
      <div class="dr-pchart-track"><div class="dr-pchart-fill" style="background:${color}" data-fill="${pct.toFixed(1)}%"></div></div>
      <span class="dr-pchart-value">${fmt(r.value)}${r.badge || ''}</span>
    </div>`;
  }).join('');
  return `<div class="dr-pchart">
    <div class="dr-pchart-title">${title}${subtitle ? `<span class="dr-pchart-subtitle">${subtitle}</span>` : ''}</div>
    <div class="dr-pchart-rows">${bars}</div>
  </div>`;
}

// Pitcher Trend Indicator -- adapts computePlayerTrendIndicator's Hot Streak/Trending
// Up/Cooling Off/Cold pattern (batter HR trend, HR Threats board) for pitchers. A
// pitcher's "hot" means structurally different things than a batter's, so this is its
// own real signal, not a reused one: driven by real velocity + whiff-rate deltas (last
// 3 starts vs season baseline, already computed by sync-pitcher-rolling.mjs), weighted
// by each pitch's rolling usage share so a shift on the primary weapon counts more than
// one on a rarely-thrown fourth pitch. Null (no badge) when rolling data hasn't synced
// for this pitcher yet or the signal is genuinely neutral -- never fabricated.
function computePitcherTrendIndicator(rollingProfile) {
  if (!rollingProfile || !Array.isArray(rollingProfile.byPitch) || !rollingProfile.byPitch.length) return null;
  let veloW = 0, veloSum = 0, whiffW = 0, whiffSum = 0;
  rollingProfile.byPitch.forEach(p => {
    const w = p.rollingUsagePct || 0;
    if (p.veloDelta != null) { veloSum += p.veloDelta * w; veloW += w; }
    if (p.whiffDelta != null) { whiffSum += p.whiffDelta * w; whiffW += w; }
  });
  if (!veloW && !whiffW) return null;
  const veloDelta = veloW > 0 ? veloSum / veloW : 0;
  const whiffDelta = whiffW > 0 ? whiffSum / whiffW : 0;
  // Combine into one score: velo weighted x2 (0.5mph is already a meaningful shift per
  // the L3 Trend table's own noise floor) plus raw whiff% points.
  const score = (veloDelta * 2) + whiffDelta;
  let label = null, tone = '';
  if (score >= 4) { label = 'Hot Streak'; tone = 'red'; }
  else if (score >= 1.5) { label = 'Trending Up'; tone = 'green'; }
  else if (score <= -4) { label = 'Cold'; tone = ''; }
  else if (score <= -1.5) { label = 'Cooling Off'; tone = ''; }
  if (!label) return null;
  return { label, tone, veloDelta: +veloDelta.toFixed(1), whiffDelta: +whiffDelta.toFixed(1) };
}
function pitcherTrendIndicatorChipHTML(rollingProfile) {
  const t = computePitcherTrendIndicator(rollingProfile);
  if (!t) return '';
  const icon = t.label === 'Hot Streak' ? '📈' : t.label === 'Trending Up' ? '↗️' : t.label === 'Cooling Off' ? '↘️' : '🧊';
  const cls = t.tone === 'red' ? 'red' : t.tone === 'green' ? 'green' : '';
  const title = `Velo ${t.veloDelta > 0 ? '+' : ''}${t.veloDelta} mph, Whiff ${t.whiffDelta > 0 ? '+' : ''}${t.whiffDelta}% (L3 starts vs season, usage-weighted)`;
  return `<span class="pr-trend-chip ${cls}" title="${drEscAttr(title)}">${icon} ${t.label.toUpperCase()}</span>`;
}

function pitcherArsenalPanelHTML(pitcherId, pitcherName) {
  const profile = pitcherStatcast[String(pitcherId)] || null;
  const rollingProfile = pitcherRolling[String(pitcherId)] || null;
  const hasRealPitchMix = !!(profile?.byPitch?.length);
  const hasCareerPitchMix = !!(profile?.career?.byPitch?.length);
  const hasRollingData = !!(rollingProfile?.byPitch?.length);

  function attackZoneColor(pct) {
    if (pct == null) return { bg:'#0d1220', text:'var(--muted)' };
    if (pct >= 20) return { bg:'#4a1010', text:'#ff6b6b' };
    if (pct >= 14) return { bg:'#3a2010', text:'#f4a261' };
    if (pct >= 8)  return { bg:'#1a2a10', text:'#90ee60' };
    return { bg:'#0d1a0d', text:'#3a6a3a' };
  }
  const attackZonePitches = (profile?.byPitch || []).filter(p => p?.name && p.zones && Object.keys(p.zones).length);
  let attackZoneHTML = '';
  if (attackZonePitches.length) {
    const auid = `azone-${String(pitcherId||'p')}-${Math.random().toString(36).slice(2,8)}`;
    const tabs = attackZonePitches.map((p, i) => `<button type="button" class="dr1042-split-btn${i===0?' active':''}" data-pitch="${i}">${p.name}</button>`).join('');
    const bodies = attackZonePitches.map((p, i) => {
      const cells = [1,2,3,4,5,6,7,8,9].map(z => {
        const cell = p.zones[z];
        const pct = cell?.usagePct;
        if (pct == null) return `<div class="sz-cell" style="background:#0d1220;color:var(--muted)" title="${ZONE_LABELS[z-1]}: no data">–</div>`;
        const c = attackZoneColor(pct);
        const wobaTxt = cell.wobaAgainst != null ? `, ${cell.wobaAgainst.toFixed ? cell.wobaAgainst.toFixed(3) : cell.wobaAgainst} wOBA against` : '';
        return `<div class="sz-cell" style="background:${c.bg};color:${c.text}" title="${ZONE_LABELS[z-1]}: ${pct}% of his ${p.name}s${wobaTxt}">${pct}%</div>`;
      }).join('');
      return `<div class="dr-azone-mode-body${i===0?' active':''}" data-pitch="${i}"><div class="strike-zone">${cells}</div></div>`;
    }).join('');
    attackZoneHTML = `
    <div class="zone-section" id="${auid}" data-attack-zone-toggle>
      <div class="zone-title">ATTACK ZONE BY PITCH · REAL LOCATION DATA</div>
      <div class="zone-wrap">
        <div class="zone-grid-outer">
          <span class="zone-label">OUTSIDE ←&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;→ INSIDE</span>
          <div style="display:flex;align-items:center;gap:6px">
            <div style="display:flex;flex-direction:column;gap:2px;font-size:9px;color:var(--muted);text-align:right;padding-right:4px">
              <div style="height:40px;display:flex;align-items:center">HIGH</div>
              <div style="height:40px;display:flex;align-items:center">MID</div>
              <div style="height:40px;display:flex;align-items:center">LOW</div>
            </div>
            ${bodies}
          </div>
          <span class="zone-label" style="margin-top:4px">% = share of that pitch's own throws landing in each zone</span>
        </div>
        <div>
          <div class="dr1042-split-toggle" role="tablist" aria-label="Attack zone pitch toggle" style="flex-wrap:wrap;height:auto">${tabs}</div>
          <div class="zone-note" style="margin-top:10px;max-width:220px">Where ${(pitcherName||'').split(' ').pop()} actually locates each individual pitch — his real location tendency pitch by pitch, not just the blended zone profile above.</div>
        </div>
      </div>
    </div>`;
  }

  const pitchSectionLabel = hasRealPitchMix
    ? `${(pitcherName||'').split(' ').pop()}'S PITCHES · ${(profile.totalPitches || 0).toLocaleString()} THROWN THIS SEASON`
    : `${(pitcherName||'').split(' ').pop()}'S PITCHES · NO REAL DATA YET`;

  function gbGood(kind, v) {
    if (v === null || v === undefined || Number.isNaN(v)) return false;
    if (kind === 'avg') return v >= .280;
    if (kind === 'slg') return v >= .450;
    if (kind === 'hr') return v >= 3;
    if (kind === 'whiff') return v <= 20;
    if (kind === 'woba') return v >= .340;
    return false;
  }
  function gbCls(kind, v) { return gbGood(kind, v) ? ' gb-good' : ''; }
  function fmtDec(v, d=3) {
    if (v === null || v === undefined || v === '' || v === '–') return '–';
    const n = parseFloat(v);
    return Number.isNaN(n) ? '–' : n.toFixed(d).replace(/^0(?=\.)/, '');
  }
  function pitchEffTag(label, cls) { return `<span class="dr1041-chip ${cls}" style="font-size:9px;padding:2px 7px;margin-right:4px">${label}</span>`; }
  function pitchEffRow(name, usage, avg, woba, slg, hr, whiffPct, veloTxt) {
    const tags = [];
    if (whiffPct != null && whiffPct >= 28) tags.push(pitchEffTag('🎯 Putaway','good'));
    if ((avg != null && avg >= .260) || (slg != null && slg >= .430)) tags.push(pitchEffTag('⚠ Vulnerable','weak'));
    return `<tr>
      <td><strong>${name}</strong>${veloTxt||''}</td>
      <td class="usage">${usage!=null?Number(usage).toFixed(0)+'%':'–'}</td>
      <td class="num${gbCls('avg',avg)}">${fmtDec(avg,3)}</td>
      <td class="num${gbCls('woba',woba)}">${fmtDec(woba,3)}</td>
      <td class="num${gbCls('slg',slg)}">${fmtDec(slg,3)}</td>
      <td class="num${gbCls('hr',hr)}">${hr!=null?hr:'–'}</td>
      <td class="num${gbCls('whiff',whiffPct)}">${whiffPct!=null?Number(whiffPct).toFixed(0)+'%':'–'}</td>
      <td>${tags.join('') || '<span style="color:var(--muted);font-size:11px">–</span>'}</td>
    </tr>`;
  }

  // veloTxt intentionally dropped from every pitch-table row here (it was
  // always empty anyway -- data/pitcher-statcast.json's byPitch has no
  // avgVelo field; only data/pitcher-rolling.json does) now that velocity
  // gets its own real chart below, keyed off the data that actually has it.
  function buildPitchRows(byPitchArr) {
    return (byPitchArr || []).map(p => {
      const woba = p.woba ?? p.wobaAgainst ?? p.xwoba ?? p.xwobaContact ?? null;
      const avg = p.avg ?? p.avgAgainst ?? null;
      const slg = p.slg ?? p.slgAgainst ?? null;
      const hr = p.homeRuns ?? p.hr ?? null;
      const whiffPct = p.whiffPct ?? p.whiffRate ?? null;
      return pitchEffRow(p.name, p.usagePct, avg, woba, slg, hr, whiffPct, '');
    }).join('');
  }
  const pitchRows = hasRealPitchMix ? buildPitchRows(profile.byPitch) : '';
  const careerPitchRows = hasCareerPitchMix ? buildPitchRows(profile.career.byPitch) : '';

  // ── Real charts: Pitch Usage, Velocity, Whiff Rate ──────────────────────
  // Usage/whiff come from the season Statcast profile (broadly synced, 700+
  // pitchers); velocity comes from data/pitcher-rolling.json, which only
  // covers today's probable starters -- but that's exactly this dashboard's
  // whole audience, so it's not a real coverage gap in practice. Velocity's
  // delta badge is colored from the PITCHER's own perspective (this is his
  // scouting report, not a batter's): velocity trending UP over his last 3
  // starts is good for him (green), trending down is a real concern
  // (orange) -- the opposite framing from the batter-facing Batter vs
  // Pitcher modal's rollingDeltaTag, which colors the same numbers from the
  // hitter's point of view.
  let chartsHTML = '';
  if (hasRealPitchMix || hasRollingData) {
    const usageRows = hasRealPitchMix ? profile.byPitch.filter(p => p.usagePct != null).map(p => ({ name: p.name, value: p.usagePct })) : [];
    const whiffRows = hasRealPitchMix ? profile.byPitch.filter(p => p.whiffPct != null).map(p => ({ name: p.name, value: p.whiffPct })) : [];
    let veloRows = [];
    if (hasRollingData) {
      veloRows = rollingProfile.byPitch.filter(p => p.seasonVelo != null).map(p => {
        const delta = p.veloDelta;
        const badge = delta != null && Math.abs(delta) >= 0.5
          ? ` <span style="color:${delta > 0 ? 'var(--green)' : '#f4a261'};font-weight:700">(${delta > 0 ? '+' : ''}${delta.toFixed(1)} L3)</span>`
          : '';
        return { name: p.name, value: p.seasonVelo, badge };
      });
    }
    const usageChart = pitchBarChartHTML('Pitch Usage', '2026 season', usageRows, 100, v => v.toFixed(0) + '%');
    const veloChart = pitchBarChartHTML('Velocity', 'season, vs last 3 starts', veloRows, 105, v => v.toFixed(1) + ' mph');
    const whiffChart = pitchBarChartHTML('Whiff Rate', '2026 season', whiffRows, 100, v => v.toFixed(0) + '%');
    if (usageChart || veloChart || whiffChart) chartsHTML = `<div class="dr-pchart-grid">${usageChart}${veloChart}${whiffChart}</div>`;
  }

  function rollingDeltaTagPitcherView(delta, noiseThreshold) {
    if (delta == null) return `<span style="color:var(--muted)">–</span>`;
    // Pitcher-centric coloring (see chartsHTML comment above): up is good here.
    const color = delta >= noiseThreshold ? 'var(--green)' : delta <= -noiseThreshold ? '#f4a261' : 'var(--muted)';
    const sign = delta > 0 ? '+' : '';
    return `<span style="color:${color};font-weight:700">${sign}${delta.toFixed(1)}</span>`;
  }
  let rollingRows = '';
  if (hasRollingData) {
    rollingRows = rollingProfile.byPitch.map(p => `
      <tr>
        <td><strong>${p.name}</strong></td>
        <td class="num">${p.seasonUsagePct != null ? p.seasonUsagePct.toFixed(0) + '%' : '–'} → ${p.rollingUsagePct != null ? p.rollingUsagePct.toFixed(0) + '%' : '–'}</td>
        <td class="num">${p.seasonVelo != null ? p.seasonVelo.toFixed(1) : '–'} → ${p.rollingVelo != null ? p.rollingVelo.toFixed(1) : '–'} mph (${rollingDeltaTagPitcherView(p.veloDelta, 0.5)})</td>
        <td class="num">${p.seasonSpin != null ? p.seasonSpin : '–'} → ${p.rollingSpin != null ? p.rollingSpin : '–'} rpm${p.spinDelta != null ? ` (${rollingDeltaTagPitcherView(p.spinDelta, 50)})` : ''}</td>
        <td class="num">${p.seasonWhiffPct != null ? p.seasonWhiffPct.toFixed(0) + '%' : '–'} → ${p.rollingWhiffPct != null ? p.rollingWhiffPct.toFixed(0) + '%' : '–'} (${rollingDeltaTagPitcherView(p.whiffDelta, 3)})</td>
      </tr>`).join('');
  }
  const rollingLastDates = (rollingProfile?.lastStartDates || []).join(', ');

  const gbLegendHTML = '<div class="dr1041-legend-note"><span class="gb-good-dot"></span> Green = favorable for the batter — a real weak spot for the pitcher on that pitch, not just a good season overall.</div>';

  const pstatsModes = [];
  if (hasRealPitchMix) pstatsModes.push('season');
  if (hasCareerPitchMix) pstatsModes.push('career');
  if (hasRollingData) pstatsModes.push('rolling');
  const pstatsModeLabel = m => m === 'season' ? 'SEASON' : m === 'career' ? 'CAREER' : 'L3 TREND';
  const pstatsToggleHTML = pstatsModes.length > 1 ? `
      <div class="dr1042-split-toggle" role="tablist" aria-label="Pitcher stats mode toggle">
        ${pstatsModes.map((m, i) => `<button type="button" class="dr1042-split-btn${i === 0 ? ' active' : ''}" data-mode="${m}">${pstatsModeLabel(m)}</button>`).join('')}
      </div>` : '';
  function seasonOrCareerBody(mode, rows, isActive) {
    return `<div class="dr-pstats-mode-body${isActive ? ' active' : ''}" data-mode="${mode}">
      <div class="dr1041-table-wrap"><table class="dr1041-pitch-table"><thead><tr><th>Pitch</th><th>Usage</th><th>AVG</th><th>wOBA</th><th>SLG</th><th>HR</th><th>Whiff%</th><th>Notes</th></tr></thead><tbody>${rows}</tbody></table></div>
      ${gbLegendHTML}
    </div>`;
  }
  function rollingBody(isActive) {
    const shortPName = (pitcherName || '').split(' ').pop();
    return `<div class="dr-pstats-mode-body${isActive ? ' active' : ''}" data-mode="rolling">
      <div class="dr1041-table-wrap"><table class="dr1041-pitch-table"><thead><tr><th>Pitch</th><th>Usage (Season → L3)</th><th>Velo (Season → L3)</th><th>Spin (Season → L3)</th><th>Whiff% (Season → L3)</th></tr></thead><tbody>${rollingRows}</tbody></table></div>
      <div class="zone-note" style="margin-top:8px">${shortPName}'s last 3 starts${rollingLastDates ? ` (${rollingLastDates})` : ''} vs his full-season baseline. Green = trending better for him (velocity or whiff rate up). Orange = trending worse (velocity or whiff rate down). Muted = change too small to be a real signal.</div>
    </div>`;
  }
  const pstatsBodiesHTML = pstatsModes.map((m, i) => {
    const isActive = i === 0;
    if (m === 'season') return seasonOrCareerBody('season', pitchRows, isActive);
    if (m === 'career') return seasonOrCareerBody('career', careerPitchRows, isActive);
    return rollingBody(isActive);
  }).join('');
  const pstatsSubtext = pstatsModes.length > 1
    ? `Real synced pitch-level data for ${pitcherName} — toggle ${pstatsModes.map(pstatsModeLabel).join(' / ')}. Every metric below is 2026 season unless the L3 Trend tab is active.`
    : hasRealPitchMix
      ? `Real synced pitch-level data for ${pitcherName}. 2026 season.`
      : hasRollingData
        ? `${pitcherName}'s last 3 starts compared to his full-season baseline, per pitch — season pitch-mix data not synced yet.`
        : `No real pitch-level data available for ${pitcherName} yet — this section will populate once the daily Statcast sync has run.`;
  // Chase% (O-Swing%) -- overall (not per-pitch-type), so it's a headline stat rather
  // than another pitch-mix table column. See sync-pitcher-rolling.mjs's
  // OUT_OF_ZONE_CODES comment for exactly what counts as "out of zone."
  const trendChipHTML = pitcherTrendIndicatorChipHTML(rollingProfile);
  const chaseTextHTML = rollingProfile?.seasonChasePct != null
    ? `<span title="Real swing rate on pitches outside the strike zone (Statcast zone 11-14), season vs last 3 starts">Chase% (O-Swing): <strong>${rollingProfile.seasonChasePct.toFixed(1)}%</strong>${rollingProfile.rollingChasePct != null ? ` → <strong>${rollingProfile.rollingChasePct.toFixed(1)}%</strong> (L3)` : ''}</span>`
    : '';
  const chasePctHTML = (chaseTextHTML || trendChipHTML)
    ? `<div class="pr-chase-chip">${chaseTextHTML}${chaseTextHTML && trendChipHTML ? ' &nbsp; ' : ''}${trendChipHTML}</div>`
    : '';

  const pitchEffectivenessTableHTML = pstatsModes.length > 0 ? `<div class="dr1041-pitch-mix" style="margin-top:14px" data-pstats-toggle>
    <div class="dr1041-pitch-head">
      <div><div class="dr1041-kicker">🧪 ${pitchSectionLabel}</div><div class="dr1041-subtext">${pstatsSubtext}</div>${chasePctHTML}</div>
      ${pstatsToggleHTML}
    </div>
    ${pstatsBodiesHTML}
  </div>` : `<div class="dr1041-pitch-mix" style="margin-top:14px">
    <div class="dr1041-pitch-head">
      <div><div class="dr1041-kicker">🧪 ${pitchSectionLabel}</div><div class="dr1041-subtext">No real pitch-level data available for ${pitcherName} yet — this section will populate once the daily Statcast sync has run.</div></div>
    </div>
  </div>`;

  return chartsHTML + pitchEffectivenessTableHTML + attackZoneHTML;
}

// Real per-matchup scouting report for HR Threats cards, at the user's request to
// replace the generic templated "grades at X% because..." summary with the same
// "SCOUTING REPORT — HOW TO HIT A HOME RUN" vulnerability bullets already shown in
// the pop-out matchup modal (openMatchup/renderMatchupModal) — built from the same
// three live MLB Stats API calls (batter season stats, pitcher season stats, career
// head-to-head) so a card's report and the modal's report always agree.
const hrScoutingReportCache = new Map();
// cardIso (optional): the card's own recency+platoon-blended ISO (r.iso on an HR
// Threats row) -- when given, the "ISO of X" callout below quotes THIS number
// instead of recomputing a raw season bs.slg-bs.avg, so the prose never disagrees
// with the ISO chip sitting right above it on the same card. Callers without a
// card row (none currently, but keeping the fallback cheap/safe) still get a real
// number instead of nothing.
function hrScoutingVulnsHTML(batterName, pitcherName, bs, ps, h2h, cardIso) {
  function fv(v, dec=3) {
    if (v==null||v===''||v==='---') return '–';
    const n = parseFloat(v); return isNaN(n) ? '–' : n.toFixed(dec).replace(/^0(\.)/, '$1');
  }
  function fi(v) { const n=parseInt(v); return isNaN(n)?'–':String(n); }
  const pHR9 = fv(ps.homeRunsPer9,2), pAVG = fv(ps.avg), pWHIP = fv(ps.whip,2);
  const hasCardIso = Number.isFinite(cardIso);
  const bISO = hasCardIso ? fv(cardIso) : ((bs.slg&&bs.avg) ? fv((parseFloat(bs.slg)-parseFloat(bs.avg)).toFixed(3)) : '–');
  const h2hAB = fi(h2h.atBats), h2hAVG = fv(h2h.avg), h2hK = fi(h2h.strikeOuts);
  const hasH2H = h2hAB !== '–' && parseInt(h2h.atBats) > 0;
  const isoVal = hasCardIso ? cardIso : ((bs.slg&&bs.avg) ? parseFloat(bs.slg)-parseFloat(bs.avg) : 0);

  const vulns = [];
  if (parseFloat(ps.homeRunsPer9) > 1.2)
    vulns.push({ icon:'🔴', text: `${pitcherName} allows <strong>${pHR9} HR/9</strong> — well above league average. ${batterName} has a clear power opportunity.` });
  else if (parseFloat(ps.homeRunsPer9) > 0.9)
    vulns.push({ icon:'🟡', text: `${pitcherName} allows <strong>${pHR9} HR/9</strong> — slightly elevated HR rate. Power hitters can take advantage.` });
  else
    vulns.push({ icon:'🟢', text: `${pitcherName} limits home runs well (<strong>${pHR9} HR/9</strong>). ${batterName} will need to work for extra bases.` });

  if (parseFloat(ps.avg) > .265)
    vulns.push({ icon:'🔴', text: `Pitcher allows <strong>${pAVG} AVG</strong> — batters are making consistent contact. Look for hits up the middle.` });
  else
    vulns.push({ icon:'🟢', text: `Pitcher holds batters to <strong>${pAVG} AVG</strong>. ${batterName} will need plate discipline to get on base.` });

  if (isoVal > 0.180)
    vulns.push({ icon:'⚡', text: `${batterName} has an <strong>ISO of ${bISO}</strong> — elite extra-base power. The middle/fastball zone is the best HR opportunity.` });

  if (hasH2H && parseInt(h2h.homeRuns) > 0)
    vulns.push({ icon:'💥', text: `Career H2H: ${batterName} has hit <strong>${fi(h2h.homeRuns)} HR</strong> off ${pitcherName} in ${h2hAB} AB. Historical edge for the batter.` });
  else if (hasH2H)
    vulns.push({ icon:'📊', text: `Career H2H: ${h2hAB} AB, <strong>${h2hAVG} AVG</strong>, ${h2hK} K. Limited power history — contact approach recommended.` });

  if (parseFloat(ps.whip) > 1.35)
    vulns.push({ icon:'🎯', text: `${pitcherName} has a <strong>${pWHIP} WHIP</strong> — struggles with command. Work the count to get into hitter's counts.` });

  return vulns.map(v => `<div class="vuln-item"><span class="vuln-icon">${v.icon}</span><span style="color:var(--text)">${v.text}</span></div>`).join('');
}
async function loadHRScoutingReport(batterId, batterName, pitcherId, pitcherName, cardIso) {
  const key = `${batterId}:${pitcherId}`;
  if (hrScoutingReportCache.has(key)) return hrScoutingReportCache.get(key);
  const promise = (async () => {
    try {
      const [h2hData, batterData, pitcherData] = await Promise.all([
        fetchJSON(`https://diamondreport.app/api/v1/people/${batterId}/stats?stats=vsPlayer&opposingPlayerId=${pitcherId}&group=hitting&season=2026`),
        fetchJSON(`https://diamondreport.app/api/v1/people/${batterId}?hydrate=stats(group=hitting,type=season,season=2026)`),
        fetchJSON(`https://diamondreport.app/api/v1/people/${pitcherId}?hydrate=stats(group=pitching,type=season,season=2026)`)
      ]);
      const h2h = h2hData?.stats?.[0]?.splits?.[0]?.stat || {};
      const bs = batterData?.people?.[0]?.stats?.[0]?.splits?.[0]?.stat || {};
      const ps = pitcherData?.people?.[0]?.stats?.[0]?.splits?.[0]?.stat || {};
      return hrScoutingVulnsHTML(batterName, pitcherName, bs, ps, h2h, cardIso) ||
        '<div class="vuln-item"><span style="color:var(--muted)">No scouting signal cleared threshold for this matchup yet.</span></div>';
    } catch(e) {
      return '<div class="vuln-item"><span style="color:var(--muted)">Scouting report unavailable right now.</span></div>';
    }
  })();
  hrScoutingReportCache.set(key, promise);
  return promise;
}

function renderLineup(panelId, data, pitcherHr9, pitcherIp, oppAbbr, pitcherId, pitcherName) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const { lineup, teamAbbr } = data || {};
  const lineupIsOfficial = data?.confirmed === true || (lineup || []).some(b => b.confirmed === true);
  const lineupIsExpected = !lineupIsOfficial && data?.lineupStatus === 'expected';
  if ((!lineupIsOfficial && !lineupIsExpected) || !(lineup || []).length) {
    renderLineupPending(panelId, teamAbbr || oppAbbr || '');
    return;
  }
  const lineupBadge = lineupIsOfficial
    ? '<span style="display:inline-flex;align-items:center;gap:4px;background:#0d2a1a;border:1px solid #2ecc71;color:#2ecc71;border-radius:999px;padding:2px 8px;font-size:9px;font-weight:800;letter-spacing:.6px">✅ CONFIRMED LINEUP</span>'
    : lineupIsExpected
      ? '<span style="display:inline-flex;align-items:center;gap:4px;background:#0d1a30;border:1px solid #2f6bff;color:#7aa6ff;border-radius:999px;padding:2px 8px;font-size:9px;font-weight:800;letter-spacing:.6px">🔮 EXPECTED LINEUP</span>'
      : '<span style="display:inline-flex;align-items:center;gap:4px;background:#2a1800;border:1px solid #f4a261;color:#f4a261;border-radius:999px;padding:2px 8px;font-size:9px;font-weight:800;letter-spacing:.6px">⚠ LINEUP NOT CONFIRMED</span>';
  const lineupNotice = lineupIsExpected
    ? `<div style="margin:8px 0;padding:8px 12px;background:#0d1a30;border:1px solid rgba(47,107,255,.4);border-radius:8px;font-size:11px;color:#9fbdff;line-height:1.5">🔮 <strong>Not yet confirmed for today.</strong> Showing ${teamAbbr || oppAbbr || 'this team'}'s lineup from ${data?.expectedFromDate ? new Date(data.expectedFromDate).toLocaleDateString('en-US', {month:'short', day:'numeric'}) : 'their last game'} as a placeholder — swaps to the real batting order the moment MLB posts it.</div>`
    : '';

  function hrProb(s) {
    const ab = parseInt(s.atBats) || 0;
    const hr = parseInt(s.homeRuns) || 0;
    // hr/ab is HR-per-AT-BAT; the 0.88 factor converts it to HR-per-PLATE-APPEARANCE
    // (PA also includes walks/HBP/sac flies, so AB understates the true denominator),
    // matching the per-PA rate pitcherRate and the 0.6/0.4 blend below assume.
    const batterRate = ab > 0 ? (hr / ab) * 0.88 : 0;
    // homeRunsPer9 is allowed-per-9-innings (27 outs); a pitcher actually faces ~38
    // batters per 9 innings once baserunners allowed are counted, so dividing by 27
    // overstated the pitcher's true HR-per-batter rate.
    const pitcherRate = pitcherHr9 > 0 ? pitcherHr9 / 38 : 0.03;
    // Was hard-capped at 25 with no floor, unlike every other market's 1-99 range —
    // real per-game HR probability for a genuinely elite matchup can exceed 25%, so
    // the old cap flattened great and mediocre matchups into the same narrow band
    // and made ranking/selection nearly meaningless. See Elite Picks HR record audit.
    return Math.max(1, Math.min(((batterRate * 0.6) + (pitcherRate * 0.4)) * 100, 99));
  }

  const withProbs = applyHotHitterBoosts(lineup.map(b => ({ ...b, todayHR: (data?.gameHasStarted ? (b.todayHR || 0) : 0), hrProb: hrProb(b.stats), baseHrProb: hrProb(b.stats) })));
  const maxProb = Math.max(...withProbs.map(b => b.hrProb), 0.01);
  const topIdx = withProbs.reduce((best, b, i) => b.hrProb > withProbs[best].hrProb ? i : best, 0);
  // HR Threats' inclusion rule (getHRRows in the v10.32 IIFE) only lets the
  // single best batter per pitcher matchup in at the lower topHrThreat
  // probability bar -- with one qualifying per matchup side, the whole board
  // was hard-capped at roughly (games today x 2) players regardless of how
  // many other batters had a real case. Widened to the top 2 by hrProb here.
  // Deliberately a separate variable from topIdx, which stays single-winner
  // for this lineup panel's own "top" highlight/bar-color below.
  const topTwoIdx = new Set(withProbs.map((b, i) => i).sort((a, b) => withProbs[b].hrProb - withProbs[a].hrProb).slice(0, 2));

  // ── Feed into HR Potential if it's empty (lineups not posted via API yet) ──
  // Only for a truly confirmed lineup — an "expected" lineup is borrowed from a prior
  // game and isn't a reliable signal that this batter is even in today's game (bench day,
  // platoon, injury, roster move since that game), so it shouldn't show up as an HR
  // Threat, just as a placeholder in this lineup panel until the real order posts.
  if (pitcherId && pitcherName && lineupIsOfficial) {
    const prRow = prRows.find(r => r.pitcher.id == pitcherId);
    const timeLabel = prRow?.pitcher.timeLabel || '–';
    const timeColor = prRow?.pitcher.timeColor || 'var(--text)';
    const gameTimestamp = prRow?.pitcher.gameTimestamp || 0;
    const tAbbr = teamAbbr || oppAbbr || '–';
    const pOppAbbr = prRow?.pitcher.oppAbbr || oppAbbr || '–';

    withProbs.forEach((b, i) => {
      if (!b.id || !isActiveForHRThreat(b)) return;
      const isTopThreat = topTwoIdx.has(i);
      // Only add if not already in hrpRows; if it exists, preserve/upgrade TOP HR THREAT status
      const existing = hrpRows.find(r => r.id === b.id && r.pitcherId == pitcherId);
      if (existing) {
        existing.topHrThreat = existing.topHrThreat || isTopThreat;
        existing.hrProb = Math.max(existing.hrProb || 0, b.hrProb || 0); existing.baseHrProb = existing.baseHrProb || b.baseHrProb || b.hrProb || 0; applyHotHitterBoost(existing);
        return;
      }
      if (!existing) {
        const s = b.stats || {};
        hrpRows.push({
          id: b.id,
          name: b.name,
          pos: b.pos,
          teamAbbr: tAbbr,
          oppAbbr: pOppAbbr,
          pitcherName,
          pitcherId,
          timeLabel,
          timeColor,
          gameTimestamp,
          gamePk: prRow?.pitcher.gamePk || 0,
          stats: s,
          last10HR: b.last10HR ?? null,
          todayHR: b.todayHR || 0,
          baseHrProb: b.baseHrProb || b.hrProb,
          hrProb: b.hrProb,
          hotHitter: b.hotHitter || null,
          hotBoostPct: b.hotBoostPct || 0,
          onFireScore: b.onFireScore || 0,
          topHrThreat: isTopThreat,
          streakDays: 1,
          hrVsPitcher: null,
          avg: parseFloat(s.avg) || 0,
          hrSeason: parseInt(s.homeRuns) || 0,
          ops: parseFloat(s.ops) || 0,
          iso: (parseFloat(s.slg)||0) - (parseFloat(s.avg)||0),
          isDrought: false,
          isFavorable: (parseFloat(s.ops)||0) >= 0.800,
        });
      }
    });

    // Re-render HR Potential whenever new batter data is added from lineup
    const hrpEl = document.getElementById('hr-potential-content');
    if (hrpEl && hrpRows.length > 0) {
      renderHRPTable();
    }
  }

  function fmtS(v, dec=3) {
    if (!v || v==='---') return '–';
    const n = parseFloat(v);
    return isNaN(n) ? '–' : n.toFixed(dec).replace(/^0/,'');
  }

  // Matchup label — based on batter K% vs pitcher K/9 and batter OPS
  function matchupLabel(s) {
    const kpct = (s.strikeOuts && s.plateAppearances) ? s.strikeOuts/s.plateAppearances : 0.22;
    const ops  = parseFloat(s.ops) || 0.700;
    const pk9  = pitcherHr9 * 9 || 8.0; // proxy from hr9
    let score = 0;
    if (kpct < 0.18) score += 2; else if (kpct > 0.28) score -= 2;
    if (ops > 0.820) score += 2; else if (ops < 0.680) score -= 1;
    if (pk9 > 10.0) score -= 2; else if (pk9 < 7.0) score += 1;
    if (score >= 2) return `<span class="lbc-matchup-tag good">✓ TOUGH FOR PITCHER</span>`;
    if (score <= -2) return `<span class="lbc-matchup-tag bad">✗ TOUGH FOR BATTER</span>`;
    return `<span class="lbc-matchup-tag neutral">~ NEUTRAL MATCHUP</span>`;
  }

  const cards = withProbs.map((b, i) => {
    const s = b.stats;
    const isTop = i === topIdx; // persists regardless of todayHR
    const homerToday = b.todayHR > 0;
    const barPct = maxProb > 0 ? (b.hrProb / maxProb) * 100 : 0;
    const barColor = homerToday ? '#2f6bff' : isTop ? '#2f6bff' : b.hrProb > maxProb * 0.7 ? '#dc2626' : '#2ecc71';
    const pName = (pitcherName||'').replace(/'/g,"\\'");
    const bName = b.name.replace(/'/g,"\\'");
    const rowBg = homerToday ? 'background:linear-gradient(90deg,#2a1a00 0%,#1a1200 100%);border-left:3px solid var(--accent2);' : '';

    return `<div data-batter-id="${b.id}" class="lineup-batter-card${homerToday?' hr-today':''}">
      <div class="lbc-head">
        <span class="lbc-rank">${i+1}</span>
        <span class="lbc-name">${b.name}</span>
        <span class="lbc-pos">${b.pos}</span>
        ${homerToday ? `<span class="hr-today-badge lbc-tag-hrtoday">💥 HR TODAY${b.todayHR>1?' x'+b.todayHR:''}</span>` : ''}
        ${isTop ? `<span class="top-hr-badge lbc-tag-tophr">⚡ TOP HR THREAT</span>` : ''}
        ${b.isOnFire ? `<span class="lbc-tag-onfire">🔥 ON FIRE</span>` : ''}
        ${b.rosterStatus ? `<span class="lbc-tag-injured" title="${b.rosterStatus}">🏥 ${b.rosterStatus}</span>` : ''}
        ${matchupLabel(s)}
        <button class="lbc-matchup-btn" onclick="openMatchup(${b.id},'${bName}',${pitcherId},'${pName}')" title="Batter vs Pitcher analysis">⚔ Matchup</button>
      </div>
      <div class="lbc-stats">
        ${buildBatterStatsLine(b)}
      </div>
    </div>`;
  }).join('');

  const now = new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
  panel.innerHTML = `
    <div style="padding:4px 0 10px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px">
      <span style="font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--accent)">
        ${teamAbbr || oppAbbr || ''} BATTING LINEUP ${lineupBadge}
      </span>
      <div style="display:flex;gap:10px;align-items:center;font-size:10px;color:var(--muted);flex-wrap:wrap">
        <span><span style="color:var(--accent2)">💥 HR TODAY</span> = homered this game</span>
        <span><span style="color:#90ee60">L10</span> = HRs in last 10 games</span>
        <span>⚔ for matchup</span>
        <span class="lineup-timestamp" style="font-family:'JetBrains Mono',monospace;color:var(--border)">Auto-checking official lineup${data.source ? ` • ${data.source}` : ''}${data.confirmedAt ? ` • confirmed ${new Date(data.confirmedAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}` : ''}</span>
      </div>
    </div>
    ${lineupNotice}
    ${cards}`;
}

function sortPR(col) {
  if (prSortCol===col) prSortDir*=-1;
  else { prSortCol=col; prSortDir = col==='hr9' ? -1 : 1; }
  renderPRTable();
}

function resetPRSort() {
  prSortCol = 'hr9';
  prSortDir = -1;
  prHandFilter = 'all';
  renderPRTable();
}

// ALL/vs RHB/vs LHB toggle for the HR/9 column -- see prHr9ForRow's own
// comment for why this is the one column that can actually change (the real
// hand-split data only exists for HR/9, not the table's other stats).
window.setPRHandFilter = function(hand) {
  prHandFilter = (hand === 'R' || hand === 'L') ? hand : 'all';
  renderPRTable();
};


// ── GAME PROPS ────────────────────────────────────────────────────────
// In-memory-only (never localStorage) short-TTL cache for the Open-Meteo weather
// lookup below — see the comment at its call site for why this can't reuse
// fetchJSON's day-long cache.
const _weatherCache = new Map();

// Weather (Open-Meteo, free, no key) — shared by loadGameProps (the DRP "HR Boost"
// badge/projected-total model) and loadHRPotential (HR Threats' per-batter hrProb).
// Deliberately NOT routed through fetchJSON(): that helper caches any non-live-score
// URL in localStorage for the rest of the calendar day (DR_STATIC_DAILY_DUMP), which
// is right for daily-batch Statcast files but wrong here — temperature and wind
// genuinely change over the course of a day, so a morning fetch (cooler) would
// otherwise get locked in and reused all afternoon even on a hot day. A short
// in-memory cache keyed to a 15-minute bucket keeps this fresh without re-fetching on
// every 2-minute auto-refresh, and is shared (module-level _weatherCache) across both
// callers so visiting both boards in one session only pays for each game's weather once.
// gameTimestamp (ms, optional) lets a pre-game call get the FORECAST for first
// pitch instead of the reading at fetch time — a 7pm game checked at 1pm was
// otherwise getting locked into an afternoon temp/wind reading for its entire
// pre-game life. Only kicks in more than 20 min before first pitch; once a game
// is live/imminent, `current` already IS game-time weather, so there's no reason
// to prefer a forecast bucket over the real live reading.
function pickWeatherHourly(wd, gameTimestamp) {
  const useForecast = !!gameTimestamp && gameTimestamp > Date.now() + 20 * 60 * 1000;
  const anchor = useForecast ? gameTimestamp : Date.now();
  const h = wd.hourly;
  let hourlySlice = [];
  if (h?.time?.length) {
    let bestIdx = -1, bestDiff = Infinity;
    for (let i = 0; i < h.time.length; i++) {
      // Open-Meteo's hourly.time strings are naive ("2026-08-02T19:00") in the
      // timezone we requested (GMT, forced below) — appending "Z" is required or
      // Date() parses them in the browser's local zone instead of UTC.
      const diff = Math.abs(new Date(h.time[i] + 'Z').getTime() - anchor);
      if (diff < bestDiff) { bestDiff = diff; bestIdx = i; }
    }
    if (bestIdx >= 0) {
      // Up to 5 consecutive hours starting at the anchor (first pitch when
      // still pre-game, "now" once the game's underway) -- same closest-
      // real-bucket lookup already used for the single-point `c` below, just
      // kept as a short forward slice instead of collapsed to one value, for
      // the hourly forecast strip.
      const HOURLY_SLICE_SIZE = 5;
      for (let i = bestIdx; i < Math.min(h.time.length, bestIdx + HOURLY_SLICE_SIZE); i++) {
        hourlySlice.push({
          time: h.time[i],
          temp: Math.round(h.temperature_2m[i]),
          precip: h.precipitation[i],
          // Real Open-Meteo field (%), NOT derived from precip (mm) -- a rain
          // amount and a rain probability are different quantities, see this
          // fetch's own &hourly= comment above.
          precipProb: Array.isArray(h.precipitation_probability) ? h.precipitation_probability[i] : null,
          wind: Math.round(h.windspeed_10m[i]),
          windDir: h.winddirection_10m[i],
          code: h.weathercode[i],
        });
      }
      if (useForecast) {
        return {
          c: {
            temperature_2m: h.temperature_2m[bestIdx],
            relative_humidity_2m: h.relative_humidity_2m[bestIdx],
            windspeed_10m: h.windspeed_10m[bestIdx],
            winddirection_10m: h.winddirection_10m[bestIdx],
            precipitation: h.precipitation[bestIdx],
            pressure_msl: h.pressure_msl[bestIdx],
            weathercode: h.weathercode[bestIdx],
          },
          forecast: true,
          hourlySlice,
        };
      }
    }
  }
  return { c: wd.current, forecast: false, hourlySlice };
}
async function fetchGameWeather(homeAbbr, awayAbbr, gameTimestamp) {
  // Retractable-roof parks (ARI, HOU, MIA, MIL, SEA, TEX, TOR) are frequently played
  // open-air, so they still get a live weather fetch — only Tropicana Field (TB) is a
  // genuine fixed dome that's never open. Open-Meteo has no live roof-open/closed
  // signal, so this fetches outdoor conditions for those parks regardless of actual
  // roof state; better than always reporting neutral.
  const stadium = stadiumCoords[homeAbbr] || stadiumCoords[awayAbbr];
  if (!stadium || (stadium.dome && !stadium.retractable)) return null;
  try {
    const bucket = Math.floor(Date.now() / (15 * 60 * 1000));
    const wKey = `${homeAbbr}:${bucket}`;
    let wd = _weatherCache.get(wKey);
    if (!wd) {
      // relative_humidity_2m + pressure_msl added for the air-density-based HR Boost
      // model (see airDensityHRMult) — pressure_msl (sea-level-equivalent, not
      // surface_pressure) is deliberate: it isolates today's weather-system pressure
      // anomaly from each park's permanent elevation, which the separate Statcast-
      // based park factor already accounts for. Using raw surface_pressure here would
      // double-count Coors' altitude as if it were a "weather" effect every single day.
      // hourly+forecast_days=2 (timezone forced to GMT) backs pickWeatherHourly's
      // pre-game first-pitch lookup above; forecast_days=2 covers a UTC day rollover
      // for late West Coast games without inflating the payload further.
      // precipitation_probability is hourly-only (Open-Meteo has no "current"
      // variant of it -- a probability is inherently a forecast concept, there's
      // no "current probability of rain"), so it's added only to &hourly=, not
      // &current=. Used by the hourly forecast strip below; the existing
      // current-point weather.precip elsewhere in this file stays as `precipitation`
      // (real millimeters, not a probability) exactly as it already was.
      const res = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${stadium.lat}&longitude=${stadium.lon}&current=temperature_2m,relative_humidity_2m,windspeed_10m,winddirection_10m,precipitation,pressure_msl,weathercode&hourly=temperature_2m,relative_humidity_2m,windspeed_10m,winddirection_10m,precipitation,precipitation_probability,pressure_msl,weathercode&forecast_days=2&timezone=GMT&temperature_unit=fahrenheit&windspeed_unit=mph`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      wd = await res.json();
      _weatherCache.set(wKey, wd);
    }
    const { c, forecast, hourlySlice } = pickWeatherHourly(wd, gameTimestamp);
    return {
      temp: Math.round(c.temperature_2m),
      humidity: c.relative_humidity_2m,
      wind: Math.round(c.windspeed_10m),
      windDir: c.winddirection_10m,
      precip: c.precipitation,
      pressureMsl: c.pressure_msl,
      code: c.weathercode,
      isForecast: forecast,
      hourlyForecast: hourlySlice || [],
    };
  } catch { return null; }
}

// Market odds (display-only comparison, see loadEspnEventIds/model.market below) —
// same in-memory 15-min-bucket pattern as weather, never persisted to localStorage.
const _marketCache = new Map();
let _espnEventIdByAbbrPair = {};
let _espnEventIdLoadedForDate = null;
// ESPN's team abbreviations mostly match the MLB Stats API ones this file uses
// everywhere else, except the White Sox (ESPN: CHW, this file: CWS throughout
// parkFactors/teamColors/stadiumCoords). Add more pairs here if another mismatch
// turns up.
const ESPN_ABBR_TO_DR = { CHW: 'CWS' };
function normalizeEspnAbbr(abbr) { return ESPN_ABBR_TO_DR[abbr] || abbr; }

// Bulk-fetches today's MLB scoreboard once (free, no key, same ESPN host already
// used for league news) purely to map each matchup to ESPN's numeric event id —
// the per-game summary endpoint below is what actually has clean moneylines for
// both teams. Split into two calls (bulk id lookup + per-game summary) rather than
// one, since the scoreboard endpoint's own embedded odds only expose the favorite's
// line as a text string ("PHI -172"), not a clean number for the underdog side.
async function loadEspnEventIds(todayCDT) {
  if (_espnEventIdLoadedForDate === todayCDT) return;
  try {
    const res = await fetch('https://site.api.espn.com/apis/site/v2/sports/baseball/mlb/scoreboard');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const byAbbrPair = {};
    (data.events || []).forEach(ev => {
      const competitors = ev.competitions?.[0]?.competitors || [];
      const away = competitors.find(c => c.homeAway === 'away');
      const home = competitors.find(c => c.homeAway === 'home');
      const awayAbbr = normalizeEspnAbbr(away?.team?.abbreviation);
      const homeAbbr = normalizeEspnAbbr(home?.team?.abbreviation);
      if (awayAbbr && homeAbbr) byAbbrPair[`${awayAbbr}@${homeAbbr}`] = ev.id;
    });
    _espnEventIdByAbbrPair = byAbbrPair;
    _espnEventIdLoadedForDate = todayCDT;
  } catch {}
}

// Real DraftKings-via-ESPN moneylines for a specific matchup, converted to a
// no-vig (vig-removed) implied win% for a clean apples-to-apples comparison
// against the DR model's own win%. Display-only — see the call site in
// loadGameProps for why this never feeds into awayScore/homeScore or any other
// scoring input.
async function getMarketOdds(awayAbbr, homeAbbr) {
  const eventId = _espnEventIdByAbbrPair[`${awayAbbr}@${homeAbbr}`];
  if (!eventId) return null;
  try {
    const bucket = Math.floor(Date.now() / (15 * 60 * 1000));
    const cacheKey = `${eventId}:${bucket}`;
    let pc = _marketCache.get(cacheKey);
    if (pc === undefined) {
      const res = await fetch(`https://site.api.espn.com/apis/site/v2/sports/baseball/mlb/summary?event=${eventId}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const summary = await res.json();
      pc = summary.pickcenter?.[0] || null;
      _marketCache.set(cacheKey, pc);
    }
    const awayML = pc?.awayTeamOdds?.moneyLine;
    const homeML = pc?.homeTeamOdds?.moneyLine;
    if (typeof awayML !== 'number' || typeof homeML !== 'number') return null;
    const impliedProb = (ml) => ml < 0 ? (-ml) / (-ml + 100) : 100 / (ml + 100);
    const awayImplied = impliedProb(awayML);
    const homeImplied = impliedProb(homeML);
    const vigTotal = awayImplied + homeImplied; // >1 due to vig — normalize it out
    return {
      provider: pc.provider?.name || 'Market',
      awayML, homeML,
      awayPct: Math.round((awayImplied / vigTotal) * 100),
      homePct: Math.round((homeImplied / vigTotal) * 100),
      overUnder: typeof pc.overUnder === 'number' ? pc.overUnder : null,
    };
  } catch { return null; }
}
