// ── Interactive visualization tap-tooltip (roadmap 5.3) ────────────────
// The Strike Zone Matchup / Attack Zone by Pitch / HR Zones grids already carry a
// per-cell description via the native title attribute (color-coded cells) or an SVG
// <title> child (HR Zones' scatter dots) -- both work as a hover tooltip on desktop,
// but neither has any mobile-tap equivalent (a phone has no "hover" state at all), so
// a mobile user could see the color-coding but never actually read what a given cell
// or dot means. Reuses the exact same title text (no separate copy to keep in sync)
// in a small floating popover on tap, auto-dismissing after a few seconds or on the
// next tap elsewhere -- desktop hover behavior is completely untouched.
document.addEventListener('click', function(e) {
  const existing = document.getElementById('dr-viz-tooltip');
  if (existing) existing.remove();
  const target = e.target.closest && e.target.closest('.zone-section .sz-cell[title], .zone-section circle');
  if (!target) return;
  const text = target.getAttribute('title') || (target.querySelector('title') ? target.querySelector('title').textContent : '');
  if (!text) return;
  const tip = document.createElement('div');
  tip.id = 'dr-viz-tooltip';
  tip.className = 'dr-viz-tooltip';
  tip.textContent = text;
  document.body.appendChild(tip);
  const rect = target.getBoundingClientRect();
  const left = Math.min(window.innerWidth - tip.offsetWidth - 8, Math.max(8, rect.left + rect.width / 2 - tip.offsetWidth / 2));
  const top = Math.max(8, rect.top + window.scrollY - tip.offsetHeight - 8);
  tip.style.left = left + 'px';
  tip.style.top = top + 'px';
  setTimeout(function () { if (tip.parentNode) tip.remove(); }, 3500);
});


// ── HEADER DATE (dynamic) ─────────────────────────────────────────────
function updateHeaderDate() {
  const now = new Date();
  const label = now.toLocaleDateString('en-US', {weekday:'short', month:'short', day:'numeric', year:'numeric', timeZone:'America/Chicago'}).toUpperCase();
  const el = document.getElementById('header-date');
  if (el) el.textContent = label;
}
updateHeaderDate();

// ── MIDNIGHT AUTO-REFRESH ─────────────────────────────────────────────
function scheduleMidnightRefresh() {
  const now = new Date();
  const midnight = new Date();
  midnight.setHours(24, 0, 5, 0); // 12:00:05am to ensure day has flipped
  const msUntilMidnight = midnight - now;
  setTimeout(() => {
    updateHeaderDate();
    Object.keys(prevGames).forEach(k => delete prevGames[k]); // clear game cache
    loadScores(); // reload with new day's games
    scheduleMidnightRefresh(); // reschedule for next midnight
  }, msUntilMidnight);
}
scheduleMidnightRefresh();


// ── HOT HITTER HR POTENTIAL ENGINE ───────────────────────────────────
// Uses repo-fed Baseball Savant/Statcast trend data when available. If the
// GitHub Action has not populated data/statcast-hot-hitters.json yet, the
// model falls back to the live MLB stats already on the page.
async function loadStatcastHotHitters(force=false) {
  if (statcastHotHittersLoaded && !force) return statcastHotHitters;
  if (statcastHotHittersPromise && !force) return statcastHotHittersPromise;
  statcastHotHittersPromise = (async () => {
    try {
      const data = await drFetchDailyJSON(`data/statcast-hot-hitters.json`);
      const list = Array.isArray(data.players) ? data.players : [];
      statcastHotHitters = {};
      list.forEach(p => {
        if (p.playerId) statcastHotHitters[String(p.playerId)] = p;
        if (p.name) statcastHotHitters[String(p.name).toLowerCase()] = p;
      });
    } catch(e) {
      statcastHotHitters = {};
    }
    statcastHotHittersLoaded = true;
    return statcastHotHitters;
  })();
  return statcastHotHittersPromise;
}
// Same repo-fed-JSON-with-graceful-fallback pattern as loadStatcastHotHitters()
// above — data/near-hrs.json is keyed by batter ID already, so this just
// normalizes the ID to a string for lookup consistency with the rest of the app.
async function loadNearHRs(force=false) {
  if (nearHRsLoaded && !force) return nearHRs;
  if (nearHRsPromise && !force) return nearHRsPromise;
  nearHRsPromise = (async () => {
    try {
      const data = await drFetchDailyJSON(`data/near-hrs.json`);
      const players = data.players || {};
      nearHRs = {};
      Object.keys(players).forEach(id => { nearHRs[String(id)] = players[id]; });
    } catch(e) {
      nearHRs = {};
    }
    nearHRsLoaded = true;
    return nearHRs;
  })();
  return nearHRsPromise;
}
