function renderNearHRs() {
  const el = document.getElementById('near-hrs-content');
  if (!el) return;
  const countEl = document.getElementById('near-hrs-count');
  const ids = Object.keys(nearHRs || {}).filter(id => Array.isArray(nearHRs[id]) && nearHRs[id].length);

  if (!ids.length) {
    el.innerHTML = `<div class="mu-empty" style="color:var(--muted)">No warning-track fly outs (375+ ft) in the last 10 games for tracked batters.</div>`;
    if (countEl) countEl.style.display = 'none';
    return;
  }

  const players = ids.map(id => {
    const info = statcastHotHitters[id] || {};
    return {
      id,
      name: drFormatNearHRName(info.name) || `Player ${id}`,
      teamAbbr: info.teamAbbr || null,
      events: nearHRs[id].slice().sort((a, b) => (b.distance || 0) - (a.distance || 0))
    };
  }).filter(p => drMatchesSearch('nearhr', p.name));

  // "YYYY-MM-DD" strings sort correctly with plain string comparison -- no
  // need to parse into real Date objects just to find each player's latest event.
  const mostRecentDate = p => p.events.reduce((m, e) => (e.date && e.date > m) ? e.date : m, '');
  const sortBy = getNearHRSortBy();
  players.sort((a, b) => {
    if (sortBy === 'longest') return ((b.events[0]?.distance || 0) - (a.events[0]?.distance || 0)) || (b.events.length - a.events.length);
    if (sortBy === 'recent') return mostRecentDate(b).localeCompare(mostRecentDate(a)) || (b.events.length - a.events.length);
    return (b.events.length - a.events.length) || ((b.events[0]?.distance || 0) - (a.events[0]?.distance || 0));
  });

  if (!players.length) {
    el.innerHTML = `<div class="mu-empty" style="color:var(--muted)">No players match your search.</div>`;
    if (countEl) countEl.style.display = 'none';
    return;
  }

  if (countEl) {
    countEl.textContent = `${players.length} Player${players.length !== 1 ? 's' : ''}`;
    countEl.style.cssText = 'background:var(--accent);color:white;font-family:Manrope,sans-serif;font-size:12px;font-weight:700;padding:2px 8px;border-radius:10px;display:inline-block;letter-spacing:.5px;flex-shrink:0';
  }

  const viewMode = (window.innerWidth <= 768) ? 'cards' : 'table';
  _nearHRLastViewMode = viewMode;
  if (viewMode === 'table') {
    const tableBody = players.map((p, i) => nearHRTableRowHTML(p, i)).join('');
    el.innerHTML = `<div class="hrpt-shell"><div class="hrpt-scroll"><table class="hrpt-table nearhrt-table"><thead><tr>${nearHRTableHeaderHTML()}</tr></thead><tbody>${tableBody}</tbody></table></div></div>`;
  } else {
    const cards = players.map((p, i) => nearHRCardHTML(p, i)).join('');
    el.innerHTML = `<div class="dr1027-hr-card-list">${cards}</div>`;
    drFillMeters(el);
  }
}
window.renderNearHRs = renderNearHRs;

