    var statChips = [
      hrChip('Zone Fit', r.zoneFitScore == null ? '–' : r.zoneFitScore + '/100', r.zoneFitScore == null ? '' : r.zoneFitScore >= 72 ? 'green' : r.zoneFitScore >= 58 ? 'gold' : ''),
      hrChip('Barrel%', hh && hh.barrelPct != null ? parseFloat(hh.barrelPct)+'%' : '–', hh && n(hh.barrelPct) >= 10 ? 'green' : ''),
      hrChip('Hard-Hit%', hh && hh.hardHitPct != null ? parseFloat(hh.hardHitPct)+'%' : '–', hh && n(hh.hardHitPct) >= 40 ? 'green' : ''),
      hrChip('Avg Exit Velo', hh && hh.avgExitVelo != null ? parseFloat(hh.avgExitVelo)+' mph' : '–', hh && n(hh.avgExitVelo) >= 90 ? 'green' : ''),
      hrChip('Ballpark Factor', bpPct != null ? (bpPct>0?'+':'')+bpPct+'%' : '–', bpPct>0?'green':bpPct<0?'red':''),
      hrChip('L10 GM HR', l10==null?'–':l10, n(l10)>=2?'green':''),
    ].filter(Boolean);
    var uid = 'featured-hrp-' + r.id + '-' + (r.pitcherId||0);
    return '<div class="dr1027-hr-card dr1027-featured-pick" style="cursor:pointer" onclick="if(!event.target.closest(\'button,a\')){openMatchup('+JSON.stringify(String(r.id))+','+JSON.stringify(r.name||'')+','+JSON.stringify(String(r.pitcherId||''))+','+JSON.stringify(r.pitcherName||'')+','+JSON.stringify(r.zoneFitScore??null)+');}">'
