/* v11.31: Pause infinite CSS animations when the tab is hidden or the
   element is scrolled off-screen. Targets the live-dot pulse, skeleton
   shimmer, spin loaders, and countdown pulse -- these were running
   continuously with no pause logic, costing GPU/compositor time even when
   nothing animated was actually visible. Pairs with the .dr-paused /
   .dr-anim-offscreen CSS rules added alongside this. */
(function(){
  var ANIM_SELECTOR = '.live-dot, .dr-v9-skeleton, .game-status.countdown-pulse, .spin, .ks-today-live';

  // Pause everything site-wide while the tab/app is backgrounded.
  document.addEventListener('visibilitychange', function(){
    document.body.classList.toggle('dr-paused', document.hidden);
  });
  if (document.hidden) document.body.classList.add('dr-paused');

  // Pause per-element when it scrolls out of the viewport (with a small
  // margin so it resumes just before it would come back into view).
  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      entry.target.classList.toggle('dr-anim-offscreen', !entry.isIntersecting);
    });
  }, { rootMargin: '150px 0px' }) : null;

  function observeAnimatedElements(){
    if (!io) return;
    document.querySelectorAll(ANIM_SELECTOR).forEach(function(el){
      if (!el.dataset.drAnimObserved) {
        el.dataset.drAnimObserved = '1';
        io.observe(el);
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', observeAnimatedElements, { once: true });
  } else {
    observeAnimatedElements();
  }

  // Live data refreshes create/remove these elements dynamically (new game
  // cards, new skeleton loaders, etc.), so periodically pick up new ones.
  // Only scans while the tab is visible -- no work done in the background.
  setInterval(function(){
    if (document.visibilityState === 'visible') observeAnimatedElements();
  }, 5000);
})();

// Desktop top nav — lives inside the header itself now (sports categories
// left, logo pushed right), but is otherwise a separate element from the
// mobile hamburger drawer (#dr-mobile-drawer), so this never touches that
// drawer's open/close behavior. Clicking a board inside the Baseball
// dropdown routes through the same window.DiamondNavigateToPane the mobile
// drawer already uses.
//
// Active-state highlighting is handled manually here rather than relying on
// the existing .gamepick-tab sync (activateGamePickPane/setDesktopTabState):
// both of those scope their tab query to root = document.getElementById('props'),
// and this nav lives outside #props — so it would never get found by that
// scoped query.
(function(){
  // One descriptor per real dropdown category (Baseball, WNBA -- each has
  // more than one board). NFL stays a single plain pill (one board, no
  // dropdown) and isn't in this list -- its click handling lives in the
  // separate `.dr-top-nav-cat-btn[data-gamepick-pane][data-sport]` query
  // below, which only matches elements that carry those attributes directly
  // (dropdown trigger buttons don't).
  var DROPDOWN_DEFS = [
    { key: 'baseball', btnId: 'dr-top-nav-baseball-btn', menuId: 'dr-top-nav-baseball-menu', currentId: 'dr-top-nav-baseball-current' },
    { key: 'wnba', btnId: 'dr-top-nav-wnba-btn', menuId: 'dr-top-nav-wnba-menu', currentId: 'dr-top-nav-wnba-current' },
  ];

  function closeMenu(dd){
    dd.menu.classList.remove('open');
    dd.menu.setAttribute('aria-hidden', 'true');
    dd.catBtn.setAttribute('aria-expanded', 'false');
  }
  function openMenu(dd, header){
    // .dr-top-nav-menu lives as a sibling of .dr-top-nav-inner (not nested
    // inside it) so that row's own overflow-x:auto scroll fallback can't
    // clip it -- see the comment in index.html. That means it isn't
    // naturally positioned under the button, so align its left edge here
    // each time it opens (covers the row being horizontally scrolled at
    // narrower widths), relative to .header -- the nearest positioned
    // ancestor now that this nav lives inside it.
    var headerRect = header.getBoundingClientRect();
    var btnRect = dd.catBtn.getBoundingClientRect();
    dd.menu.style.left = (btnRect.left - headerRect.left) + 'px';
    dd.menu.classList.add('open');
    dd.menu.setAttribute('aria-hidden', 'false');
    dd.catBtn.setAttribute('aria-expanded', 'true');
  }
  function closeAllMenus(except){
    DROPDOWN_DEFS.forEach(function(dd){
      if (dd !== except && dd.menu && dd.menu.classList.contains('open')) closeMenu(dd);
    });
  }
  function dropdownOwning(el){
    var menuEl = el.closest ? el.closest('.dr-top-nav-menu') : null;
    if (!menuEl) return null;
    for (var i = 0; i < DROPDOWN_DEFS.length; i++) {
      if (DROPDOWN_DEFS[i].menu === menuEl) return DROPDOWN_DEFS[i];
    }
    return null;
  }
  function syncActive(header, pane){
    header.querySelectorAll('.dr-top-nav-tab[data-gamepick-pane]').forEach(function(btn){
      var isActive = btn.getAttribute('data-gamepick-pane') === pane;
      btn.classList.toggle('active', isActive);
      if (isActive) {
        var dd = dropdownOwning(btn);
        if (dd) {
          if (dd.currentLabel) dd.currentLabel.textContent = btn.querySelector('span') ? btn.querySelector('span').textContent : '';
          if (dd.catBtn) dd.catBtn.classList.add('active');
        }
      }
    });
    DROPDOWN_DEFS.forEach(function(dd){
      if (!dd.catBtn) return;
      var hasActiveTab = dd.menu && dd.menu.querySelector('.dr-top-nav-tab.active[data-gamepick-pane="' + pane + '"]');
      if (!hasActiveTab) dd.catBtn.classList.remove('active');
    });
    // NFL's own single-board pill (not part of any dropdown) gets the same
    // active highlight directly on the pill itself.
    header.querySelectorAll('.dr-top-nav-cat-btn[data-gamepick-pane]').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-gamepick-pane') === pane);
    });
  }
  function bind(){
    var header = document.querySelector('.header');
    if (!header) return;

    DROPDOWN_DEFS.forEach(function(dd){
      dd.catBtn = document.getElementById(dd.btnId);
      dd.menu = document.getElementById(dd.menuId);
      dd.currentLabel = document.getElementById(dd.currentId);
      if (!dd.catBtn || !dd.menu || dd.catBtn.dataset.drTopNavReady) return;
      dd.catBtn.dataset.drTopNavReady = '1';
      dd.catBtn.addEventListener('click', function(e){
        e.stopPropagation();
        if (dd.menu.classList.contains('open')) closeMenu(dd);
        else { closeAllMenus(dd); openMenu(dd, header); }
      });
    });
    document.addEventListener('click', function(e){
      DROPDOWN_DEFS.forEach(function(dd){
        if (dd.menu && dd.menu.classList.contains('open') && !dd.menu.contains(e.target) && e.target !== dd.catBtn) closeMenu(dd);
      });
    });
    document.addEventListener('keydown', function(e){
      if (e.key === 'Escape') closeAllMenus(null);
    });

    header.querySelectorAll('.dr-top-nav-tab[data-gamepick-pane]').forEach(function(btn){
      if (btn.dataset.drTopNavReady) return;
      btn.dataset.drTopNavReady = '1';
      btn.addEventListener('click', function(){
        var pane = btn.getAttribute('data-gamepick-pane');
        var sport = btn.getAttribute('data-sport');
        if (sport && typeof window.setActiveSport === 'function') window.setActiveSport(sport);
        syncActive(header, pane);
        var owner = dropdownOwning(btn);
        if (owner) closeMenu(owner);
        if (typeof window.DiamondNavigateToPane === 'function') window.DiamondNavigateToPane(pane);
      });
    });
    // NFL: a single-board category, no dropdown -- clicking routes straight
    // into that sport's one board. Also flips the sport context (body class,
    // mobile drawer filtering) the same way the hub cards' own click
    // handlers already do via setActiveSport, since this desktop pill is a
    // second, independent entry point into the same pane.
    header.querySelectorAll('.dr-top-nav-cat-btn[data-gamepick-pane][data-sport]').forEach(function(btn){
      if (btn.dataset.drTopNavReady) return;
      btn.dataset.drTopNavReady = '1';
      btn.addEventListener('click', function(){
        var pane = btn.getAttribute('data-gamepick-pane');
        var sport = btn.getAttribute('data-sport');
        if (typeof window.setActiveSport === 'function') window.setActiveSport(sport);
        syncActive(header, pane);
        if (typeof window.DiamondNavigateToPane === 'function') window.DiamondNavigateToPane(pane);
      });
    });
    // Initial state: match whatever pane the page booted into (hash-restored
    // or default), read from the already-rendered #props panes.
    var activePane = document.querySelector('#props .gamepick-pane.active');
    if (activePane) syncActive(header, activePane.getAttribute('data-gamepick-pane'));
    window.addEventListener('hashchange', function(){
      setTimeout(function(){
        var p = document.querySelector('#props .gamepick-pane.active');
        if (p) syncActive(header, p.getAttribute('data-gamepick-pane'));
      }, 30);
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, { once:true });
  else bind();
  window.addEventListener('load', bind, { once:true });
})();

// Landing hub ("The Sports Desk") — default view for a fresh visit with no
// #gamepick= hash; hidden once a sport is entered. Every route into a pane
// (the static desktop tabs' onclick, the mobile drawer, the desktop sidebar)
// ultimately calls window.showGamePickPane, so wrapping that is enough to
// hide the hub from any entry point without touching the nav's own code —
// same non-invasive wrap pattern already used elsewhere in this file (see
// window.showGamePickPane wraps above).
(function(){
  var newsLoaded = false;
  var newsArticlesAll = [];
  var newsArticles = [];
  var newsVisibleCount = 10;
  var headlinesAll = [];
  var headlinesVisibleCount = 6;
  var activeHeadlineCategory = 'all';
  // Categories collapsed into the synthetic "more" filter chip (real count below
  // MIN_HEADLINE_CHIP_COUNT today) -- populated by renderHeadlineFilters, read by
  // filteredHeadlines. See renderHeadlineFilters' own comment for why this is
  // purely count-driven rather than a hardcoded list of "small" categories.
  var smallHeadlineCategories = [];
  var activeSport = 'all';
  var hrLoaded = false;
  var leadersLoaded = false;
  var projectionsLoaded = false;
  var yesterdayScoresLoaded = false;
  var scoreboardTimer = null;
  var gameContentCache = {};
  var gameFeedCache = {};

  function hashIsGamepick(){
    return /^#?gamepick=/.test(window.location.hash || '');
  }

  function showHub(){
    document.body.classList.add('dr-hub-active');
    loadDailyBriefing();
    renderWatchlistSection();
    loadFeaturedPlayer();
    loadHubHeadlines();
    loadHRCarousel();
    loadTrendingPlayers();
    loadHubNews();
    loadHubHRs();
    loadHubLeaders();
    loadHubProjections();
    loadHubScoreboard();
    loadHubYesterdayScores();
    if (!scoreboardTimer) scoreboardTimer = setInterval(loadHubScoreboard, 120000);
  }

  function hideHub(){
    document.body.classList.remove('dr-hub-active');
    if (scoreboardTimer) { clearInterval(scoreboardTimer); scoreboardTimer = null; }
  }

  // Multi-Sport News and Navigation (roadmap 3.x): switches which sport the
  // hub feed is scoped to. "all" (default) is the combined feed across every
  // sport we cover; "MLB" is the same feed narrowed to MLB; "NFL"/"NBA" have
  // no real analytics behind them yet, so they show real filtered ESPN news
  // (applyNewsSportFilter) plus an honest "launching soon" notice in place of
  // the MLB-only Diamond Report Headlines/scoreboard/leaders modules -- see
  // the body.dr-hub-sport-nfl/nba rules in styles.css that force those
  // sections hidden regardless of their own lazy-loaders' display state.
  // NBA is the only sport left with no real board behind it -- NFL joined
  // MLB/WNBA as a genuinely live section once its Anytime TD board was
  // hub-linked, so it's no longer in isOtherSport/this text below.
  var SPORT_COMINGSOON_TEXT = {
    NBA: "NBA projections and leaderboards are in the works. In the meantime, here's what's happening around the NBA:"
  };
  function setActiveSport(sport){
    if (activeSport === sport) return;
    activeSport = sport;
    document.body.classList.remove('dr-hub-sport-all', 'dr-hub-sport-mlb', 'dr-hub-sport-nfl', 'dr-hub-sport-nba', 'dr-hub-sport-wnba');
    document.body.classList.add('dr-hub-sport-' + sport.toLowerCase());

    document.querySelectorAll('.dr-hub-sporttab').forEach(function(btn){
      var on = btn.getAttribute('data-sport') === sport;
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    document.querySelectorAll('.dr-hub-sport-card[data-sport]').forEach(function(card){
      card.classList.toggle('current', card.getAttribute('data-sport') === sport);
    });

    var isOtherSport = sport === 'NBA';
    var comingSoon = document.getElementById('dr-hub-sport-comingsoon');
    var comingSoonText = document.getElementById('dr-hub-sport-comingsoon-text');
    if (comingSoon) comingSoon.style.display = isOtherSport ? '' : 'none';
    if (comingSoonText) comingSoonText.textContent = isOtherSport ? (SPORT_COMINGSOON_TEXT[sport] || '') : '';

    if (newsArticlesAll.length) applyNewsSportFilter();

    updateMobileMenuSport(sport);
  }
  window.setActiveSport = setActiveSport;

  // The mobile hamburger drawer (#dr-mobile-drawer, index.html) lists board
  // shortcuts (.dr-menu-item[data-tab]) -- previously a single fixed MLB-only
  // list regardless of which sport was active. Each item now also carries a
  // data-sport (see index.html), and this keeps the drawer showing only the
  // active sport's boards. NBA (the only sport with no real board yet) falls
  // back to the MLB list, same as 'all' does.
  function updateMobileMenuSport(sport){
    var showSport = (sport === 'NFL' || sport === 'WNBA') ? sport : 'MLB';
    document.querySelectorAll('.dr-menu-item[data-sport]').forEach(function(item){
      // .dr-menu-item itself carries "display:flex !important" in styles.css --
      // toggling item.style.display here would silently lose to that rule, so
      // this toggles a higher-specificity class instead (see
      // #dr-mobile-drawer .dr-menu-item.dr-menu-item-hidden in styles.css).
      item.classList.toggle('dr-menu-item-hidden', item.getAttribute('data-sport') !== showSport);
    });
  }

  function escapeHtml(s){
    return String(s || '').replace(/[&<>"']/g, function(c){
      return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
    });
  }

  function timeAgo(iso){
    var t = new Date(iso).getTime();
    if (!t || isNaN(t)) return '';
    var minutes = Math.max(1, Math.round((Date.now() - t) / 60000));
    if (minutes < 60) return minutes + 'm ago';
    var hours = Math.round(minutes / 60);
    if (hours < 24) return hours + 'h ago';
    return Math.round(hours / 24) + 'd ago';
  }

  function renderHubNews(articles){
    var section = document.getElementById('dr-hub-news');
    var grid = document.getElementById('dr-hub-news-grid');
    if (!section || !grid || !articles || !articles.length) return;
    newsArticlesAll = articles;
    applyNewsSportFilter();

    var moreBtn = document.getElementById('dr-hub-news-more');
    if (moreBtn && !moreBtn.dataset.drBound) {
      moreBtn.dataset.drBound = '1';
      moreBtn.addEventListener('click', function(){
        newsVisibleCount = Math.min(newsVisibleCount + 10, newsArticles.length);
        renderNewsGrid();
      });
    }
  }

  // Re-scopes the already-fetched, already-league-tagged news feed (see
  // fetchLeagueNews/loadHubNews) to the currently selected sport tab -- "All
  // Sports" shows the full merged feed, a specific sport shows just that
  // league's real articles. No new fetch, no fabricated content: this is the
  // same data loadHubNews always pulled, just filtered client-side.
  function applyNewsSportFilter(){
    var section = document.getElementById('dr-hub-news');
    var heading = document.getElementById('dr-hub-news-heading');
    if (!section) return;
    newsArticles = activeSport === 'all' ? newsArticlesAll : newsArticlesAll.filter(function(a){ return a.league === activeSport; });
    newsVisibleCount = Math.min(10, newsArticles.length);
    if (heading) heading.textContent = activeSport === 'all' ? 'Around the Leagues' : 'Around ' + activeSport;
    if (!newsArticles.length) { section.style.display = 'none'; return; }
    renderNewsGrid();
    section.style.display = '';
  }

  function renderNewsGrid(){
    var grid = document.getElementById('dr-hub-news-grid');
    if (!grid) return;
    var visible = newsArticles.slice(0, newsVisibleCount);
    grid.innerHTML = visible.map(function(a, i){
      var img = a && a.images && a.images[0] && a.images[0].url;
      var when = timeAgo(a && a.published);
      return (
        '<button type="button" class="dr-hub-news-card dr-anim-in' + (i === 0 ? ' lead' : '') + '" style="animation-delay:' + (Math.min(i, 8) * 25) + 'ms" data-news-idx="' + i + '">' +
          (img ? '<img src="' + escapeHtml(img) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '') +
          '<div class="dr-hub-news-body">' +
            '<div class="dr-hub-news-headline">' + escapeHtml(a && a.headline) + '</div>' +
            '<div class="dr-hub-news-meta">ESPN' + (a.league ? ' · ' + a.league : '') + (when ? ' · ' + when : '') + '</div>' +
          '</div>' +
        '</button>'
      );
    }).join('');

    grid.querySelectorAll('.dr-hub-news-card').forEach(function(card){
      card.addEventListener('click', function(){
        var idx = Number(card.getAttribute('data-news-idx'));
        openNewsModal(visible[idx]);
      });
    });

    var moreBtn = document.getElementById('dr-hub-news-more');
    if (moreBtn) moreBtn.style.display = newsVisibleCount < newsArticles.length ? '' : 'none';
  }

  function openNewsModal(a){
    var modal = document.getElementById('dr-hub-news-modal');
    if (!modal || !a) return;
    var img = a.images && a.images[0] && a.images[0].url;
    var href = a.links && a.links.web && a.links.web.href;
    var when = timeAgo(a.published);

    var imgEl = document.getElementById('dr-hub-news-modal-img');
    if (img) { imgEl.src = img; imgEl.style.display = ''; imgEl.onerror = function(){ imgEl.style.display = 'none'; }; }
    else { imgEl.style.display = 'none'; }

    document.getElementById('dr-hub-news-modal-meta').textContent = 'ESPN' + (a.league ? ' · ' + a.league : '') + (when ? ' · ' + when : '');
    document.getElementById('dr-hub-news-modal-title').textContent = a.headline || '';
    var descEl = document.getElementById('dr-hub-news-modal-desc');
    if (a.description) { descEl.textContent = a.description; descEl.style.display = ''; }
    else { descEl.style.display = 'none'; }
    var linkEl = document.getElementById('dr-hub-news-modal-link');
    if (href) { linkEl.href = href; linkEl.style.display = ''; }
    else { linkEl.style.display = 'none'; }

    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
  }

  function closeNewsModal(){
    var modal = document.getElementById('dr-hub-news-modal');
    if (!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
  }

  function fetchLeagueNews(url, league){
    return fetch(url)
      .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function(data){
        var articles = (data && data.articles) || [];
        articles.forEach(function(a){ a.league = league; });
        return articles;
      })
      .catch(function(){ return []; });
  }

  function loadHubNews(){
    if (newsLoaded) return;
    newsLoaded = true;
    Promise.all([
      fetchLeagueNews('https://site.api.espn.com/apis/site/v2/sports/baseball/mlb/news?limit=50', 'MLB'),
      fetchLeagueNews('https://site.api.espn.com/apis/site/v2/sports/football/nfl/news?limit=30', 'NFL'),
      fetchLeagueNews('https://site.api.espn.com/apis/site/v2/sports/basketball/nba/news?limit=30', 'NBA'),
      fetchLeagueNews('https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/news?limit=30', 'WNBA')
    ]).then(function(results){
      var merged = results[0].concat(results[1]).concat(results[2]).concat(results[3]).sort(function(a, b){
        return new Date(b.published) - new Date(a.published);
      });
      renderHubNews(merged);
    });
  }

  function hs(id){
    return id ? 'https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_60,q_auto:best/v1/people/' + id + '/headshot/67/current' : '';
  }
  // Same real MLB headshot source as hs() above, just requested at a much
  // wider size (w_500) since this one gets stretched to the full card width
  // as a 16:9 banner photo instead of a small round avatar.
  function hsBig(id){
    return id ? 'https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_500,q_auto:best/v1/people/' + id + '/headshot/67/current' : '';
  }

  // Best-effort lookup of the actual home run clip via the game's content/
  // highlights feed, rather than just linking to the whole game's Gameday
  // page. This endpoint's exact shape can't be verified from this dev
  // environment (no external network access here), so every step is
  // defensive — if a game has no matching highlight, or the fetch/shape
  // doesn't match what's expected, findHRClipUrl just returns null and the
  // caller leaves the existing Gameday link in place. Never worse than
  // today, upgrades in place when it works.
  function fetchGameContent(gamePk){
    if (gameContentCache[gamePk]) return gameContentCache[gamePk];
    var p = fetch('https://diamondreport.app/api/v1/game/' + gamePk + '/content')
      .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function(data){
        return (data && data.highlights && data.highlights.highlights && data.highlights.highlights.items) || [];
      })
      .catch(function(){ return []; });
    gameContentCache[gamePk] = p;
    return p;
  }

  // Returns { videoUrl, webUrl } — videoUrl is a direct playable clip (used
  // to play the video in place, in-site), webUrl is the clip's mlb.com/video
  // page (used as a new-tab fallback when there's no direct playback url).
  // Either or both may be null if no highlight matched this player.
  function findHRClipUrl(items, playerName){
    if (!items || !items.length || !playerName) return { videoUrl: null, webUrl: null };
    var lastName = String(playerName).trim().split(/\s+/).pop().toLowerCase();
    if (!lastName) return { videoUrl: null, webUrl: null };
    for (var i = 0; i < items.length; i++) {
      var it = items[i] || {};
      var text = [it.title, it.headline, it.blurb, it.description].filter(Boolean).join(' ').toLowerCase();
      if (text.indexOf(lastName) === -1) continue;
      if (!/home run|homers|homered/.test(text)) continue;
      // Skip multi-player compilation reels ("Top 10 Home Runs of the
      // Week", "Plays of the Night", etc.) that happen to name-check this
      // player alongside others — those aren't the player's specific clip
      // and linking to one is worse than the Gameday-page fallback.
      if (/top\s*\d+|recap|best of|plays of the|highlights of the/.test(text)) continue;
      var webUrl = it.slug ? 'https://www.mlb.com/video/' + it.slug : null;
      var playback = (it.playbacks || []).find(function(pb){ return pb && pb.url; });
      return { videoUrl: playback ? playback.url : null, webUrl: webUrl };
    }
    return { videoUrl: null, webUrl: null };
  }

  // The live play-by-play feed (feed/live) is the standard, well-established
  // MLB Stats API endpoint for pitch-level detail — same family as the
  // boxscore endpoint already used throughout this file, unlike the
  // less-certain content/highlights feed above.
  function fetchGameFeed(gamePk){
    if (gameFeedCache[gamePk]) return gameFeedCache[gamePk];
    var p = fetch('https://diamondreport.app/api/v1.1/game/' + gamePk + '/feed/live')
      .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function(data){
        return (data && data.liveData && data.liveData.plays && data.liveData.plays.allPlays) || [];
      })
      .catch(function(){ return []; });
    gameFeedCache[gamePk] = p;
    return p;
  }

  // Finds the pitch that was put in play for a given batter's home run.
  // Matches by batter id (more reliable than name matching) — if a batter
  // has multiple HRs in the same game, this returns the first one found,
  // a known simplification since loadHRsToday's data is one aggregated
  // entry per batter per game, not one per individual home run.
  function findHRPitchInfo(allPlays, batterId){
    if (!allPlays || !allPlays.length || !batterId) return null;
    for (var i = 0; i < allPlays.length; i++) {
      var play = allPlays[i] || {};
      if (!play.result || play.result.event !== 'Home Run') continue;
      if (!play.matchup || !play.matchup.batter || play.matchup.batter.id !== batterId) continue;
      var events = play.playEvents || [];
      var pitch = null;
      for (var j = events.length - 1; j >= 0; j--) {
        if (events[j] && events[j].isPitch) { pitch = events[j]; break; }
      }
      if (!pitch) return null;
      var pitchType = pitch.details && pitch.details.type && pitch.details.type.description;
      var velocity = pitch.pitchData && pitch.pitchData.startSpeed;
      var pitcherName = play.matchup.pitcher && play.matchup.pitcher.fullName;
      if (!pitchType && !velocity) return null;
      return { pitchType: pitchType || null, velocity: velocity ? Math.round(velocity) : null, pitcherName: pitcherName || null };
    }
    return null;
  }

  function openHRVideoModal(title, meta, videoUrl){
    var modal = document.getElementById('dr-hub-hr-modal');
    var video = document.getElementById('dr-hub-hr-modal-video');
    if (!modal || !video) return;
    document.getElementById('dr-hub-hr-modal-title').textContent = title || '';
    document.getElementById('dr-hub-hr-modal-meta').textContent = meta || '';
    video.src = videoUrl;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
    video.play().catch(function(){});
  }

  function closeHRVideoModal(){
    var modal = document.getElementById('dr-hub-hr-modal');
    var video = document.getElementById('dr-hub-hr-modal-video');
    if (!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
    if (video) { video.pause(); video.removeAttribute('src'); video.load(); }
  }
  // Exposed on window so other, differently-scoped parts of this file (this
  // whole file is a concatenation of many once-separate <script> tags, each
  // its own closure -- see the "from <script id=...>" markers throughout)
  // can reuse this exact same in-site video player instead of each building
  // their own modal. First reused by the Near HRs board's Watch links (see
  // nearHRTableRowHTML/nearHRCardHTML), which used to link out to Baseball
  // Savant's own page in a new tab.
  window.openHRVideoModal = openHRVideoModal;
  window.closeHRVideoModal = closeHRVideoModal;

  function renderHubHRs(list, dayLabel){
    var container = document.getElementById('dr-hub-hr-list');
    if (!container || !list || !list.length) return;
    dayLabel = dayLabel || 'today';
    // Most recent first — allHRs is sorted oldest-game-first for the Props pane.
    var recent = list.slice().reverse().slice(0, 6);
    container.innerHTML = recent.map(function(h, i){
      var fallback = h.gamePk ? 'https://www.mlb.com/gameday/' + h.gamePk : 'https://www.mlb.com/video';
      var title = escapeHtml(h.name) + ' — ' + h.hrs + ' HR' + (h.hrs !== 1 ? 's' : '') + ' ' + dayLabel;
      var sub = escapeHtml(h.teamAbbr || '') + (h.gameLabel ? ' · ' + escapeHtml(h.gameLabel) : '') + (h.timeStr ? ' · ' + escapeHtml(h.timeStr) : '');
      return (
        '<button type="button" class="dr-hub-hr-card" data-hr-idx="' + i + '" data-fallback="' + escapeHtml(fallback) + '">' +
          (h.id ? '<img class="dr-hub-hr-photo" src="' + escapeHtml(hs(h.id)) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '<span class="dr-hub-hr-play">▶</span>') +
          '<span class="dr-hub-hr-text">' +
            '<span class="dr-hub-hr-title">' + title + '</span>' +
            '<span class="dr-hub-hr-sub">' + sub + '</span>' +
          '</span>' +
        '</button>'
      );
    }).join('');

    container.querySelectorAll('.dr-hub-hr-card').forEach(function(card){
      card.addEventListener('click', function(){
        var videoUrl = card.dataset.videoUrl;
        var webUrl = card.dataset.webUrl;
        if (videoUrl) {
          var titleEl = card.querySelector('.dr-hub-hr-title');
          var subEl = card.querySelector('.dr-hub-hr-sub');
          openHRVideoModal(titleEl ? titleEl.textContent : '', subEl ? subEl.textContent : '', videoUrl);
        } else {
          window.open(webUrl || card.dataset.fallback, '_blank', 'noopener,noreferrer');
        }
      });
    });

    // Progressive enhancement — once/if a matching highlight is found for a
    // player, stash its direct video url (plays in-site) and/or web page
    // url (new-tab fallback) on the card as data attributes, read by the
    // click handler above. Until/unless that resolves, clicking just opens
    // the Gameday page fallback already wired in — never worse than before.
    recent.forEach(function(h, i){
      if (!h.gamePk) return;
      fetchGameContent(h.gamePk).then(function(items){
        var found = findHRClipUrl(items, h.name);
        var card = container.querySelector('[data-hr-idx="' + i + '"]');
        if (!card) return;
        if (found.videoUrl) card.dataset.videoUrl = found.videoUrl;
        if (found.webUrl) card.dataset.webUrl = found.webUrl;
      });
    });

    // Second, independent progressive enhancement — append the actual pitch
    // (velocity + type, e.g. "95 mph Slider") to the card's subtitle once
    // found. The video modal reads this same subtitle text at click time,
    // so it picks up the enrichment automatically without any extra wiring.
    recent.forEach(function(h, i){
      if (!h.gamePk || !h.id) return;
      fetchGameFeed(h.gamePk).then(function(allPlays){
        var pitch = findHRPitchInfo(allPlays, h.id);
        if (!pitch || (!pitch.pitchType && !pitch.velocity)) return;
        var card = container.querySelector('[data-hr-idx="' + i + '"]');
        var subEl = card && card.querySelector('.dr-hub-hr-sub');
        if (!subEl) return;
        var pitchLabel = [pitch.velocity ? pitch.velocity + ' mph' : null, pitch.pitchType].filter(Boolean).join(' ');
        if (pitchLabel) subEl.textContent += ' · ' + pitchLabel;
      });
    });
  }

  // Curated set of hitting/pitching categories for the League Leaders widget —
  // enough to give a real snapshot of "who's having the best season" without
  // turning a News Central side section into a full stats page. Category keys
  // match MLB Stats API's leaderCategories values exactly.
  var LEADER_HITTING_CATS = ['homeRuns', 'battingAverage', 'onBasePlusSlugging', 'runsBattedIn'];
  // ERA, Wins, and WHIP were dropped from the widget per request — Strikeouts is the
  // only pitching category shown now.
  var LEADER_PITCHING_CATS = ['strikeouts'];
  var LEADER_CATEGORY_LABELS = {
    homeRuns: 'Home Runs', battingAverage: 'Batting Avg', onBasePlusSlugging: 'OPS', runsBattedIn: 'RBI',
    strikeouts: 'Strikeouts'
  };
  function leaderCategoryLabel(cat){ return LEADER_CATEGORY_LABELS[cat] || cat; }

  // Batting average/OPS display as ".312"-style (no leading zero); everything else
  // (HR/RBI/strikeouts) as a plain whole-number count — matches how each stat is
  // conventionally shown.
  function formatLeaderValue(cat, value){
    var num = parseFloat(value);
    if (!Number.isFinite(num)) return String(value == null ? '–' : value);
    if (cat === 'battingAverage' || cat === 'onBasePlusSlugging') return num.toFixed(3).replace(/^0\./, '.');
    return String(Math.round(num));
  }

  var LEADER_ROWS_PER_CATEGORY = 3;
  var leaderEntries = [];
  var teamIdToAbbr = null;

  // /stats/leaders' team object only reliably carries an id, not an
  // abbreviation (confirmed against a live response — every leader came back
  // with team.abbreviation undefined). Resolve it from the existing
  // abbr->id map (window.teamIds, built at the top of app.js) instead.
  function teamAbbrFromId(id){
    if (!teamIdToAbbr) {
      teamIdToAbbr = {};
      var ids = window.teamIds || {};
      for (var abbr in ids) { teamIdToAbbr[ids[abbr]] = abbr; }
    }
    return teamIdToAbbr[id] || '';
  }

  function renderHubLeaders(categories){
    var container = document.getElementById('dr-hub-leaders-list');
    var section = document.getElementById('dr-hub-leaders');
    if (!container || !categories || !categories.length) return;
    leaderEntries = [];

    var groups = categories.map(function(c){
      var leaders = (c && c.leaders || []).slice(0, LEADER_ROWS_PER_CATEGORY);
      if (!leaders.length) return '';
      var rows = leaders.map(function(leader){
        var person = leader.person || {};
        var team = leader.team || {};
        var teamAbbr = team.abbreviation || teamAbbrFromId(team.id) || '';
        var value = formatLeaderValue(c.leaderCategory, leader.value);
        var idx = leaderEntries.push({
          category: c.leaderCategory,
          rank: leader.rank,
          value: value,
          name: person.fullName || '–',
          teamAbbr: teamAbbr,
          personId: person.id || null,
        }) - 1;
        return (
          '<button type="button" class="dr-hub-leader-row" data-leader-idx="' + idx + '">' +
            '<span class="dr-hub-leader-row-rank">#' + escapeHtml(String(leader.rank || '')) + '</span>' +
            (person.id ? '<img class="dr-hub-leader-row-photo" src="' + escapeHtml(hs(person.id)) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '') +
            '<span class="dr-hub-leader-row-name">' + escapeHtml(person.fullName || '–') + '</span>' +
            '<span class="dr-hub-leader-row-team">' + escapeHtml(teamAbbr) + '</span>' +
            '<span class="dr-hub-leader-row-value">' + escapeHtml(value) + '</span>' +
          '</button>'
        );
      }).join('');
      return (
        '<div class="dr-hub-leader-group">' +
          '<h4 class="dr-hub-leader-group-title">' + escapeHtml(leaderCategoryLabel(c.leaderCategory)) + '</h4>' +
          rows +
        '</div>'
      );
    }).filter(Boolean);
    if (!groups.length) return;
    container.innerHTML = groups.join('');
    container.querySelectorAll('.dr-hub-leader-row').forEach(function(row){
      row.addEventListener('click', function(){
        var idx = Number(row.getAttribute('data-leader-idx'));
        openLeaderModal(leaderEntries[idx]);
      });
    });
    if (section) section.style.display = '';
    showSideToggleIfNeeded();
  }

  // Below the side-rail breakpoint, League Leaders/Season Projections are collapsed
  // behind a toggle by default (too much extra scrolling on a phone to show
  // both expanded). Only reveal the toggle once there's actually something
  // behind it — no point showing "Show League Leaders" if both fetches failed.
  function showSideToggleIfNeeded(){
    var toggle = document.getElementById('dr-hub-side-toggle');
    if (!toggle || toggle.dataset.drHubShown) return;
    var leaders = document.getElementById('dr-hub-leaders');
    var projections = document.getElementById('dr-hub-projections');
    var hasContent = (leaders && leaders.style.display !== 'none') || (projections && projections.style.display !== 'none');
    if (!hasContent) return;
    toggle.dataset.drHubShown = '1';
    toggle.style.display = 'flex';
  }

  function toggleSideContent(){
    var toggle = document.getElementById('dr-hub-side-toggle');
    var content = document.getElementById('dr-hub-side-content');
    var label = toggle && toggle.querySelector('.dr-hub-side-toggle-label');
    if (!toggle || !content) return;
    var expanded = content.classList.toggle('expanded');
    toggle.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    if (label) label.textContent = expanded ? 'Hide Season Projections & League Leaders' : 'Show Season Projections & League Leaders';
  }

  function openLeaderModal(entry){
    var modal = document.getElementById('dr-hub-leader-modal');
    if (!modal || !entry) return;
    var photoEl = document.getElementById('dr-hub-leader-modal-photo');
    if (entry.personId) { photoEl.src = hs(entry.personId); photoEl.style.display = ''; photoEl.onerror = function(){ photoEl.style.display = 'none'; }; }
    else { photoEl.style.display = 'none'; }
    document.getElementById('dr-hub-leader-modal-meta').textContent = entry.teamAbbr ? entry.teamAbbr + ' · ' + new Date().getFullYear() + ' Season' : String(new Date().getFullYear()) + ' Season';
    document.getElementById('dr-hub-leader-modal-title').textContent = entry.name || '';
    document.getElementById('dr-hub-leader-modal-value').textContent = entry.value || '';
    document.getElementById('dr-hub-leader-modal-cat').textContent = leaderCategoryLabel(entry.category);
    document.getElementById('dr-hub-leader-modal-rank').textContent = entry.rank ? ('Ranked #' + entry.rank + ' in MLB') : '';
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
  }

  function closeLeaderModal(){
    var modal = document.getElementById('dr-hub-leader-modal');
    if (!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
  }

  function loadHubLeaders(){
    if (leadersLoaded) return;
    leadersLoaded = true;
    var season = new Date().getFullYear();
    Promise.all([
      fetchJSON('https://diamondreport.app/api/v1/stats/leaders?leaderCategories=' + LEADER_HITTING_CATS.join(',') + '&season=' + season + '&sportId=1&statGroup=hitting&limit=' + LEADER_ROWS_PER_CATEGORY).catch(function(){ return null; }),
      fetchJSON('https://diamondreport.app/api/v1/stats/leaders?leaderCategories=' + LEADER_PITCHING_CATS.join(',') + '&season=' + season + '&sportId=1&statGroup=pitching&limit=' + LEADER_ROWS_PER_CATEGORY).catch(function(){ return null; })
    ]).then(function(results){
      var all = [];
      results.forEach(function(d){
        if (d && Array.isArray(d.leagueLeaders)) all = all.concat(d.leagueLeaders);
      });
      if (all.length) renderHubLeaders(all);
    }).catch(function(){});
  }

  // World Series / MVP projections — from data/season-projections.json, a repo-synced daily
  // file (Monte Carlo playoff bracket sim + a composite-score MVP model; see
  // scripts/generate-season-projections.mjs for methodology), same fetch pattern as
  // the Statcast files (drFetchDailyJSON, not a live per-request MLB API call).
  function wsTeamLogo(teamId){
    return teamId ? '<img class="dr-hub-projections-row-photo" src="https://www.mlbstatic.com/team-logos/' + teamId + '.svg" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '';
  }

  function projectionsRowHtml(photoHtml, name, team, pct){
    var width = Math.max(0, Math.min(100, pct));
    return (
      '<div class="dr-hub-projections-row">' +
        photoHtml +
        '<span class="dr-hub-projections-row-name">' + escapeHtml(name) + '</span>' +
        '<span class="dr-hub-projections-row-team">' + escapeHtml(team || '') + '</span>' +
        '<span class="dr-hub-projections-row-bar"><span class="dr-hub-projections-row-bar-fill" style="width:' + width + '%"></span></span>' +
        '<span class="dr-hub-projections-row-pct">' + pct.toFixed(1) + '%</span>' +
      '</div>'
    );
  }

  function renderHubProjections(data){
    var section = document.getElementById('dr-hub-projections');
    var wsEl = document.getElementById('dr-hub-ws-projections');
    var mvpAlEl = document.getElementById('dr-hub-mvp-al-projections');
    var mvpNlEl = document.getElementById('dr-hub-mvp-nl-projections');
    if (!section || !data) return;

    var ws = Array.isArray(data.worldSeries) ? data.worldSeries.slice(0, 8) : [];
    var mvpAl = (data.mvp && Array.isArray(data.mvp.AL)) ? data.mvp.AL.slice(0, 3) : [];
    var mvpNl = (data.mvp && Array.isArray(data.mvp.NL)) ? data.mvp.NL.slice(0, 3) : [];
    if (!ws.length && !mvpAl.length && !mvpNl.length) return;

    if (wsEl) wsEl.innerHTML = ws.map(function(t){
      return projectionsRowHtml(wsTeamLogo(t.teamId), t.name || t.abbr || '–', t.abbr, t.pct);
    }).join('');
    if (mvpAlEl) mvpAlEl.innerHTML = mvpAl.map(function(c){
      return projectionsRowHtml(c.id ? '<img class="dr-hub-projections-row-photo" src="' + escapeHtml(hs(c.id)) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '', c.name || '–', c.teamAbbr, c.pct);
    }).join('');
    if (mvpNlEl) mvpNlEl.innerHTML = mvpNl.map(function(c){
      return projectionsRowHtml(c.id ? '<img class="dr-hub-projections-row-photo" src="' + escapeHtml(hs(c.id)) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' : '', c.name || '–', c.teamAbbr, c.pct);
    }).join('');
    section.style.display = '';
    showSideToggleIfNeeded();
  }

  function loadHubProjections(){
    if (projectionsLoaded) return;
    projectionsLoaded = true;
    drFetchDailyJSON('data/season-projections.json').then(function(data){
      renderHubProjections(data);
    }).catch(function(){});
  }

  // Diamond Report Headlines (roadmap 3.2) -- proprietary, data-driven editorial
  // headlines from data/daily-headlines.json; see scripts/generate-headlines.mjs for
  // how each of the 6 categories (recap, trend, notable performance, weather, injury,
  // model movement, leaderboard) is generated -- real numbers this site's own sync
  // pipeline already computed, narrated, never spun filler text. Same
  // drFetchDailyJSON pattern as season-projections.json above. Titles/blurbs render
  // via textContent, not innerHTML, even though the script only ever writes text it
  // built itself from real stats -- no reason to trust that path any more than user
  // input. Each card's "View related report" link and clip button are wired with
  // addEventListener (not inline onclick) since the click targets (applyHeadlineLink,
  // openHRVideoModal) need the real headline object, not just a string embeddable in
  // an HTML attribute.
  // ── Featured Player (roadmap 2) ──────────────────────────────────────────
  // Fetches data/featured-player.json, generated server-side by
  // scripts/generate-headlines.mjs's buildFeaturedPlayer from the exact same
  // real HR-probability model/batter pool the HR Threats board uses (see that
  // function's own header comment for the full lock-in/degrade discipline).
  // Never fabricates a pick client-side -- if the file is missing or empty
  // today, the section just stays hidden (same convention as every other Hub
  // section here).
  var featuredPlayerLoaded = false;
  function loadFeaturedPlayer(){
    if (featuredPlayerLoaded) return;
    featuredPlayerLoaded = true;
    drFetchDailyJSON('data/featured-player.json').then(function(data){
      renderFeaturedPlayer(data);
    }).catch(function(){});
  }

  function featuredPlayerTrendChipHTML(p){
    if (typeof window.computePlayerTrendIndicator !== 'function') return '';
    var t = window.computePlayerTrendIndicator({ last10HR: p.last10HR, atBats: p.atBats, hrSeason: p.hrSeason });
    if (!t) return '';
    var icon = t.label === 'Hot Streak' ? '🔥' : t.label === 'Cold' ? '🧊' : t.label === 'Trending Up' ? '📈' : '📉';
    return '<span class="dr-featured-player-trend dr-featured-player-trend-'+(t.tone||'neutral')+'">'+icon+' '+escapeHtml(t.label)+(t.smallSample?' · small sample':'')+'</span>';
  }

  function renderFeaturedPlayer(data){
    var section = document.getElementById('dr-hub-featured');
    var content = document.getElementById('dr-hub-featured-content');
    if (!section || !content) return;
    var p = data && data.player;
    if (!p) { section.style.display = 'none'; return; }

    var matchupHTML = p.confirmedToday
      ? escapeHtml(p.teamAbbr||'') + ' vs ' + escapeHtml(p.oppAbbr||'') + (p.pitcherName ? ' · ' + escapeHtml(p.pitcherName) : '')
      : '<span class="dr-featured-player-scratched">Not currently confirmed in today\'s lineup — real season numbers below still reflect this pick.</span>';

    var statChips = [
      ['AVG', p.avg!=null ? p.avg.toFixed(3).replace(/^0/,'') : '–'],
      ['OBP', p.obp!=null ? p.obp.toFixed(3).replace(/^0/,'') : '–'],
      ['SLG', p.slg!=null ? p.slg.toFixed(3).replace(/^0/,'') : '–'],
      ['OPS', p.ops!=null ? p.ops.toFixed(3).replace(/^0/,'') : '–'],
      ['Season HR', p.hrSeason!=null ? p.hrSeason : '–'],
      ['Last 10 HR', p.last10HR!=null ? p.last10HR : '–'],
    ].map(function(c){ return '<span class="dr-featured-player-stat"><b>'+escapeHtml(c[1])+'</b><small>'+escapeHtml(c[0])+'</small></span>'; }).join('');

    // Was two views of the exact same 3 facts stacked on top of each other --
    // rounded-pill "reason chips" (each truncated at the first literal '.',
    // which silently chopped any reason containing a decimal number, e.g.
    // "Projects at a real 37.0% HR probability..." rendering as just
    // "Projects at a real 37") immediately followed by an "AI Explanation"
    // paragraph restating the identical text in full. Consolidated into one
    // real list, reusing the exact driver-row treatment already shipped for
    // the Matchup modal's Why Today tab (pr-drivers-panel/pr-driver-row) so
    // this reads as the same real synthesis pattern instead of a different
    // one-off component, and dropped the truncation entirely -- these are
    // already short, single-sentence reasons, nothing here needs chopping.
    var reasons = Array.isArray(p.reasons) ? p.reasons : [];
    var whyHTML = reasons.length
      ? '<div class="pr-drivers-panel" style="margin-top:12px">'
        + '<div class="pr-drivers-summary">🤖 <b>Why the model likes this</b></div>'
        + reasons.slice(0,3).map(function(r){ return '<div class="pr-driver-row"><span class="pr-driver-icon">'+escapeHtml(r.icon||'')+'</span><span class="pr-driver-text">'+escapeHtml(r.text||'')+'</span></div>'; }).join('')
        + '</div>'
      : '';

    var updated = data.generatedAt ? new Date(data.generatedAt).toLocaleString('en-US', { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' }) : '';
    var clickable = p.confirmedToday && p.pitcherId;
    var bName = String(p.name||'').replace(/'/g,"\\'");
    var pName = String(p.pitcherName||'').replace(/'/g,"\\'");

    content.innerHTML =
      '<div class="dr-featured-player-card'+(clickable?' clickable':'')+'"'+(clickable?' onclick="openMatchup('+p.id+',\''+bName+'\','+p.pitcherId+',\''+pName+'\')" role="button" tabindex="0"':'')+'>'+
        '<div class="dr-featured-player-head">'+
          '<img class="dr-featured-player-photo" loading="lazy" decoding="async" src="'+hsBig(p.id)+'" onerror="this.style.display=\'none\'" alt="">'+
          '<div class="dr-featured-player-headtext">'+
            '<div class="dr-featured-player-badge">⭐ TODAY\'S FEATURED PLAYER</div>'+
            '<div class="dr-featured-player-name">'+escapeHtml(p.name||'')+'</div>'+
            '<div class="dr-featured-player-meta">'+matchupHTML+'</div>'+
          '</div>'+
        '</div>'+
        '<div class="dr-featured-player-body">'+
          '<div class="dr-featured-player-score-row">'+
            '<div class="dr-featured-player-score"><strong>'+(p.liveScore!=null?p.liveScore.toFixed(1):'–')+'%</strong><span>HR Probability</span></div>'+
            featuredPlayerTrendChipHTML(p)+
          '</div>'+
          '<div class="dr-featured-player-stats">'+statChips+'</div>'+
          whyHTML+
          (clickable ? '<div class="dr-featured-player-cta">Tap for the full Matchup analysis ›</div>' : '')+
          '<div class="dr-featured-player-footer">Selected from the real HR-probability model + hot streak/matchup/near-HR signals · Updated '+escapeHtml(updated)+'</div>'+
        '</div>'+
      '</div>';
    section.style.display = '';
  }

  var CATEGORY_LABELS = { recap: 'RECAP', trend: 'TREND', streak: 'STREAK', notable: 'NOTABLE PERFORMANCE', weather: 'WEATHER', injury: 'INJURY', model: 'MODEL MOVE', leaderboard: 'LEADERBOARD', transaction: 'TRANSACTION', nohitter: 'NO-HITTER', milestone: 'MILESTONE' };
  // Purely decorative -- a quick-scan visual cue per category, same real
  // categories CATEGORY_LABELS already names. A missing icon just renders no
  // emoji rather than a placeholder.
  var CATEGORY_ICONS = { recap: '📋', trend: '📈', streak: '🔥', notable: '💥', weather: '🌤️', injury: '🩹', model: '⚙️', leaderboard: '🏆', transaction: '🔄', nohitter: '🚫', milestone: '🎉' };
  var headlinesLoaded = false;
  function loadHubHeadlines(){
    if (headlinesLoaded) return;
    headlinesLoaded = true;
    drFetchDailyJSON('data/daily-headlines.json').then(function(data){
      renderHubHeadlines(data);
    }).catch(function(){});
  }

  // Navigates to a headline's related board via the site's existing hash-routing
  // (#gamepick=...), then -- only for headlines about a specific player, and only
  // for the HR Threats board, the one board type this reuses -- stuffs the player's
  // name into that board's own existing per-board search box (window.setPropSearchFilter,
  // the same global the search input's oninput handler itself calls) so the click
  // actually surfaces the player the headline was about, rather than just landing on
  // an unfiltered board. The short delay lets the hashchange listener finish
  // switching panes before the board searched is guaranteed to exist/be visible.
  function applyHeadlineLink(link){
    if (!link || !link.hash) return;
    window.location.hash = link.hash.replace(/^#/, '');
    if (link.playerName && link.hash === '#gamepick=hr') {
      setTimeout(function(){
        if (typeof window.setPropSearchFilter === 'function') window.setPropSearchFilter('hr', link.playerName);
      }, 60);
    }
  }

  // Daily Briefing -- "understand today in under 60 seconds." Deliberately
  // makes its own independent fetches of data the hub already loads elsewhere
  // (featured-player.json, daily-headlines.json, trending-players.json)
  // instead of reaching into loadFeaturedPlayer/loadHubHeadlines/
  // loadTrendingPlayers' internal state, so this has no load-order dependency
  // on those other sections and can't be broken by future changes to them.
  // Every item here is real synced data -- nothing is fabricated, and an
  // item is simply omitted (not shown empty/fake) when its data isn't
  // available today.
  var briefingLoaded = false;
  var briefingItems = [];
  function loadDailyBriefing(){
    if (briefingLoaded) return;
    briefingLoaded = true;
    Promise.all([
      drFetchDailyJSON('data/featured-player.json').catch(function(){ return null; }),
      drFetchDailyJSON('data/daily-headlines.json').catch(function(){ return null; }),
      drFetchDailyJSON('data/trending-players.json').catch(function(){ return null; })
    ]).then(function(results){
      renderDailyBriefing(results[0], results[1], results[2]);
    });
  }

  function briefingItemHTML(it, i){
    return '<button type="button" class="dr-hub-briefing-item" onclick="(window.__drBriefingClick||function(){})(' + i + ')">' +
      '<span class="dr-hub-briefing-item-label">' + escapeHtml(it.icon || '') + ' ' + escapeHtml(it.label || '') + '</span>' +
      '<span class="dr-hub-briefing-item-title">' + escapeHtml(it.title || '') + '</span>' +
      (it.sub ? '<span class="dr-hub-briefing-item-sub">' + escapeHtml(it.sub) + '</span>' : '') +
    '</button>';
  }

  function renderDailyBriefing(featuredData, headlinesData, trendingData){
    var section = document.getElementById('dr-hub-briefing');
    var grid = document.getElementById('dr-hub-briefing-grid');
    var expandBtn = document.getElementById('dr-hub-briefing-expand');
    var full = document.getElementById('dr-hub-briefing-full');
    if (!section || !grid) return;

    var p = featuredData && featuredData.player;
    var headlines = (headlinesData && Array.isArray(headlinesData.headlines)) ? headlinesData.headlines : [];
    var trendingList = Array.isArray(trendingData && trendingData.players) ? trendingData.players
      : (Array.isArray(trendingData) ? trendingData : []);

    var recap = headlines.filter(function(h){ return h.category === 'recap'; })[0];
    // Top Story and Signal to Know both used to independently take "the first
    // non-recap headline in the array" / "the first injury|weather|notable
    // headline in the array" -- since generate-headlines.mjs always pushes
    // notable right after recap, whenever a notable headline existed both
    // slots silently picked the exact same story, wasting a whole briefing
    // tile on a literal repeat (confirmed live: "Top Story" and "Notable
    // Performance" showing the identical "Longest home run of the day" line).
    // Fixed by ranking the real one-off categories by a fixed newsworthiness
    // order -- transaction/model movement are genuine same-day news that can
    // change a roster or a pick, weather/injury are real but more contextual,
    // notable/leaderboard are retrospective facts -- and having Top Story and
    // Signal draw from different ranks of that same ordered list, so they can
    // never collide on one story.
    var ONE_OFF_PRIORITY = ['nohitter', 'milestone', 'transaction', 'model', 'injury', 'weather', 'notable', 'leaderboard'];
    var oneOffs = headlines.filter(function(h){ return h.category !== 'recap' && h.category !== 'trend' && h.category !== 'streak'; });
    oneOffs.sort(function(a, b){
      var ai = ONE_OFF_PRIORITY.indexOf(a.category); if (ai === -1) ai = ONE_OFF_PRIORITY.length;
      var bi = ONE_OFF_PRIORITY.indexOf(b.category); if (bi === -1) bi = ONE_OFF_PRIORITY.length;
      return ai - bi;
    });
    var topStory = oneOffs[0] || headlines.filter(function(h){ return h.category !== 'recap'; })[0];
    var signal = oneOffs[1];
    var topTrend = trendingList[0];

    briefingItems = [];

    if (topStory) {
      briefingItems.push({
        label: 'Top Story', icon: CATEGORY_ICONS[topStory.category] || '📰',
        title: topStory.title, sub: topStory.blurb,
        run: function(){ openHeadlineModal(topStory); }
      });
    }
    if (p) {
      briefingItems.push({
        label: 'Best Game to Watch', icon: '⚾',
        title: (p.teamAbbr || '') + ' vs ' + (p.oppAbbr || ''),
        sub: (p.name || 'Today’s featured matchup') + (p.pitcherName ? ' vs ' + p.pitcherName : ''),
        run: function(){ applyHeadlineLink({ hash: '#gamepick=game' }); }
      });
      briefingItems.push({
        label: 'Highest-Confidence Pick', icon: '🎯',
        title: (p.name || '') + ' — ' + (p.liveScore != null ? p.liveScore.toFixed(1) : '–') + '% HR probability',
        sub: 'Matchup Edge ' + (p.matchupEdge != null ? p.matchupEdge : '–') + (p.pitcherName ? ' vs ' + p.pitcherName : ''),
        run: function(){ applyHeadlineLink({ hash: '#gamepick=hr', playerName: p.name }); }
      });
    }
    if (signal) {
      briefingItems.push({
        label: CATEGORY_LABELS[signal.category] || 'Signal to Know', icon: CATEGORY_ICONS[signal.category] || '🩹',
        title: signal.title, sub: signal.blurb,
        run: function(){ openHeadlineModal(signal); }
      });
    }
    if (topTrend) {
      briefingItems.push({
        label: 'Trending Up', icon: '📈',
        title: (topTrend.name || '') + ' — ' + (topTrend.trendLabel || ''),
        sub: topTrend.trendMetric || '',
        run: function(){
          if (topTrend.type === 'pitcher') { window.location.hash = 'gamepick=k'; return; }
          window.location.hash = 'gamepick=hr';
          if (topTrend.playerId) setTimeout(function(){
            if (typeof window.setPropSearchFilter === 'function') window.setPropSearchFilter('hr', topTrend.name);
          }, 60);
        }
      });
    }
    if (recap) {
      briefingItems.push({
        label: 'Yesterday’s Model Record', icon: '📋',
        title: recap.title, sub: recap.blurb,
        run: function(){ window.location.href = '/track-record.html'; }
      });
    }

    if (!briefingItems.length) { section.style.display = 'none'; return; }

    window.__drBriefingClick = function(i){ var it = briefingItems[i]; if (it && it.run) it.run(); };
    grid.innerHTML = briefingItems.map(briefingItemHTML).join('');

    // "Give me the full briefing" -- everything above, just with the full
    // (unclipped) text for each item instead of a scannable summary line.
    // No new data: same briefingItems, rendered without truncation.
    if (expandBtn && full) {
      expandBtn.style.display = '';
      expandBtn.onclick = function(){
        var open = full.style.display !== 'none';
        full.style.display = open ? 'none' : '';
        expandBtn.setAttribute('aria-expanded', open ? 'false' : 'true');
        document.getElementById('dr-hub-briefing-expand-label').textContent = open ? 'Give me the full briefing' : 'Show less';
        expandBtn.querySelector('.dr-hub-briefing-expand-icon').textContent = open ? '▾' : '▴';
        if (!open) {
          full.innerHTML = briefingItems.map(function(it){
            return '<div class="dr-hub-briefing-full-item"><b>' + escapeHtml(it.label) + '</b><p>' + escapeHtml((it.title || '') + (it.sub ? ' — ' + it.sub : '')) + '</p></div>';
          }).join('');
        }
      };
    }

    section.style.display = '';
  }

  // Your Watchlist -- reads the same localStorage watchlist every board's
  // inline star already writes to (drGetWatchlist/drToggleWatchlist, defined
  // top-level above). Hidden entirely when empty, matching the "hide rather
  // than show empty" convention Trending Players already uses. Re-renders
  // live on the existing dr-watchlist-change event so starring/unstarring a
  // player anywhere on the site updates this section without a reload.
  function renderWatchlistSection(){
    var section = document.getElementById('dr-hub-watchlist');
    var grid = document.getElementById('dr-hub-watchlist-grid');
    if (!section || !grid || typeof drGetWatchlist !== 'function') return;
    var wl = drGetWatchlist();
    var ids = Object.keys(wl);
    if (!ids.length) { section.style.display = 'none'; return; }
    ids.sort(function(a, b){ return (wl[b].addedAt || 0) - (wl[a].addedAt || 0); });
    grid.innerHTML = ids.map(function(id){
      var entry = wl[id] || {};
      var name = entry.name || 'Player';
      var safeName = name.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
      return '<div class="dr-hub-watchlist-card">' +
        '<img class="dr-hub-watchlist-photo" loading="lazy" decoding="async" src="' + hs(id) + '" onerror="this.style.display=\'none\'" alt="">' +
        '<button type="button" class="dr-hub-watchlist-name" onclick="window.location.hash=\'gamepick=hr\';setTimeout(function(){if(typeof window.setPropSearchFilter===\'function\')window.setPropSearchFilter(\'hr\',\'' + safeName + '\')},60)">' + escapeHtml(name) + '</button>' +
        '<button type="button" class="dr-hub-watchlist-remove" onclick="window.drToggleWatchlist(\'' + id + '\',\'' + safeName + '\')" aria-label="Remove from watchlist" title="Remove from watchlist">★</button>' +
      '</div>';
    }).join('');
    section.style.display = '';
  }
  document.addEventListener('dr-watchlist-change', renderWatchlistSection);

  function fmtRate3(v){ return v != null && Number.isFinite(v) ? v.toFixed(3).replace(/^0/, '') : '—'; }
  // countTo (optional): a real integer to count up to on first paint via the
  // existing animateCountUp helper (already used elsewhere for one-shot-per-open
  // content like this modal) -- renders "0" first, then the real number gets
  // wired up to a data attribute the caller animates after inserting into the
  // DOM. Plain text values (rate stats, "—") skip this and render immediately.
  function statPillHTML(value, label, countTo){
    var valueHTML = Number.isFinite(countTo) ? '<b data-count-to="' + countTo + '">0</b>' : '<b>' + escapeHtml(value) + '</b>';
    return '<span class="dr-featured-player-stat">' + valueHTML + '<small>' + escapeHtml(label) + '</small></span>';
  }

  // Real, honestly-aggregated last-10-real-games rate stats -- sums the counting
  // stats (AB/H/HR/BB/HBP/SF/TB) across the most recent N games from the same
  // stats=lastXGames log fetchBatterSeasonBundle already pulls, then derives
  // AVG/OBP/SLG/OPS from those sums. Deliberately NOT an average of each game's
  // own rate stat (which would over-weight a 1-AB game as much as a 5-AB game) --
  // this is the same real aggregation any box score stretch uses.
  function aggregateLastNGames(logs, n){
    var recent = (logs || []).slice().sort(function(a, b){ return (b.date || '').localeCompare(a.date || ''); }).slice(0, n);
    if (!recent.length) return null;
    var ab = 0, h = 0, hr = 0, bb = 0, hbp = 0, sf = 0, tb = 0;
    recent.forEach(function(g){
      var s = g.stat || {};
      ab += parseInt(s.atBats) || 0;
      h += parseInt(s.hits) || 0;
      hr += parseInt(s.homeRuns) || 0;
      bb += parseInt(s.baseOnBalls) || 0;
      hbp += parseInt(s.hitByPitch) || 0;
      sf += parseInt(s.sacFlies) || 0;
      tb += parseInt(s.totalBases) || 0;
    });
    if (ab === 0) return { games: recent.length, ab: ab, h: h, hr: hr, avg: null, obp: null, slg: null, ops: null };
    var avg = h / ab;
    var obpDenom = ab + bb + hbp + sf;
    var obp = obpDenom > 0 ? (h + bb + hbp) / obpDenom : null;
    var slg = tb / ab;
    return { games: recent.length, ab: ab, h: h, hr: hr, avg: avg, obp: obp, slg: slg, ops: obp != null ? obp + slg : null };
  }

  function renderHeadlineStatsLoading(){
    var box = document.getElementById('dr-hub-headline-modal-stats');
    if (!box) return;
    box.style.display = '';
    box.innerHTML = '<div class="dr-hub-headline-stats-loading"><span class="spin"></span> Loading real season + last-10-game stats…</div>';
  }
  function hideHeadlineStats(){
    var box = document.getElementById('dr-hub-headline-modal-stats');
    if (!box) return;
    box.style.display = 'none';
    box.innerHTML = '';
  }
  function renderHeadlineStats(seasonStats, l10){
    var box = document.getElementById('dr-hub-headline-modal-stats');
    if (!box) return;
    var s = seasonStats || {};
    var hasSeason = (parseInt(s.atBats) || 0) > 0;
    var rowDelay = 0;
    var seasonRow = hasSeason ? '<div class="dr-hub-headline-stats-row" style="animation-delay:' + (rowDelay++ * 70) + 'ms"><div class="dr-hub-headline-stats-label">2026 SEASON</div><div class="dr-featured-player-stats">'
      + statPillHTML(fmtRate3(parseFloat(s.avg)), 'AVG') + statPillHTML(fmtRate3(parseFloat(s.obp)), 'OBP') + statPillHTML(fmtRate3(parseFloat(s.slg)), 'SLG') + statPillHTML(fmtRate3(parseFloat(s.ops)), 'OPS') + statPillHTML(null, 'HR', s.homeRuns != null ? parseInt(s.homeRuns) : NaN)
      + '</div></div>' : '';
    var l10Row = l10 && l10.ab > 0 ? '<div class="dr-hub-headline-stats-row" style="animation-delay:' + (rowDelay++ * 70) + 'ms"><div class="dr-hub-headline-stats-label">LAST ' + l10.games + ' GAME' + (l10.games === 1 ? '' : 'S') + '</div><div class="dr-featured-player-stats">'
      + statPillHTML(fmtRate3(l10.avg), 'AVG') + statPillHTML(fmtRate3(l10.ops), 'OPS') + statPillHTML(null, 'HR', l10.hr)
      + '</div></div>' : '';
    if (!seasonRow && !l10Row) { hideHeadlineStats(); return; }
    box.innerHTML = seasonRow + l10Row;
    box.style.display = '';
    // Deferred one frame: calling animateCountUp synchronously from here (a
    // promise callback, not an existing rAF frame) let its first internal
    // rAF occasionally fire with a timestamp at or before its own `start`
    // capture, producing a negative eased value and a one-frame "-0" flash.
    // requestAnimationFrame here first guarantees animateCountUp's own
    // start/first-frame pair are both inside the rAF timeline.
    box.querySelectorAll('b[data-count-to]').forEach(function(el){
      var target = parseInt(el.getAttribute('data-count-to'), 10);
      requestAnimationFrame(function(){ animateCountUp(el, target, 0, 600); });
    });
  }

  // Clicking a headline opens this popup in place rather than jumping straight
  // to the related board -- readers get the full story without leaving the
  // headlines feed. The popup's own buttons are the only things that actually
  // navigate (applyHeadlineLink) or open the video modal, and only when the
  // reader chooses to.
  //
  // Real season + last-10-game stats (roadmap: headlines feel bland once
  // opened) -- fetched live via the exact same fetchBatterSeasonBundle used
  // elsewhere in this app (openMatchup's batter stats, the lineup builder's
  // hot-hitter fallback), not a second copy of that MLB Stats API call. Only
  // fetched for headlines about a specific player (h.link.playerId) -- a
  // game-level headline like Weather has no player to show stats for.
  // headlineStatsReqId guards against a fast double-click (open headline A,
  // then B before A's fetch resolves) rendering A's stats into B's now-open
  // modal.
  var headlineStatsReqId = 0;
  function openHeadlineModal(h){
    var modal = document.getElementById('dr-hub-headline-modal');
    if (!modal || !h) return;
    var photo = document.getElementById('dr-hub-headline-modal-photo');
    var playerId = h.link && h.link.playerId;
    if (playerId) {
      photo.onerror = function(){ this.style.display = 'none'; };
      photo.src = hs(playerId);
      photo.style.display = '';
    } else {
      photo.removeAttribute('src');
      photo.style.display = 'none';
    }
    document.getElementById('dr-hub-headline-modal-cat').textContent = (CATEGORY_ICONS[h.category] ? CATEGORY_ICONS[h.category] + ' ' : '') + (CATEGORY_LABELS[h.category] || String(h.category || '').toUpperCase());
    document.getElementById('dr-hub-headline-modal-title').textContent = h.title || '';
    document.getElementById('dr-hub-headline-modal-blurb').textContent = h.blurb || '';

    var linkBtn = document.getElementById('dr-hub-headline-modal-link');
    if (h.link) {
      linkBtn.style.display = '';
      // A trend/streak headline carries the real opposing pitcher (row.pitcherId/
      // pitcherName, threaded through by generate-headlines.mjs) -- when it's
      // there, jump straight into the Matchup modal's Why Today tab instead of
      // just landing on the HR Threats board filtered to this player, which
      // still requires finding and clicking their card to see the actual read.
      if (h.link.pitcherId != null && typeof window.openMatchup === 'function') {
        linkBtn.textContent = 'See the Matchup →';
        linkBtn.onclick = function(){ closeHeadlineModal(); window.openMatchup(h.link.playerId, h.link.playerName, h.link.pitcherId, h.link.pitcherName); };
      } else {
        linkBtn.textContent = 'View related report →';
        linkBtn.onclick = function(){ closeHeadlineModal(); applyHeadlineLink(h.link); };
      }
    } else {
      linkBtn.style.display = 'none';
      linkBtn.onclick = null;
    }

    var clipBtn = document.getElementById('dr-hub-headline-modal-clip');
    if (h.clip && h.clip.videoUrl) {
      var catLabel = CATEGORY_LABELS[h.category] || String(h.category || '').toUpperCase();
      clipBtn.style.display = '';
      clipBtn.onclick = function(){ closeHeadlineModal(); openHRVideoModal(h.title, catLabel, h.clip.videoUrl); };
    } else {
      clipBtn.style.display = 'none';
      clipBtn.onclick = null;
    }

    var statsReq = ++headlineStatsReqId;
    if (playerId && typeof fetchBatterSeasonBundle === 'function') {
      renderHeadlineStatsLoading();
      fetchBatterSeasonBundle(playerId, new Date().getFullYear()).then(function(bundle){
        if (statsReq !== headlineStatsReqId) return;
        renderHeadlineStats(bundle.seasonStats, aggregateLastNGames(bundle.logs, 10));
      }).catch(function(){
        if (statsReq !== headlineStatsReqId) return;
        hideHeadlineStats();
      });
    } else {
      hideHeadlineStats();
    }

    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
  }

  function closeHeadlineModal(){
    var modal = document.getElementById('dr-hub-headline-modal');
    if (!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
  }

  function renderHubHeadlines(data){
    var section = document.getElementById('dr-hub-headlines');
    var grid = document.getElementById('dr-hub-headlines-grid');
    if (!section || !grid || !data) return;
    var headlines = Array.isArray(data.headlines) ? data.headlines : [];
    if (!headlines.length) return;

    // Server order is already the real most-important-first ranking: recap
    // (today's context) leads, then the small set of one-off editorial picks
    // (notable performance, weather, injury, model move, leaderboard -- each
    // at most one real headline), THEN real trend headlines ranked by
    // scoreForMarket, then real streak headlines ranked by how extreme the
    // actual ratio is (hot or cold). trend and streak intentionally cover
    // EVERY real qualifying player (not a curated top-N) per
    // generate-headlines.mjs and can legitimately run into the hundreds on an
    // active day -- the one-off picks are pushed ahead of that flood
    // server-side specifically so they land within the leading
    // headlinesVisibleCount instead of getting buried at the tail of "View
    // More" pagination. Capped here to the leading headlinesVisibleCount, with
    // "View More" revealing the rest rather than dropping any real story.
    headlinesAll = headlines;
    activeHeadlineCategory = 'all';
    headlinesVisibleCount = Math.min(6, headlinesAll.length);

    var moreBtn = document.getElementById('dr-hub-headlines-more');
    if (moreBtn && !moreBtn.dataset.drBound) {
      moreBtn.dataset.drBound = '1';
      moreBtn.addEventListener('click', function(){
        headlinesVisibleCount = Math.min(headlinesVisibleCount + 6, filteredHeadlines().length);
        renderHeadlinesGrid();
      });
    }

    renderHeadlineFilters();
    renderHeadlinesGrid();
    section.style.display = '';
  }

  function filteredHeadlines(){
    if (activeHeadlineCategory === 'all') return headlinesAll;
    if (activeHeadlineCategory === 'more') {
      return headlinesAll.filter(function(h){ return smallHeadlineCategories.indexOf(h.category) !== -1; });
    }
    return headlinesAll.filter(function(h){ return h.category === activeHeadlineCategory; });
  }

  // One chip per category that actually has >=1 real headline today (plus "All"),
  // each labeled with its real count -- a category with zero real headlines today
  // simply gets no chip, same "never fabricate a control for data that doesn't
  // exist" standard as everywhere else. Same pill-tab visual language as the
  // MLB/NFL/NBA sport tabs above on this same page.
  //
  // Categories below MIN_HEADLINE_CHIP_COUNT collapse into a single "More" chip
  // instead of each getting their own pill. On a normal day trend/streak
  // legitimately cover hundreds of real players while recap/notable/weather/
  // injury/model/leaderboard are each a single hand-picked daily pick -- without
  // this, 5-6 chips that only ever say "1" crowd out the two real-volume filters.
  // Purely count-driven (not a hardcoded list of "minor" categories), so a
  // category earns its own chip the moment it produces enough real headlines to
  // deserve one, same as any other real-number-or-nothing threshold in this app.
  var MIN_HEADLINE_CHIP_COUNT = 3;
  function renderHeadlineFilters(){
    var wrap = document.getElementById('dr-hub-headline-filters');
    if (!wrap) return;
    var counts = {};
    headlinesAll.forEach(function(h){ counts[h.category] = (counts[h.category] || 0) + 1; });
    var cats = Object.keys(counts).sort(function(a, b){ return counts[b] - counts[a]; });
    if (cats.length < 2) { wrap.innerHTML = ''; wrap.style.display = 'none'; return; }

    var bigCats = cats.filter(function(c){ return counts[c] >= MIN_HEADLINE_CHIP_COUNT; });
    var smallCats = cats.filter(function(c){ return counts[c] < MIN_HEADLINE_CHIP_COUNT; });
    smallHeadlineCategories = smallCats;
    // A lone small category doesn't need the generic "More" label/grouping
    // behavior -- just show it as its own chip, same as before this change.
    if (smallCats.length === 1) { bigCats = bigCats.concat(smallCats); smallCats = []; smallHeadlineCategories = []; }

    var chips = ['<button type="button" class="dr-hub-headline-filter' + (activeHeadlineCategory === 'all' ? ' active' : '') + '" data-headline-filter="all">All <span class="dr-hub-headline-filter-count">' + headlinesAll.length + '</span></button>'];
    bigCats.forEach(function(cat){
      var label = CATEGORY_LABELS[cat] || String(cat).toUpperCase();
      chips.push('<button type="button" class="dr-hub-headline-filter' + (activeHeadlineCategory === cat ? ' active' : '') + '" data-headline-filter="' + cat + '">' + label + ' <span class="dr-hub-headline-filter-count">' + counts[cat] + '</span></button>');
    });
    if (smallCats.length) {
      var moreCount = smallCats.reduce(function(n, c){ return n + counts[c]; }, 0);
      var moreTitle = smallCats.map(function(c){ return CATEGORY_LABELS[c] || String(c).toUpperCase(); }).join(', ');
      chips.push('<button type="button" class="dr-hub-headline-filter' + (activeHeadlineCategory === 'more' ? ' active' : '') + '" data-headline-filter="more" title="' + escapeHtml(moreTitle) + '">More <span class="dr-hub-headline-filter-count">' + moreCount + '</span></button>');
    }
    wrap.innerHTML = chips.join('');
    wrap.style.display = '';

    wrap.querySelectorAll('[data-headline-filter]').forEach(function(btn){
      btn.addEventListener('click', function(){
        activeHeadlineCategory = btn.getAttribute('data-headline-filter');
        headlinesVisibleCount = Math.min(6, filteredHeadlines().length);
        renderHeadlineFilters();
        renderHeadlinesGrid();
      });
    });
  }

  function renderHeadlinesGrid(){
    var grid = document.getElementById('dr-hub-headlines-grid');
    if (!grid) return;
    var headlines = filteredHeadlines().slice(0, headlinesVisibleCount);

    grid.innerHTML = '';
    headlines.forEach(function(h, i){
      var catLabel = CATEGORY_LABELS[h.category] || String(h.category || '').toUpperCase();
      var card = document.createElement('div');
      // "lead" (bigger, full-width) is tied to the recap headline itself, not
      // positional luck -- so filtering to a non-recap category never
      // stretches an arbitrary first card, and filtering to "Recap" still
      // shows it full-width.
      card.className = 'dr-hub-headline-card dr-anim-in' + (h.category === 'recap' ? ' lead' : '');
      card.style.animationDelay = Math.min(i, 8) * 25 + 'ms';
      card.setAttribute('data-category', h.category || '');
      card.addEventListener('click', function(){ openHeadlineModal(h); });

      // Same ESPN "Around the Leagues" card shape (renderHubNews below) --
      // a full-bleed photo on top, no gap/border under it, rather than the
      // old small round avatar. Only rendered when there's a real player
      // photo to show; a headline with none (weather, recap, etc.) just
      // skips straight to the text body.
      var playerId = h.link && h.link.playerId;
      if (playerId) {
        var photo = document.createElement('img');
        photo.className = 'dr-hub-headline-photo-big';
        photo.src = hsBig(playerId);
        photo.alt = '';
        photo.loading = 'lazy';
        photo.decoding = 'async';
        photo.onerror = function(){ this.style.display = 'none'; };
        card.appendChild(photo);
      }

      var body = document.createElement('div');
      body.className = 'dr-hub-headline-body';

      var cat = document.createElement('div');
      cat.className = 'dr-hub-headline-cat';
      cat.textContent = (CATEGORY_ICONS[h.category] ? CATEGORY_ICONS[h.category] + ' ' : '') + catLabel;
      body.appendChild(cat);

      var title = document.createElement('div');
      title.className = 'dr-hub-headline-title';
      title.textContent = h.title || '';
      body.appendChild(title);

      // Real stat chip -- generate-headlines.mjs now carries the same number
      // that already ranked/selected this headline (HR probability for trend,
      // real last-10-games HR count for streak) instead of dropping it once
      // the headline text was written. Turns "here's a story" into "here's a
      // story plus a real number to check," which is the whole point of
      // surfacing it before a reader ever opens the matchup. Older headline
      // JSON generated before this field existed just won't have h.stat, and
      // the chip simply doesn't render -- no fabricated fallback number.
      if (h.stat && h.stat.value != null) {
        var statChip = document.createElement('div');
        statChip.className = 'dr-hub-headline-stat';
        if (h.stat.kind === 'hrProb') {
          statChip.classList.add('is-neutral');
          statChip.innerHTML = '<strong>' + escapeHtml(String(h.stat.value)) + '%</strong><span>HR Probability</span>';
        } else if (h.stat.kind === 'last10HR') {
          statChip.classList.add(h.stat.favorable ? 'is-positive' : 'is-negative');
          statChip.innerHTML = '<strong>' + escapeHtml(String(h.stat.value)) + '</strong><span>HR L10</span>';
        }
        if (statChip.innerHTML) body.appendChild(statChip);
      }

      var blurb = document.createElement('p');
      blurb.className = 'dr-hub-headline-blurb';
      blurb.textContent = h.blurb || '';
      body.appendChild(blurb);

      var actions = document.createElement('div');
      actions.className = 'dr-hub-headline-actions';
      if (h.link) {
        var linkBtn = document.createElement('button');
        linkBtn.type = 'button';
        linkBtn.className = 'dr-hub-headline-link';
        linkBtn.textContent = h.link.pitcherId != null ? 'See the Matchup →' : 'View related report →';
        linkBtn.addEventListener('click', function(e){ e.stopPropagation(); openHeadlineModal(h); });
        actions.appendChild(linkBtn);
      }
      if (h.clip && h.clip.videoUrl) {
        var clipBtn = document.createElement('button');
        clipBtn.type = 'button';
        clipBtn.className = 'dr-hub-headline-clip';
        clipBtn.textContent = '▶ Watch';
        clipBtn.addEventListener('click', function(e){ e.stopPropagation(); openHRVideoModal(h.title, catLabel, h.clip.videoUrl); });
        actions.appendChild(clipBtn);
      }
      if (actions.childNodes.length) body.appendChild(actions);

      card.appendChild(body);
      grid.appendChild(card);
    });

    var moreBtn = document.getElementById('dr-hub-headlines-more');
    if (moreBtn) moreBtn.style.display = headlinesVisibleCount < filteredHeadlines().length ? '' : 'none';
  }

  var trendingPlayersLoaded = false;
  function loadTrendingPlayers(){
    if (trendingPlayersLoaded) return;
    trendingPlayersLoaded = true;
    drFetchDailyJSON('data/trending-players.json').then(function(data){
      renderTrendingPlayers(data);
    }).catch(function(){
      // Previously a silent catch(){} -- the section starts display:none and
      // is only ever revealed by renderTrendingPlayers on real success, so a
      // fetch failure here used to leave it hidden forever with zero signal
      // anything had gone wrong. Reset the one-shot guard so Retry can
      // actually re-fetch (trendingPlayersLoaded normally blocks re-entry
      // after the first call).
      trendingPlayersLoaded = false;
      var section = document.getElementById('dr-hub-trending');
      var grid = document.getElementById('dr-hub-trending-grid');
      if (section && grid) {
        section.style.display = '';
        drShowError(grid, "Couldn't load trending players.", loadTrendingPlayers);
      }
    });
  }

  // Small decorative HR-landing-spot dot plot -- same real xFt/yFt/distance
  // fields the full Matchup modal's spray chart uses (see hrSprayChartHTML
  // there), just a compact generic-diamond version: this card isn't tied to
  // a specific game/park, so there's no "today's park" to draw an accurate
  // wall against.
  function trendingBatterSprayHTML(dots){
    var W = 160, H = 120, plateX = W / 2, plateY = H - 8;
    var maxDist = dots.reduce(function(m, d){ return Math.max(m, d.distance || 0); }, 350);
    var scale = (plateY - 14) / Math.max(maxDist, 350);
    var wallPath = 'M ' + plateX + ',' + plateY + ' L 12,36 Q ' + plateX + ',8 ' + (W - 12) + ',36 Z';
    var circles = dots.map(function(d){
      var cx = Math.max(4, Math.min(W - 4, plateX + (d.xFt || 0) * scale));
      var cy = Math.max(4, Math.min(plateY - 2, plateY - (d.yFt || 0) * scale));
      var title = d.distance != null ? Math.round(d.distance) + ' ft' : '';
      return '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="3.5" fill="#f6c343" fill-opacity=".9" stroke="#0a0e1a" stroke-width="1"><title>' + title + '</title></circle>';
    }).join('');
    return '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;display:block">' +
      '<path d="' + wallPath + '" fill="rgba(120,150,200,.08)" stroke="rgba(255,255,255,.25)" stroke-width="1.2"/>' + circles + '</svg>';
  }

  // Small pitch-type-colored whiff scatter over a generic strike-zone box --
  // reuses the exact real pitchTypeColor() mapping the Pitcher Analytics
  // Dashboard's own charts use (top-level function, defined near
  // blendRecentForm), so a given pitch type reads the same color everywhere
  // on the site, not just inside a pitcher's own dashboard.
  function trendingPitcherWhiffHTML(dots){
    var W = 160, H = 120;
    var X_MIN = -1.6, X_MAX = 1.6, Z_MIN = 0.3, Z_MAX = 4.7;
    var ZONE_HALF_W = 0.83, ZONE_BOT = 1.5, ZONE_TOP = 3.5;
    function toXY(px, pz){
      return {
        x: 8 + ((px - X_MIN) / (X_MAX - X_MIN)) * (W - 16),
        y: H - 8 - ((pz - Z_MIN) / (Z_MAX - Z_MIN)) * (H - 16),
      };
    }
    var zoneTL = toXY(-ZONE_HALF_W, ZONE_TOP), zoneBR = toXY(ZONE_HALF_W, ZONE_BOT);
    var circles = dots.map(function(d){
      var xy = toXY(d.plateX || 0, d.plateZ || 0);
      var cx = Math.max(4, Math.min(W - 4, xy.x)), cy = Math.max(4, Math.min(H - 4, xy.y));
      var color = pitchTypeColor(d.pitchName || '');
      return '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="3.5" fill="' + color + '" fill-opacity=".9" stroke="#0a0e1a" stroke-width="1"><title>' + drEscAttr(d.pitchName || '') + '</title></circle>';
    }).join('');
    return '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;display:block">' +
      '<rect x="' + zoneTL.x.toFixed(1) + '" y="' + zoneTL.y.toFixed(1) + '" width="' + (zoneBR.x - zoneTL.x).toFixed(1) + '" height="' + (zoneBR.y - zoneTL.y).toFixed(1) + '" fill="rgba(120,150,200,.08)" stroke="rgba(255,255,255,.3)" stroke-width="1.2"/>' + circles + '</svg>';
  }

  // One card's markup -- shared by both the batter (HR pace) and pitcher (whiff
  // rate) subgroups in renderTrendingPlayers below, since a card looks and
  // behaves identically either way; only which subgroup it lands in differs.
  function buildTrendingCard(p, i){
      var card = document.createElement('div');
      card.className = 'dr-hub-trending-card dr-anim-in';
      card.style.animationDelay = Math.min(i, 8) * 25 + 'ms';
      if (p.trendMetric) card.title = p.trendMetric;

      var visualWrap = document.createElement('div');
      visualWrap.className = 'dr-hub-trending-visual';
      if (p.visual && p.visual.type === 'whiff') visualWrap.innerHTML = trendingPitcherWhiffHTML(p.visual.dots || []);
      else if (p.visual && p.visual.type === 'spray') visualWrap.innerHTML = trendingBatterSprayHTML(p.visual.dots || []);
      card.appendChild(visualWrap);

      var info = document.createElement('div');
      info.className = 'dr-hub-trending-info';

      if (p.playerId) {
        var photo = document.createElement('img');
        photo.className = 'dr-hub-trending-photo';
        photo.src = hs(p.playerId);
        photo.alt = '';
        photo.loading = 'lazy';
        photo.decoding = 'async';
        photo.onerror = function(){ this.style.display = 'none'; };
        info.appendChild(photo);
      }

      var text = document.createElement('div');
      text.className = 'dr-hub-trending-text';
      var nameEl = document.createElement('div');
      nameEl.className = 'dr-hub-trending-name';
      nameEl.textContent = p.name || '';
      text.appendChild(nameEl);
      var subEl = document.createElement('div');
      subEl.className = 'dr-hub-trending-sub';
      subEl.textContent = (p.visual && p.visual.label) || '';
      text.appendChild(subEl);

      // Stacked under name/sub (not a sibling flex item sharing the row with the
      // photo) so the pct chip's own width never eats into the space available
      // for the player's name -- that's what was truncating names like "Luis
      // Rengifo" down to "Luis ..." on mobile before.
      var pctEl = document.createElement('div');
      pctEl.className = 'dr-hub-trending-pct';
      var pctVal = Number(p.trendPct) || 0;
      // trendPctCapped (see generate-headlines.mjs's TRENDING_PCT_CAP): a light
      // hitter with a near-zero expected HR pace can post a real but absurd-looking
      // 900%+ ratio off one hot stretch -- capped server-side and flagged here so
      // the '+' honestly signals "at least this much" instead of a fabricated number.
      pctEl.textContent = 'Trending ' + (pctVal >= 0 ? '↑' : '↓') + Math.abs(pctVal) + (p.trendPctCapped ? '%+' : '%');
      text.appendChild(pctEl);
      info.appendChild(text);

      card.appendChild(info);

      // Batters reuse the exact same #gamepick=hr + name-search pattern the
      // headline cards' applyHeadlineLink already uses. Pitchers land on the
      // real Strikeouts pane (#gamepick=k, a confirmed valid VALID[] key) --
      // that board's own search-stuffing hook isn't wired the same way, so
      // this just navigates there rather than guessing at an unverified call.
      if (p.playerId) {
        card.style.cursor = 'pointer';
        card.addEventListener('click', function(){
          if (p.type === 'pitcher') {
            window.location.hash = 'gamepick=k';
          } else {
            window.location.hash = 'gamepick=hr';
            setTimeout(function(){
              if (typeof window.setPropSearchFilter === 'function') window.setPropSearchFilter('hr', p.name);
            }, 60);
          }
        });
      }

      return card;
  }

  // Separated into two labeled subgroups by what's actually trending (HR pace
  // for hitters, whiff rate for pitchers) instead of one mixed strip -- those
  // are two different stats on two different scales, and lumping them together
  // made it unclear at a glance which kind of "trending" a given card meant.
  // Each subgroup is its own horizontal-scroll row and is only rendered when it
  // has at least one real qualifying player, same "hide rather than show empty"
  // rule the section itself already follows.
  function renderTrendingSubgroup(container, label, players){
    if (!players.length) return;
    var group = document.createElement('div');
    group.className = 'dr-hub-trending-subgroup';
    var head = document.createElement('div');
    head.className = 'dr-hub-trending-subhead';
    head.textContent = label;
    group.appendChild(head);
    var row = document.createElement('div');
    row.className = 'dr-hub-trending-grid';
    players.forEach(function(p, i){ row.appendChild(buildTrendingCard(p, i)); });
    group.appendChild(row);
    container.appendChild(group);
  }

  function renderTrendingPlayers(data){
    var section = document.getElementById('dr-hub-trending');
    var grid = document.getElementById('dr-hub-trending-grid');
    if (!section || !grid || !data) return;
    var players = Array.isArray(data.players) ? data.players : [];
    if (!players.length) return;

    grid.innerHTML = '';
    grid.className = 'dr-hub-trending-groups';
    var batters = players.filter(function(p){ return p.type !== 'pitcher'; });
    var pitchers = players.filter(function(p){ return p.type === 'pitcher'; });
    renderTrendingSubgroup(grid, '🔥 Hot At The Plate — HR Pace', batters);
    renderTrendingSubgroup(grid, '🎯 Trending Arms — Whiff Rate', pitchers);
    section.style.display = '';
  }

  // Whether any of today's games has actually started yet (Live or Final).
  // Defaults to true (i.e. "yes, started") on any fetch failure — if we
  // can't tell, it's safer to fall back to the plain empty-state link than
  // to risk showing yesterday's home runs as if they were today's.
  function hasAnyGameStartedToday(){
    var todayStr = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
    return fetch('https://diamondreport.app/api/v1/schedule?sportId=1&date=' + todayStr + '&hydrate=status&language=en')
      .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function(data){
        var entry = (data.dates || []).find(function(d){ return d.date === todayStr; }) || (data.dates && data.dates[0]);
        var games = (entry && entry.games) || [];
        return games.some(function(g){
          var st = g.status && g.status.abstractGameState;
          return st === 'Live' || st === 'Final';
        });
      })
      .catch(function(){ return true; });
  }

  // Self-contained variant of loadHRsToday's boxscore-scanning logic for an
  // arbitrary date, used only to fetch yesterday's home runs for the hub
  // fallback below. Deliberately doesn't touch bannerHRs, #hrs-today-content,
  // or any other global state loadHRsToday manages — this is read-only, for
  // display here only.
  function fetchHRsForDate(dateStr){
    return fetch('https://diamondreport.app/api/v1/schedule?sportId=1&date=' + dateStr + '&hydrate=team&language=en')
      .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function(data){
        var entry = (data.dates || []).find(function(d){ return d.date === dateStr; }) || (data.dates && data.dates[0]);
        var games = (entry && entry.games) || [];
        return Promise.all(games.map(function(g){
          return fetch('https://diamondreport.app/api/v1/game/' + g.gamePk + '/boxscore')
            .then(function(r){ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
            .then(function(bd){ return bd.teams; })
            .catch(function(){ return null; });
        })).then(function(boxscores){
          var allHRs = [];
          games.forEach(function(g, gi){
            var box = boxscores[gi];
            if (!box || !g.teams) return;
            var dt = new Date(g.gameDate);
            var timeStr = dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: 'America/Chicago' });
            var awayAbbr = g.teams.away && g.teams.away.team && g.teams.away.team.abbreviation;
            var homeAbbr = g.teams.home && g.teams.home.team && g.teams.home.team.abbreviation;
            ['away', 'home'].forEach(function(side){
              var team = box[side];
              if (!team) return;
              var abbr = side === 'away' ? awayAbbr : homeAbbr;
              (team.batters || []).forEach(function(id){
                var p = team.players && team.players['ID' + id];
                var hrs = parseInt(p && p.stats && p.stats.batting && p.stats.batting.homeRuns) || 0;
                if (hrs > 0) allHRs.push({
                  name: (p.person && p.person.fullName) || '–',
                  id: p.person && p.person.id,
                  teamAbbr: abbr,
                  hrs: hrs,
                  gameLabel: awayAbbr + ' @ ' + homeAbbr,
                  timeStr: timeStr,
                  gameTimestamp: dt.getTime(),
                  gamePk: g.gamePk
                });
              });
            });
          });
          allHRs.sort(function(a, b){ return a.gameTimestamp - b.gameTimestamp || b.hrs - a.hrs; });
          return allHRs;
        });
      })
      .catch(function(){ return []; });
  }

  function loadHubHRs(){
    if (hrLoaded) return;
    hrLoaded = true;
    try {
      var maybePromise = typeof window.loadHRsToday === 'function' ? window.loadHRsToday() : null;
      Promise.resolve(maybePromise).then(function(){
        var todaysHRs = window.__drHRsToday || [];
        if (todaysHRs.length) {
          renderHubHRs(todaysHRs);
          return;
        }
        // Nothing today yet — if that's because the first game of the day
        // hasn't started, keep showing yesterday's home runs instead of
        // reverting to the plain "watch highlights" link for however many
        // hours it is until first pitch.
        hasAnyGameStartedToday().then(function(started){
          if (started) return;
          var yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);
          var yStr = yesterday.toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
          fetchHRsForDate(yStr).then(function(list){
            if (!list.length) return;
            var heading = document.getElementById('dr-hub-hr-heading');
            if (heading) heading.textContent = "Yesterday's Home Run Highlights";
            renderHubHRs(list, 'yesterday');
          });
        });
      }).catch(function(){ /* leave the generic fallback link in place */ });
    } catch(e) { /* leave the generic fallback link in place */ }
  }

  // ── Home Run Highlights Carousel ──────────────────────────────────────
  // A richer, auto-playing companion to the "Home Run Highlights" side-rail
  // above -- same real today/yesterday-fallback data source (loadHRsToday /
  // fetchHRsForDate), but each slide gets a real muted-autoplay MLB highlight
  // clip (fetchGameContent/findHRClipUrl -- MLB's own official content API,
  // a direct playable clip URL; deliberately NOT the Savant gf-feed path
  // sync-near-hrs.mjs uses, which has a known unresolved 0%-match bug), plus
  // real HR trend, hard-hit%/barrel%, and the next real probable-pitcher
  // matchup. Every field is real or simply omitted from the card -- never
  // fabricated. The whole section stays hidden when there are zero real HRs
  // to show (no fallback content, same as the side-rail's own honesty
  // standard).
  var hrCarouselSlides = [];
  var hrCarouselIndex = 0;
  var hrCarouselPlaying = true;
  var hrCarouselMuted = true; // starts muted -- browser autoplay policy requires
                               // it, and this app's own acceptance bar ("autoplay
                               // does not play disruptive audio") requires it too
  var hrCarouselAdvanceTimer = null;
  var hrCarouselLoaded = false;
  var HR_CAROUSEL_MAX_SLIDES = 8;
  var HR_CAROUSEL_FALLBACK_MS = 12000; // advance even if a clip never resolves/plays

  function loadHRCarousel(){
    if (hrCarouselLoaded) return;
    hrCarouselLoaded = true;
    try {
      var maybePromise = typeof window.loadHRsToday === 'function' ? window.loadHRsToday() : null;
      Promise.resolve(maybePromise).then(function(){
        var todaysHRs = window.__drHRsToday || [];
        if (todaysHRs.length) { initHRCarousel(todaysHRs); return; }
        hasAnyGameStartedToday().then(function(started){
          if (started) return; // real games underway with zero real HRs yet -- stay hidden, not stale
          var yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);
          var yStr = yesterday.toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
          fetchHRsForDate(yStr).then(function(list){
            if (list.length) initHRCarousel(list);
          });
        });
      }).catch(function(){});
    } catch(e) {}
  }
  window.loadHRCarousel = loadHRCarousel;

  // Dedupe by batter id (a multi-HR game, or a doubleheader, can produce more
  // than one real entry for the same player) keeping their best (highest-HR)
  // entry, capped to a real top N most-recent so the carousel stays tight.
  function buildHRCarouselSlideList(rawList){
    var byId = {};
    (rawList || []).forEach(function(h){
      if (!h.id) return;
      var existing = byId[h.id];
      if (!existing || h.hrs > existing.hrs) byId[h.id] = h;
    });
    return Object.keys(byId).map(function(id){ return byId[id]; })
      .sort(function(a, b){ return b.gameTimestamp - a.gameTimestamp || b.hrs - a.hrs; })
      .slice(0, HR_CAROUSEL_MAX_SLIDES);
  }

  function initHRCarousel(rawList){
    var slides = buildHRCarouselSlideList(rawList);
    if (!slides.length) return;
    hrCarouselSlides = slides.map(function(h){
      return {
        id: h.id, name: h.name, teamAbbr: h.teamAbbr, hrs: h.hrs, gamePk: h.gamePk, gameLabel: h.gameLabel,
        videoUrl: null, webUrl: null, trend: null, recentGames: null, hardHitPct: null, barrelPct: null,
        nextOpp: null, nextPitcherName: null, nextPitcherId: null,
      };
    });
    var section = document.getElementById('dr-hub-hr-carousel');
    if (section) section.style.display = '';
    renderHRCarouselShell();
    goToHRCarouselSlide(0);
    enrichHRCarouselSlides();
  }
  window.initHRCarousel = initHRCarousel;

  function enrichHRCarouselSlides(){
    // Hard-hit%/barrel% -- one shared JSON file, real fields already used
    // elsewhere in this app (Featured Home Run Pick card, cold-batter panel).
    (typeof loadStatcastHotHitters === 'function' ? loadStatcastHotHitters() : Promise.resolve()).catch(function(){}).then(function(){
      if (typeof statcastHotHitters === 'undefined' || !statcastHotHitters) return;
      hrCarouselSlides.forEach(function(slide){
        var hh = statcastHotHitters[String(slide.id)] || statcastHotHitters[String(slide.name || '').toLowerCase()];
        if (!hh) return;
        slide.hardHitPct = hh.hardHitPct != null ? parseFloat(hh.hardHitPct) : null;
        slide.barrelPct = hh.barrelPct != null ? parseFloat(hh.barrelPct) : null;
        refreshHRCarouselStatCard(slide.id);
      });
    });

    // Real HR trend (computePlayerTrendIndicator) + a real last-5-games HR line --
    // one fetch (season stats + real game log) covers both, same endpoint the
    // Pitcher Report lineup/K-prop code already uses.
    var season = new Date().getFullYear();
    hrCarouselSlides.forEach(function(slide){
      if (typeof fetchBatterSeasonBundle !== 'function') return;
      fetchBatterSeasonBundle(slide.id, season, {}).then(function(bundle){
        var logs = bundle.logs || [];
        var last10HR = logs.slice(0, 10).reduce(function(sum, g){ return sum + (parseInt(g.stat && g.stat.homeRuns) || 0); }, 0);
        var atBats = parseInt(bundle.seasonStats && bundle.seasonStats.atBats) || 0;
        var hrSeason = parseInt(bundle.seasonStats && bundle.seasonStats.homeRuns) || 0;
        slide.trend = (typeof window.computePlayerTrendIndicator === 'function' && atBats > 0)
          ? window.computePlayerTrendIndicator({ last10HR: last10HR, atBats: atBats, hrSeason: hrSeason })
          : null;
        slide.recentGames = logs.slice(0, 5).map(function(g){ return parseInt(g.stat && g.stat.homeRuns) || 0; });
        refreshHRCarouselStatCard(slide.id);
      }).catch(function(){});
    });

    // Real next-game probable opposing pitcher -- one shared today's-schedule
    // fetch for the whole carousel (not one per slide). A team with no game
    // today (off day) simply gets no next-matchup line, never a guess.
    if (typeof getTodaySchedule === 'function') {
      getTodaySchedule('team,probablePitcher').then(function(games){
        hrCarouselSlides.forEach(function(slide){
          var game = (games || []).find(function(g){
            return g.teams && ((g.teams.home.team.abbreviation === slide.teamAbbr) || (g.teams.away.team.abbreviation === slide.teamAbbr));
          });
          if (!game) return;
          var isHome = game.teams.home.team.abbreviation === slide.teamAbbr;
          var oppSide = isHome ? 'away' : 'home';
          var oppTeam = game.teams[oppSide];
          slide.nextOpp = oppTeam.team.abbreviation;
          if (oppTeam.probablePitcher) {
            slide.nextPitcherName = oppTeam.probablePitcher.fullName;
            slide.nextPitcherId = oppTeam.probablePitcher.id;
          }
          refreshHRCarouselStatCard(slide.id);
        });
      }).catch(function(){});
    }

    // Real MLB highlight clip -- same resolution path (and cache) as the side-rail's
    // renderHubHRs above.
    hrCarouselSlides.forEach(function(slide){
      if (!slide.gamePk) return;
      fetchGameContent(slide.gamePk).then(function(items){
        var found = findHRClipUrl(items, slide.name);
        slide.videoUrl = found.videoUrl;
        slide.webUrl = found.webUrl;
        if (hrCarouselSlides[hrCarouselIndex] === slide) playHRCarouselVideo(slide);
      });
    });
  }

  function renderHRCarouselShell(){
    var wrap = document.getElementById('dr-hub-hr-carousel-body');
    if (!wrap) return;
    var dots = hrCarouselSlides.map(function(s, i){
      return '<button type="button" class="dr-hrc-dot' + (i === 0 ? ' active' : '') + '" data-hrc-dot="' + i + '" aria-label="Go to slide ' + (i + 1) + '"></button>';
    }).join('');
    wrap.innerHTML =
      '<div class="dr-hrc-stage">' +
        '<video id="dr-hrc-video" class="dr-hrc-video" playsinline muted></video>' +
        '<div class="dr-hrc-noclip" id="dr-hrc-noclip">🎥<span>No clip available yet</span></div>' +
        '<div class="dr-hrc-controls">' +
          '<button type="button" class="dr-hrc-btn" id="dr-hrc-prev" aria-label="Previous home run">‹</button>' +
          '<button type="button" class="dr-hrc-btn" id="dr-hrc-playpause" aria-label="Pause carousel">⏸</button>' +
          '<div class="dr-hrc-dots">' + dots + '</div>' +
          '<button type="button" class="dr-hrc-btn" id="dr-hrc-mute" aria-label="Unmute">🔇</button>' +
          '<button type="button" class="dr-hrc-btn" id="dr-hrc-next" aria-label="Next home run">›</button>' +
        '</div>' +
      '</div>' +
      '<button type="button" class="dr-hrc-card" id="dr-hrc-card" aria-label="View full matchup"></button>';

    document.getElementById('dr-hrc-prev').addEventListener('click', function(e){ e.stopPropagation(); hrCarouselGoPrev(); });
    document.getElementById('dr-hrc-next').addEventListener('click', function(e){ e.stopPropagation(); hrCarouselGoNext(); });
    document.getElementById('dr-hrc-playpause').addEventListener('click', function(e){ e.stopPropagation(); hrCarouselTogglePlay(); });
    document.getElementById('dr-hrc-mute').addEventListener('click', function(e){ e.stopPropagation(); hrCarouselToggleMute(); });
    wrap.querySelectorAll('[data-hrc-dot]').forEach(function(btn){
      btn.addEventListener('click', function(e){ e.stopPropagation(); goToHRCarouselSlide(parseInt(btn.getAttribute('data-hrc-dot'), 10)); });
    });
    document.getElementById('dr-hrc-card').addEventListener('click', function(){ openHRCarouselMatchup(); });

    var video = document.getElementById('dr-hrc-video');
    video.addEventListener('ended', function(){ if (hrCarouselPlaying) hrCarouselGoNext(); });

    // Basic touch-swipe for mobile -- separate from the control-bar buttons above
    // (which stopPropagation, so a tap there is never misread as a swipe).
    var stage = wrap.querySelector('.dr-hrc-stage');
    var touchStartX = null;
    stage.addEventListener('touchstart', function(e){ touchStartX = e.touches[0].clientX; }, { passive: true });
    stage.addEventListener('touchend', function(e){
      if (touchStartX == null) return;
      var dx = e.changedTouches[0].clientX - touchStartX;
      touchStartX = null;
      if (Math.abs(dx) < 40) return;
      if (dx < 0) hrCarouselGoNext(); else hrCarouselGoPrev();
    }, { passive: true });
  }

  function goToHRCarouselSlide(i){
    if (!hrCarouselSlides.length) return;
    hrCarouselIndex = ((i % hrCarouselSlides.length) + hrCarouselSlides.length) % hrCarouselSlides.length;
    var slide = hrCarouselSlides[hrCarouselIndex];
    renderHRCarouselStatCard(slide);
    playHRCarouselVideo(slide);
    document.querySelectorAll('#dr-hub-hr-carousel-body [data-hrc-dot]').forEach(function(dot, i2){
      dot.classList.toggle('active', i2 === hrCarouselIndex);
    });
    clearTimeout(hrCarouselAdvanceTimer);
    if (hrCarouselPlaying) hrCarouselAdvanceTimer = setTimeout(function(){ hrCarouselGoNext(); }, HR_CAROUSEL_FALLBACK_MS);
  }
  function hrCarouselGoNext(){ goToHRCarouselSlide(hrCarouselIndex + 1); }
  function hrCarouselGoPrev(){ goToHRCarouselSlide(hrCarouselIndex - 1); }

  function playHRCarouselVideo(slide){
    var video = document.getElementById('dr-hrc-video');
    var noclip = document.getElementById('dr-hrc-noclip');
    if (!video) return;
    if (slide.videoUrl) {
      if (video.getAttribute('data-src') !== slide.videoUrl) {
        video.src = slide.videoUrl;
        video.setAttribute('data-src', slide.videoUrl);
      }
      video.muted = hrCarouselMuted;
      video.style.display = '';
      if (noclip) noclip.style.display = 'none';
      if (hrCarouselPlaying) video.play().catch(function(){});
    } else {
      video.pause();
      video.removeAttribute('src');
      video.setAttribute('data-src', '');
      video.load();
      video.style.display = 'none';
      // 'flex' (not '') -- .dr-hrc-noclip's own CSS rule defaults to display:none,
      // so clearing the inline style here would just fall back to that same hidden
      // default instead of actually showing the placeholder.
      if (noclip) noclip.style.display = 'flex';
    }
  }

  function hrCarouselTogglePlay(){
    hrCarouselPlaying = !hrCarouselPlaying;
    var video = document.getElementById('dr-hrc-video');
    var btn = document.getElementById('dr-hrc-playpause');
    if (btn) { btn.textContent = hrCarouselPlaying ? '⏸' : '▶'; btn.setAttribute('aria-label', hrCarouselPlaying ? 'Pause carousel' : 'Play carousel'); }
    if (video) { if (hrCarouselPlaying) video.play().catch(function(){}); else video.pause(); }
    clearTimeout(hrCarouselAdvanceTimer);
    if (hrCarouselPlaying) hrCarouselAdvanceTimer = setTimeout(function(){ hrCarouselGoNext(); }, HR_CAROUSEL_FALLBACK_MS);
  }

  function hrCarouselToggleMute(){
    hrCarouselMuted = !hrCarouselMuted;
    var video = document.getElementById('dr-hrc-video');
    var btn = document.getElementById('dr-hrc-mute');
    if (video) video.muted = hrCarouselMuted;
    if (btn) { btn.textContent = hrCarouselMuted ? '🔇' : '🔊'; btn.setAttribute('aria-label', hrCarouselMuted ? 'Unmute' : 'Mute'); }
  }

  function hrCarouselTrendBadgeHTML(trend){
    if (!trend) return '';
    var icon = trend.label === 'Hot Streak' ? '📈' : trend.label === 'Trending Up' ? '↗️' : trend.label === 'Cooling Off' ? '↘️' : '🧊';
    var cls = trend.tone === 'red' ? 'hot' : trend.tone === 'green' ? 'up' : '';
    return '<span class="dr-hrc-trend ' + cls + '">' + icon + ' ' + escapeHtml(trend.label) + '</span>';
  }

  function renderHRCarouselStatCard(slide){
    var card = document.getElementById('dr-hrc-card');
    if (!card || !slide) return;
    var statChips = [];
    if (slide.hardHitPct != null) statChips.push('<span class="dr-hrc-chip">Hard-Hit ' + slide.hardHitPct.toFixed(1) + '%</span>');
    if (slide.barrelPct != null) statChips.push('<span class="dr-hrc-chip">Barrel ' + slide.barrelPct.toFixed(1) + '%</span>');
    var recentGamesHTML = Array.isArray(slide.recentGames) && slide.recentGames.length
      ? '<div class="dr-hrc-recent" title="Last ' + slide.recentGames.length + ' games, real HR count per game">' +
          slide.recentGames.map(function(hr){ return '<span class="dr-hrc-gamedot' + (hr > 0 ? ' hr' : '') + '">' + (hr > 0 ? hr : '') + '</span>'; }).join('') +
        '</div>'
      : '';
    var matchupLine = slide.nextPitcherName
      ? 'Next: vs ' + escapeHtml(slide.nextPitcherName) + (slide.nextOpp ? ' (' + escapeHtml(slide.nextOpp) + ')' : '')
      : (slide.nextOpp ? 'Next: vs ' + escapeHtml(slide.nextOpp) : '');
    // Real identity of the currently-shown slide, exposed as data attributes so a
    // click handler (or a test) never has to assume which slide is active from
    // navigation history alone.
    card.setAttribute('data-batter-id', String(slide.id));
    card.setAttribute('data-next-pitcher-id', slide.nextPitcherId != null ? String(slide.nextPitcherId) : '');
    card.innerHTML =
      '<img class="dr-hrc-photo" src="' + escapeHtml(hs(slide.id)) + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' +
      '<div class="dr-hrc-info">' +
        '<div class="dr-hrc-name">' + escapeHtml(slide.name) + ' <span class="dr-hrc-team">' + escapeHtml(slide.teamAbbr || '') + '</span></div>' +
        '<div class="dr-hrc-hrline">' + slide.hrs + ' HR' + (slide.hrs !== 1 ? 's' : '') + (slide.gameLabel ? ' · ' + escapeHtml(slide.gameLabel) : '') + '</div>' +
        '<div class="dr-hrc-chips">' + hrCarouselTrendBadgeHTML(slide.trend) + statChips.join('') + '</div>' +
        recentGamesHTML +
        (matchupLine ? '<div class="dr-hrc-next">' + matchupLine + '</div>' : '') +
      '</div>' +
      '<span class="dr-hrc-cta">Full Matchup ›</span>';
  }

  function refreshHRCarouselStatCard(id){
    var slide = hrCarouselSlides[hrCarouselIndex];
    if (slide && slide.id === id) renderHRCarouselStatCard(slide);
  }

  function openHRCarouselMatchup(){
    var slide = hrCarouselSlides[hrCarouselIndex];
    if (!slide) return;
    if (slide.nextPitcherId && typeof window.openMatchup === 'function') {
      window.openMatchup(slide.id, slide.name, slide.nextPitcherId, slide.nextPitcherName);
    } else if (slide.videoUrl) {
      openHRVideoModal(slide.name + ' — ' + slide.hrs + ' HR' + (slide.hrs !== 1 ? 's' : ''), slide.gameLabel || '', slide.videoUrl);
    } else if (slide.webUrl) {
      window.open(slide.webUrl, '_blank', 'noopener,noreferrer');
    } else {
      window.open(slide.gamePk ? ('https://www.mlb.com/gameday/' + slide.gamePk) : 'https://www.mlb.com/video', '_blank', 'noopener,noreferrer');
    }
  }

  // Today's Games strip — quick-glance scoreboard so a hub visitor can see
  // what's happening today without clicking into Baseball first. Reuses the
  // same shared getTodaySchedule cache loadScores() draws from (no extra
  // network cost if the Prediction Center has already loaded), with its own
  // lightweight per-game transform since this only needs team/score/status,
  // not the full win-probability/standings-badge treatment gameCard() builds.
  function hubScoreboardChip(g){
    var isLive = g.status === 'live';
    var isFinal = g.status === 'final';
    var statusHtml = isLive
      ? '<span class="dr-hub-score-status live">' + (g.inning || 'LIVE') + '</span>'
      : isFinal
        ? '<span class="dr-hub-score-status final">FINAL</span>'
        : '<span class="dr-hub-score-status upcoming">' + escapeHtml(g.time) + '</span>';
    var scoreHtml = (g.awayScore != null && g.homeScore != null)
      ? '<span class="dr-hub-score-line">' +
          '<span class="' + (g.awayScore > g.homeScore ? 'dr-hub-score-win' : '') + '">' + g.awayScore + '</span>' +
          '<span class="dr-hub-score-sep">–</span>' +
          '<span class="' + (g.homeScore > g.awayScore ? 'dr-hub-score-win' : '') + '">' + g.homeScore + '</span>' +
        '</span>'
      : '<span class="dr-hub-score-line dr-hub-score-vs">vs</span>';
    return (
      '<button type="button" class="dr-hub-score-chip ' + g.status + '" data-dr-hub-open-baseball="1">' +
        statusHtml +
        '<span class="dr-hub-score-teams">' +
          '<span class="dr-hub-score-team">' + teamLogo(g.awayAbbr) + '<span>' + escapeHtml(g.awayAbbr) + '</span></span>' +
          scoreHtml +
          '<span class="dr-hub-score-team">' + teamLogo(g.homeAbbr) + '<span>' + escapeHtml(g.homeAbbr) + '</span></span>' +
        '</span>' +
      '</button>'
    );
  }

  function renderHubScoreboard(games){
    var section = document.getElementById('dr-hub-scoreboard');
    var strip = document.getElementById('dr-hub-scoreboard-strip');
    if (!section || !strip || !games.length) return;
    strip.innerHTML = games.map(hubScoreboardChip).join('');
    if (!strip.dataset.drHubBound) {
      strip.dataset.drHubBound = '1';
      strip.addEventListener('click', function(e){
        if (e.target.closest('[data-dr-hub-open-baseball]')) {
          var card = document.getElementById('dr-hub-baseball-card');
          if (card) card.click();
        }
      });
    }
    section.style.display = '';
  }

  function loadHubScoreboard(){
    getTodaySchedule('linescore,team').then(function(games){
      var mapped = games.map(function(g){
        var away = g.teams.away, home = g.teams.home;
        var state = g.status.abstractGameState;
        var detailedState = g.status.detailedState;
        var trulyInProgress = detailedState === 'In Progress';
        var linescore = g.linescore || {};
        var inningStr = (trulyInProgress && linescore.currentInning)
          ? (linescore.inningHalf === 'Bottom' ? '▼' : '▲') + ' ' + linescore.currentInning
          : (trulyInProgress ? 'LIVE' : null);
        var isLive = state === 'Live' || trulyInProgress;
        var isFinal = state === 'Final' || detailedState === 'Final' || detailedState === 'Game Over';
        var dt = new Date(g.gameDate);
        return {
          awayAbbr: away.team.abbreviation,
          homeAbbr: home.team.abbreviation,
          awayScore: away.score != null ? away.score : null,
          homeScore: home.score != null ? home.score : null,
          inning: inningStr,
          time: dt.toLocaleTimeString('en-US', {hour:'numeric', minute:'2-digit', timeZone:'America/Chicago'}),
          status: isLive ? 'live' : isFinal ? 'final' : 'upcoming'
        };
      });
      // Live and upcoming first (what a visitor most wants to see at a glance),
      // finals last; stable within each group since the API already returns
      // games in a sensible order.
      var order = { live: 0, upcoming: 1, final: 2 };
      mapped.sort(function(a, b){ return order[a.status] - order[b.status]; });
      renderHubScoreboard(mapped);
    }).catch(function(){});
  }

  // Yesterday's Scores — sidebar section, same chip pattern as Today's Games but for
  // the previous Chicago-time calendar day. Fetched once per page load (yesterday's
  // slate is done and cached hard by the API, no reason to poll it like today's).
  function renderHubYesterdayScores(games){
    var section = document.getElementById('dr-hub-yesterday');
    var strip = document.getElementById('dr-hub-yesterday-strip');
    if (!section || !strip || !games.length) return;
    strip.innerHTML = games.map(hubScoreboardChip).join('');
    if (!strip.dataset.drHubBound) {
      strip.dataset.drHubBound = '1';
      strip.addEventListener('click', function(e){
        if (e.target.closest('[data-dr-hub-open-baseball]')) {
          var card = document.getElementById('dr-hub-baseball-card');
          if (card) card.click();
        }
      });
    }
    section.style.display = '';
  }

  function loadHubYesterdayScores(){
    if (yesterdayScoresLoaded) return;
    yesterdayScoresLoaded = true;
    var yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    var yStr = yesterday.toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
    fetchJSON('https://diamondreport.app/api/v1/schedule?sportId=1&date=' + yStr + '&hydrate=linescore,team&language=en')
      .then(function(data){
        var entry = (data.dates || []).find(function(d){ return d.date === yStr; }) || data.dates && data.dates[0];
        var games = (entry && entry.games) || [];
        games = games.slice().sort(function(a,b){ return new Date(a.gameDate) - new Date(b.gameDate); });
        var mapped = games.map(function(g){
          var away = g.teams.away, home = g.teams.home;
          var state = g.status.abstractGameState;
          var detailedState = g.status.detailedState;
          var isFinal = state === 'Final' || detailedState === 'Final' || detailedState === 'Game Over';
          return {
            awayAbbr: away.team.abbreviation,
            homeAbbr: home.team.abbreviation,
            awayScore: away.score != null ? away.score : null,
            homeScore: home.score != null ? home.score : null,
            inning: null,
            time: '',
            status: isFinal ? 'final' : 'upcoming'
          };
        }).filter(function(g){ return g.status === 'final'; });
        if (mapped.length) renderHubYesterdayScores(mapped);
      }).catch(function(){});
  }

  function bind(){
    var hub = document.getElementById('dr-landing-hub');
    if (!hub) return;

    var modalClose = document.getElementById('dr-hub-news-modal-close');
    var modalOverlay = document.getElementById('dr-hub-news-modal-overlay');
    if (modalClose && !modalClose.dataset.drHubReady) {
      modalClose.dataset.drHubReady = '1';
      modalClose.addEventListener('click', closeNewsModal);
    }
    if (modalOverlay && !modalOverlay.dataset.drHubReady) {
      modalOverlay.dataset.drHubReady = '1';
      modalOverlay.addEventListener('click', closeNewsModal);
    }

    var hrModalClose = document.getElementById('dr-hub-hr-modal-close');
    var hrModalOverlay = document.getElementById('dr-hub-hr-modal-overlay');
    if (hrModalClose && !hrModalClose.dataset.drHubReady) {
      hrModalClose.dataset.drHubReady = '1';
      hrModalClose.addEventListener('click', closeHRVideoModal);
    }
    if (hrModalOverlay && !hrModalOverlay.dataset.drHubReady) {
      hrModalOverlay.dataset.drHubReady = '1';
      hrModalOverlay.addEventListener('click', closeHRVideoModal);
    }

    var leaderModalClose = document.getElementById('dr-hub-leader-modal-close');
    var leaderModalOverlay = document.getElementById('dr-hub-leader-modal-overlay');
    if (leaderModalClose && !leaderModalClose.dataset.drHubReady) {
      leaderModalClose.dataset.drHubReady = '1';
      leaderModalClose.addEventListener('click', closeLeaderModal);
    }
    if (leaderModalOverlay && !leaderModalOverlay.dataset.drHubReady) {
      leaderModalOverlay.dataset.drHubReady = '1';
      leaderModalOverlay.addEventListener('click', closeLeaderModal);
    }

    var headlineModalClose = document.getElementById('dr-hub-headline-modal-close');
    var headlineModalOverlay = document.getElementById('dr-hub-headline-modal-overlay');
    if (headlineModalClose && !headlineModalClose.dataset.drHubReady) {
      headlineModalClose.dataset.drHubReady = '1';
      headlineModalClose.addEventListener('click', closeHeadlineModal);
    }
    if (headlineModalOverlay && !headlineModalOverlay.dataset.drHubReady) {
      headlineModalOverlay.dataset.drHubReady = '1';
      headlineModalOverlay.addEventListener('click', closeHeadlineModal);
    }

    var sideToggle = document.getElementById('dr-hub-side-toggle');
    if (sideToggle && !sideToggle.dataset.drHubReady) {
      sideToggle.dataset.drHubReady = '1';
      sideToggle.addEventListener('click', toggleSideContent);
    }

    document.addEventListener('keydown', function(e){
      if (e.key === 'Escape') { closeNewsModal(); closeHRVideoModal(); closeLeaderModal(); closeHeadlineModal(); }
    });

    var baseballCard = document.getElementById('dr-hub-baseball-card');
    if (baseballCard && !baseballCard.dataset.drHubReady) {
      baseballCard.dataset.drHubReady = '1';
      baseballCard.addEventListener('click', function(){
        setActiveSport('MLB');
        hideHub();
        if (!hashIsGamepick()) {
          try { window.location.hash = 'gamepick=game'; } catch(e) {}
        }
        if (typeof window.showGamePickPane === 'function') window.showGamePickPane('game');
      });
    }

    document.querySelectorAll('.dr-hub-sporttab').forEach(function(tab){
      if (tab.dataset.drHubReady) return;
      tab.dataset.drHubReady = '1';
      tab.addEventListener('click', function(){ setActiveSport(tab.getAttribute('data-sport')); });
    });

    // Real and live -- mirrors the baseball card's real navigation into its
    // board instead of staying on the hub.
    var nflCard = document.getElementById('dr-hub-nfl-card');
    if (nflCard && !nflCard.dataset.drHubReady) {
      nflCard.dataset.drHubReady = '1';
      nflCard.addEventListener('click', function(){
        setActiveSport('NFL');
        hideHub();
        if (!hashIsGamepick()) {
          try { window.location.hash = 'gamepick=nfltd'; } catch(e) {}
        }
        if (typeof window.showGamePickPane === 'function') window.showGamePickPane('nfltd');
      });
    }
    // NBA still has no real board behind it -- stays on the hub and only
    // filters news, unlike the MLB/NFL/WNBA cards.
    var nbaCard = document.getElementById('dr-hub-nba-card');
    if (nbaCard && !nbaCard.dataset.drHubReady) {
      nbaCard.dataset.drHubReady = '1';
      nbaCard.addEventListener('click', function(){ setActiveSport('NBA'); });
    }

    // Real and live -- mirrors the baseball card's real navigation into its
    // board instead of the "soon" dead end.
    var wnbaCard = document.getElementById('dr-hub-wnba-card');
    if (wnbaCard && !wnbaCard.dataset.drHubReady) {
      wnbaCard.dataset.drHubReady = '1';
      wnbaCard.addEventListener('click', function(){
        setActiveSport('WNBA');
        hideHub();
        if (!hashIsGamepick()) {
          try { window.location.hash = 'gamepick=wnbapts'; } catch(e) {}
        }
        if (typeof window.showGamePickPane === 'function') window.showGamePickPane('wnbapts');
      });
    }

    var logo = document.getElementById('dr-header-logo');
    if (logo && !logo.dataset.drHubReady) {
      logo.dataset.drHubReady = '1';
      var goToHub = function(){
        try { window.location.hash = ''; } catch(e) {}
        showHub();
      };
      logo.addEventListener('click', goToHub);
      logo.addEventListener('keydown', function(e){
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); goToHub(); }
      });
    }

    if (hashIsGamepick()) hideHub(); else showHub();

    var oldShowPane = window.showGamePickPane;
    if (typeof oldShowPane === 'function' && !oldShowPane.__drHub) {
      var wrapShowPane = function(p){ hideHub(); return oldShowPane.apply(this, arguments); };
      wrapShowPane.__drHub = true;
      window.showGamePickPane = wrapShowPane;
    }

  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, { once:true });
  else bind();

  window.addEventListener('hashchange', function(){
    if (hashIsGamepick()) hideHub(); else showHub();
  });
})();

// ── Fixed-header overlap fix ────────────────────────────────────────────
// .header has 11 separate rule blocks scattered across styles.css (the same
// kind of "years of conflicting per-breakpoint !important overrides" mess
// already documented elsewhere in this file), and the cascade currently
// resolves to position:fixed on every breakpoint -- which pulls the header
// out of document flow with nothing compensating for it below, so the top
// of the page (the Featured Player card's footer, in one real report) sits
// hidden behind it. Rather than add a 12th competing .header{} rule and risk
// interacting unpredictably with the other eleven, this measures the header's
// actual rendered height at runtime and reserves that much space -- correct
// regardless of which of the existing rules ends up winning, and a no-op if
// a future edit ever makes the header participate in normal flow instead
// (sticky/static), since it only applies the compensation while the header
// is actually computed as position:fixed.
(function () {
  function fixHeaderOverlap() {
    var header = document.querySelector('.header');
    if (!header) return;
    var isFixed = window.getComputedStyle(header).position === 'fixed';
    // setProperty(..., 'important') rather than the plain .style shorthand --
    // one of the eleven .header-adjacent rules is `body{padding:0!important}`
    // (mobile media query), which silently wins over a non-!important inline
    // style regardless of the inline style's usual specificity advantage.
    if (isFixed) document.body.style.setProperty('padding-top', header.offsetHeight + 'px', 'important');
    else document.body.style.removeProperty('padding-top');
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fixHeaderOverlap, { once: true });
  else fixHeaderOverlap();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ if (typeof window.drInitFilterScrollHints === 'function') window.drInitFilterScrollHints(); }, { once: true });
  else if (typeof window.drInitFilterScrollHints === 'function') window.drInitFilterScrollHints();
  var resizeTimer = null;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(fixHeaderOverlap, 150);
  });
})();
